SWITCH_KW = ["换一台", "换一个", "换台", "换个", "别的", "其他", "还有吗", "还有别",
             "不要这台", "不想要", "不喜欢", "太贵", "便宜点", "再看看", "没有别的"]

# 🔴 本轮的模型路由结果（2026-11-16 毕设架构反转）。
#    `_run` 开头写入，函数内所有路由点读取；下一轮被覆盖。
#    None = 意图层不可用，一切路由退回词表兜底。
_LAST_ROUTE = [None]

# 「别的」被当换台信号会误伤：「它比别的便宜多少」「别的品牌都贵」——
# 这是在比较，不是要换台。实测 2026-11-11：用户问"帮我算一下它比别的便宜多少"，
# 系统直接换了台，还没解释为什么不给算。
SWITCH_NOT = re.compile(
    r"(比|和|跟|与|相对)\s*(别的|其他|其它)"
    r"|(别的|其他|其它)\s*(品牌|牌子|机型|厂商|家)"
    # 「别的条件不变」「其他要求不变」——这是在确认条件，不是要换台。
    # 实测 2026-11-11（第五轮）：这句被判成换台，返回"都看过了"，
    # 用户只是在确认，系统却说没货了。
    r"|(别的|其他|其它)\s*(条件|要求|配置|需求|参数)"
    r"|(条件|要求|配置|需求|参数)\s*(都)?\s*不变")
# 明确要求比较的说法
COMPARE_KW = ["便宜多少", "差多少", "贵多少", "相差", "对比", "比较一下",
              "哪个更", "哪个便宜", "哪个划算", "比一下"]

# ── 「放宽预算」（2026-11-13 加）────────────────────────────────────
# 真实事故（用户报的，日志 chat-2026-11-13 第 71→72 条）：
#   第 71 条 exhausted：「这个条件下库里就这几台，都看过了。
#                        要不放宽预算，或者换个品类我再看看？」
#   第 72 条 用户答：「可以，放宽预算推荐几台」
#   → 系统把**同一台战 66 又推了一遍**（槽位 budget 还是 7000，
#     seen 里那三台也没被排除）。
#
# 这是**系统自己提的建议，然后自己没接住**——比用户随口一说更糟：
# 用户照着提示做了，得到的却是原地打转，之后就不会再信那些建议了。
#
# 所以「放宽」必须变成**具体动作**，不能只是听懂了一个词。
RELAX_BUDGET = re.compile(
    r"放宽.{0,4}预算|预算.{0,4}(放宽|提高|加|涨|多点|高点|上来|抬)|"
    r"(加|多|再)(给|来)?(点|些|些钱|点钱|点预算)|不差钱|预算不(是问题|限)|"
    r"可以(加|多)(点|些)|往上(加|走|提)|提(高|一下)预算|"
    # 「放宽」自己也能独立成句 —— 上一轮系统问的是「要不要放宽预算」，
    # 用户完全可能只回「放宽吧」「再放宽点」，不带"预算"两个字。
    # （2026-11-13 回归测试 R4 抓到的：第二次说"再放宽点"没被认出，
    #  预算停在 8000 没动。）
    r"放宽|放宽松|"
    # 「不用给我省」「别省着」—— 双重否定，意思是"可以多花"。
    # 2026-11-13 实测：这句原来两条路都接不住（拒绝词表误伤、放宽词表没收录），
    # 最后靠模型猜对的 —— 但这类说法是封闭的，规则该确定地认得。
    # 判据要点：必须是「省」这个动词，不能只写"不用"（见 budget_intent 的说明）。
    r"不用(给我)?省|别(给我)?省|不用省着")

# 放宽多少：一次上调 20%，且**至少**跨过一个 1000 的档位。
# 为什么不是固定加 1000：预算 12000 加 1000 只多 8%，几乎等于没变；
# 预算 4000 加 1000 是 25%，已经很多。按比例才是一致的"再宽一点"。
# 为什么要"至少跨档"：7000×1.2=8400 和 7000 落在同一个"7000-8000"档里
# 不够明显，跨到 8000 以上才真的打开新区间。
RELAX_STEP_RATIO = 0.20


def relaxed_budget(budget):
    """把预算放宽一档。返回新的预算（int，整千）。

    `budget` 是 99999（用户没说预算）时**不放宽** —— 那本来就是全家桶，
    再放宽没有意义，硬加只会把文案写得更奇怪。

    结果一定是整千：价格筛选是按千分档的，返回 2001 这种数会让
    「7000-8000 有几台」和「8000 以内」两处算出的口径对不上。
    """
    if not budget or budget >= 99999:
        return budget
    up = int(round(budget * (1 + RELAX_STEP_RATIO) / 1000.0) * 1000)
    if up <= budget:
        # +20% 后还被四舍五入抹平（预算很小时会发生），退化成"往上跨一档"。
        # 这里也必须落在整千上，不能写 budget+1000（1001 → 2001 就不整千了）。
        up = (budget // 1000 + 1) * 1000
    return up


def is_relax_budget(text):
    """这句是不是在答应「放宽预算」。"""
    return bool(RELAX_BUDGET.search(text or ""))

# 「淘宝上是不是更便宜」「这个在淘宝卖多少」「两个平台差多少钱」
# —— 这类是在问**别的渠道**的价格，而库里只有京东一家的价。
#
# 实测 2026-11-11（淘宝数据入库后必测的一项）：不设这道闸，模型会直接编：
#   Q「这个在淘宝卖多少」→ A「这台在**淘宝**到手价是 5100 元」  ← 把京东价冒充淘宝价
#   Q「淘宝上是不是更便宜」→ A「价格往往比 5100 元**更高**」     ← 凭空给行情判断
# 两条都过了 untraceable_numbers 校验：因为它没编数字，只是给数字换了主语。
# 数字校验管不到"数字是对的、出处是假的"，必须单独有一道判据。
#
# 分辨力对照（2026-11-11，20 条必须拦住 + 22 条不能误杀 → 42/42）：
#   拦住：淘宝上是不是更便宜 / 这个在淘宝卖多少 / 两个平台差多少钱 / 百亿补贴有这个吗
#   不误杀：多少钱 / 贵不贵 / 便宜点的 / 差多少性能 / 这个价位有什么 / 太贵了便宜点
SRC_ASK = re.compile(
    r"(淘宝|天猫|京东|拼多多|闲鱼|官网|旗舰店|自营|百亿补贴|国补)"
    r".{0,10}(多少钱|卖多少|什么价|几块|便宜|贵|价格|报价|多少|划算|合适|靠谱|有货|怎么样|有没有|有这个)"
    r"|(多少钱|卖多少|什么价|价格|报价|比|有没有|有这个).{0,8}(淘宝|天猫|京东|拼多多|闲鱼|官方|百亿补贴)"
    r"|(哪个平台|哪家|哪个渠道|哪个店|两个平台|全网|这边|那边|两边|两家|各平台)"
    r".{0,10}(便宜|贵|划算|低|高|差多少钱|差价|差多少|价格)"
    r"|(换|去|在|上).{0,4}(淘宝|京东|拼多多|天猫).{0,4}(买|下单|看)")

# 库里实际有价格的渠道。淘宝数据虽然已入库，但它是别人爬的、口径只有 41/145 条可信，
# 且**无法与京东做同配置匹配**（见 match_sources.py：剩下的全是对不上的）。
# 所以对外仍然只说"京东有价"，淘宝只在明确要求时作参考价出现。
PRICED_SOURCES = {"京东"}

# ---- 概念错配：把库里有的数字贴上库里没有的标签 --------------------------
# verify_answer() 只校验「数字能不能在语料里找到」，管不到「数字被贴了什么标签」。
# 实测 2026-11-11（第六轮对抗）：
#   Q「这台出厂价是多少」→ A「出厂价是 6000 元」
#   6000 这个数**确实**在语料里（它是原价），所以数字校验完全通过 ——
#   但原价是零售标价，出厂价是厂商出厂成本，两个东西。
#   用户拿着"出厂价 6000"去砍价，砍的是个不存在的价。
# 同理「京东销量第一」「在天猫卖得最好」—— 库里连销量字段都没有。
#
# 分辨力对照（2026-11-11：16 条必须拦住 + 16 条不能误杀 → 32/32）
#   拦住：出厂价 / 拿货价 / 成本价 / 批发价 / 内部价 / 员工价 / 二手价 / 回收价
#         销量第一 / 卖得最好 / 排名第几 / 好评率 / 回购率
#   不误杀：多少钱 / 原价多少 / 国补能补多少 / 到手价 5100 吗 / 便宜点 / 值不值
PRICE_LABEL = re.compile(
    r"(出厂价|成本价|进货价|拿货价|批发价|渠道价|代理价|经销价|供货价"
    r"|底价|内部价|员工价|清仓价|甩卖价|爆款价|活动价|预售|定金|尾款"
    r"|二手价|回收价|以旧换新价|折旧价|折价|残值"
    # 「以旧换新能抵多少」「旧机能抵几个钱」—— 抵价也是库里没有的价签
    r"|(以旧换新|旧机|老机器|换新).{0,6}(抵|能抵|值多少|卖多少|折多少)"
    r"|抵多少|能抵多少|抵扣多少|折算多少)")

RANK_CLAIM = re.compile(
    r"(销量|卖得|卖的最|卖得最|销量榜|热销|畅销|销冠|第一名|排行|排名|榜首"
    r"|口碑最好|评价最好|最受欢迎|最多人买|回购率|好评率)")

# ---- 「最 X」排序断言：库里能核的放，核不了的拦 ---------------------------
# 实测 2026-11-11（第六轮对抗）：「这个价在市场上算什么水平」→
#   「这台联想小新 Air14 在轻薄本里算**最贵的一台**，但比库内最贵的 6799 元便宜不少」
# 两处都错：① 5100 在 10 台里排第 3，不是最贵；② 同一句里说"最贵"又说"比最贵的便宜"。
# _overspec() 完全没覆盖这类（它只管"这个价位能拿到 2.5K 屏"这类配置断言）。
#
# 难点：「最」本身不一定是错 —— 「全库最便宜的就是它」是**可核实且正确**的。
# 只用文案判会把合法陈述一起拦掉（实测误抓 3 条），那是判据没分辨力。
# 所以分两层：
#   可核实维度（贵/便宜/轻/重、价格最高最低）→ 交给数据层核对，这里不拦
#   不可核实维度（好/强/值/划算/耐用/省电/屏幕素质/噪音）→ 库里根本没这字段，一律拦
SUPER_SEG = re.compile(
    r"最[^，。；！？\n]{0,10}"
    r"|排名第[一二三四五零]|数一数二|首屈一指|位居第一|排在第一|销量第一|全库第一")

SUPER_UNCHECKABLE = ("好", "强", "快", "值", "划算", "耐用", "省电", "安静",
                     "厚", "薄", "优", "手感", "高", "低")
SUPER_CHECKABLE = ("贵", "便宜", "轻", "重")

# 说「价格本身最高/最低」是可核实的（库里有 price 字段）。各种说法要列全。
PRICE_LOWHIGH = re.compile(
    r"(最高价|最低价|价格最高|价格最低|价位最高|价位最低"
    r"|到手价最高|到手价最低|售价最高|售价最低|全库最高|全库最低|价最低|价最高)")

# 带免责的说法等于把范围限定住了，不算过度断言
SUPER_HEDGE = re.compile(r"(之一|按库内|按本库|库内|在本库|以库里|库里只有)")


def super_claims(text):
    """找出「最 X」里**库里无法核实**的那些排序断言。

    可核实的（价格最贵/最便宜/最轻/最重、价格最高最低）不在这里拦 ——
    它们的对错要用数据判，交给 verify_answer / audit_data 那一层。
    """
    out = []
    for m in SUPER_SEG.finditer(text):
        seg = m.group(0)
        ctx = text[max(0, m.start() - 8):m.end() + 10]
        if SUPER_HEDGE.search(ctx):
            continue
        if PRICE_LOWHIGH.search(seg) or PRICE_LOWHIGH.search(ctx):
            continue
        hit = None
        # 按词长优先：先看长的词，避免「便宜」被「薄」抢走
        for w in sorted(SUPER_UNCHECKABLE + SUPER_CHECKABLE, key=len, reverse=True):
            if w in seg:
                hit = w
                break
        if hit is None:
            if re.search(r"排名第[一二三四五零]|数一数二|首屈一指|位居第一|排在第一|销量第一", seg):
                out.append(seg.strip())
            continue
        if hit in SUPER_UNCHECKABLE:
            out.append(seg.strip())
    return out

# ---- 意图标签（classify_intent 的返回值）----
# 用字符串而不是枚举，日志里直接可读，排查时不用查表。
INTENT_ASK_CURRENT = "ask_current"        # 问「这台」怎么样
INTENT_REFUSE_SWITCH = "refuse_switch"    # 不要这台 / 要换台
INTENT_STATE_RANGE = "state_range"        # 说价位段 / 品类 / 条件
INTENT_STATE_NEW_NEED = "state_new_need"  # 提新需求
INTENT_UNKNOWN = "unknown"                # 没听清，需要反问
INTENT_LIST_OTHERS = "list_others"        # 把其余候选列出来（2026-11-12 新增）
# 🔴 2026-11-21 新增：**数据分析**（毕设题目要求）
#
#    用户问的是**整个库的统计特征**，不是"给我推荐一台"：
#      「有多少台有独显」「各品牌售后评分对比」
#      「8000以内平均多重」「32G内存的价格分布」「性能最强的五台」
#
#    原来这些都走 state_range → clarify → 回一句"是笔记本还是台式？"
#    （实测：5 个分析类问题，4 个被这么打回）。
#
#    为什么必须单独一个意图：它的**回答形态完全不同** ——
#    推荐是"一台机器 + 理由"，分析是"一个数/一张表 + 样本量"。
#    走推荐路径必然答非所问。
INTENT_ANALYZE = "analyze"                # 对整个库做统计分析

# 「把其余推荐的列出来」—— 这是要清单，不是要换台，也不是追问某台细节。
# 🔴 实测 2026-11-12：用户说「其余推荐的给我列举出信息我看看」，
#   系统走了一遍 build_recommendation + compose，把首位那台**又讲了一遍**，
#   另外两台一个字没提。用户原话："我让他把其他推荐的列举出来，他还是推荐同一台"。
#   这不是模型的问题 —— 代码里压根没有"列清单"这条路。
# ⚠️ 和 "还有别的吗" 必须分开：后者是**换一台**（SWITCH_KW），前者是要**看全部**。
LIST_OTHERS_PAT = re.compile(
    r"(其余|其他|其它|剩下|别的|另外|还有).{0,8}(推荐|候选|机型|机器|选项|几台|哪些)"
    r"|(列举|列一下|列出来|罗列|都列|一条条列)"
    r"|(分别|逐个).{0,6}(说|列|介绍)"
    # 🔴 2026-11-13 晚（eval_behavior 抓到）：「还有几个选择一次说完」「把候选都给我看看」
    #    两句都比对失败 —— 差的是「几个/候选」和动词的搭配，上面第一条要求
    #    "几个"前面紧跟"其余/还有"，而"还有几个选择"中间夹了"选择"。
    #    判据放宽成"出现数量词 or 候选词 + 看/说/给"：
    #      数量词（几个/几台/多少）→ 用户认为有很多台，要全部看到
    #      候选/机型/清单 + 看/说/列 → 同上
    r"|(还有|再有|再给|能看|想看|都给我).{0,6}(几个|几台|多少|别的|其他)"
    r"|(候选|机型|机器|选项|清单).{0,4}(都|全|看|说|列|给)")

# 「还有别的品牌吗」不是"换台"，也不是没听懂 —— 是**换品牌**（M04 回归）。
BRAND_SWITCH = re.compile(r"(别的|其他|其它|换个|换一个|还有).{0,4}(品牌|牌子)")

# 「别的品牌是不是都更贵」—— 是在**问价**，不是要求换品牌。
# 实测 2026-11-12（attack5 X09）：这句命中 BRAND_SWITCH，把当前品牌整组排除，
# 静默换推了另一台。区分判据：带价格比较词的"别的品牌"句是比价，不排除品牌。
BRAND_PRICE_Q = re.compile(r"(更?贵|更?便宜|价格|差价|多少钱)")

# 明确要"把几台摆一起看"。
# 🔴 2026-11-12 死循环：6f 的反问里给了「① 把它和另外两台放一起比」这个选项，
#   但代码里**没有对比能力**，用户点① → 又回到同一句反问 → 再点 → 再问，卡死。
#   给了选项就必须能接住，否则不给。
COMPARE_ASK = re.compile(
    r"(对比|比较|比一下|比一比|放一起比|摆一起|哪个好|哪个更|怎么选|二选一|三选一)")

# 指向「正在讨论的这台」的说法。实测 2026-11-11 16:27：
# 用户说「打游戏这个合适吗，偶尔打打游戏」，被当成「我要游戏本」，
# 直接把 cat 改成 gaming、推了台 6799 的天选 7 —— 他问的是刚才那台。
# 根因不是模型听不懂，是系统里没有「当前在聊哪一台」这个状态。
CURRENT_REF = ["这个", "这台", "这款", "这部", "这一台", "它", "那台", "那个",
               "刚才", "刚刚", "你推的", "你说的", "你推荐", "刚推", "上面那",
               "这价格", "那价格"]

# 上面那个词表是**列举式**的，漏一个说法就整类失灵 —— 实测 2026-11-11（第七轮）：
#   「这台保修几年」→ followup  ✔
#   「这机器保修几年」→ clarify  ✘ 反问「是笔记本还是台式？」
# 区别只是「台」换成「机器」。用户已经聊了五轮这台机器，被一个问题打回第一句。
# 漏判清单实测：这机器 / 这机子 / 这笔记本 / 这电脑 / 这本子 / 该机型 / 这机 /
#               这玩意儿 / 这货色 / 这型号
# ⇒ 不能靠加词补，要按**构词**匹配：「这/那/该/此 +（量词）+ 电脑类名词」。
COMPUTER_NOUN = r"(?:机器|机子|机型|型号|笔记本|本子|电脑|机|货色|玩意儿|产品|设备)"
CURRENT_REF_PAT = re.compile(
    r"(?:这|那|该|此)(?:个|款|台|部|只|种)?\s*" + COMPUTER_NOUN)

# 「我说的就是…那一台」「就是这台」「指的就是它」—— 用户在**确认**，不是提新需求。
# 这类句子里「推荐/说」这些词会出现，但语义是锁定，不是索取。见 refers_to_current。
CONFIRM_CURRENT = re.compile(
    r"(就是|正是|指的?是|说的?是|问的?是|要的?是)\s*"
    r"(?:你(?:刚才|刚刚)?)?(?:给我)?(?:推荐|说|讲|推)?(?:的)?\s*"
    r"(?:这|那|它|上面|刚才|刚刚)"
    r"|就是这台|就是这款|就是它")

# 「这个价位 / 这个预算 / 这个条件」是在说范围，不是指向某一台。
# 不加这条，「我要打游戏，这个价位有什么」会被当成追问，永远换不了需求。
#
# 但「这个价」单独出现时**不一定是范围** —— 实测 2026-11-11（第六轮对抗）：
#   「这个价在市场上算什么水平」被这里判成"说范围"，于是没走"问当前这台"的分支，
#   一路掉进 recommend。recommend 里模型看到的是"这是榜首"，就编了
#   「在轻薄本里算最贵的一台」—— 它以为榜首=最贵。
# 区分办法：后面**没跟名词**（没有"位次/东西/机型"）时，它是"这台的价格"，指向当前。
#   「这个价在市场上算什么水平」→ 问这台     ← 不能判成范围
#   「这个价位有什么」            → 问范围     ← 必须判成范围
#   「这个价格划算吗」            → 问这台
# 同理「这个机器 / 这个机型 / 这个型号」是**指向某台机器**，不是范围。
# 上一版把「机」也写进了否定前瞻，`(这个|那个)(价|款|机)(?!...)`，
# 结果「这个机器怎么样」被吃成「这个机」→ 判成说范围 → 问这台的路整条断掉。
# 实测 2026-11-11（第七轮）：这个机器 / 这个机型 / 那个机子 全部判错。
# 修法：把「价」和「款/机」拆开 —— 「价」才需要在后面区分"这台的价格"和"这个价位"。
REF_NOT_CURRENT = re.compile(
    r"(这个|那个)(价位段|价位|价格段|预算|钱|档位|档次|段位|条件|需求|情况|品类|类型)"
    # 「这个价…」：后面跟"格/位"等名词性成分才算范围
    r"|(这个|那个)价(?:格)?(?:段|位|档|区间)"
    # 「这个款/机」只有在后面接范围词时才算范围
    r"|(这个|那个)(款|机|个机)(?:型|式)?(?:段|位|档|区间)"
    # 「这个价格的机器」「这种机器的价格区间」—— 说范围，不是在指某一台。
    # 实测 2026-11-11（第七轮压测）：放宽 CURRENT_REF_PAT 之后这两类被误抓成"问本台"。
    r"|(这个|那个|这种|那种)(价格|价位|档次|价位段)(?:的)?(?:机器|机型|本子|电脑|本)"
    r"|(这种|那种)(机器|机型|电脑|本子|本)(?:的)?(?:价格|价位|区间|档次|段位)"
    r"|(这个|那个)(机器|机型|电脑|本子|本)(?:的)?(?:价格区间|价格范围|价位区间)"
    # 「这个型号和那个型号哪个好」—— 两台横向比，不是在问当前这一台。
    r"|(?:这|那)(?:个|款|台|种)?\s*" + COMPUTER_NOUN + r"\s*(?:和|与|跟|对比|比)\s*"
    r"(?:那|这|另)(?:个|款|台|种)?",
)

# 明确否掉某个用途（要合并 purpose 时才用得着）
PURPOSE_DROP = {"gaming": ["不玩", "不打游戏", "不游戏", "游戏不考虑", "不需要游戏"],
                "design": ["不做设计", "不学设计", "不搞设计"]}

NEGATE_CURRENT = ["不行", "不合适", "不适合", "不要了", "换掉", "算了"]

# 上面这组词原来是 `any(k in text ...)` 判的。中文里**疑问句把否定词包在中间**，
# 字面包含就判否，会把「问」当成「否」—— 实测 2026-11-11（第七轮）：
#   「这台行不行」     → 命中「不行」→ 判成用户否掉这台 → 推一台新的   ✘
#   「这台不合适吗」   → 命中「不合适」→ 同上                          ✘
#   「这个性能行不行」 → 同上                                          ✘
# 用户只是在问「行不行」，突然被塞了台别的机器 —— 这是最容易被骂"听不懂人话"的一类。
#
# 判据分两步：先认出疑问句式，剩下的才算真否定。
#   ① A不A 正反问：「行不行」「合适不合适」「够不够」「好不好」
#   ② 句末疑问语气：「…吗 / 嘛 / 么 / 呢」，或整句以问号收尾
_NOTA_Q = re.compile(r"([\u4e00-\u9fa5]{1,3})\s*不\s*\1")
_Q_TAIL = re.compile(r"[吗嘛么呢]\s*[？?]?\s*$|[？?]\s*$")


def _negates_current(text):
    """这句是不是在**否掉**当前这台（不是问它行不行）。

    歧义如实说明：「这台不合适吗」两种读法都通（真问 / 反问式否定）。
    这里选**当疑问**处理 —— 判错方向时，用户还能补一句「就是不行」；
    反过来判成否定就直接换台，用户会觉得系统自己瞎猜。
    """
    if not any(k in text for k in NEGATE_CURRENT):
        return False
    if _NOTA_Q.search(text):
        return False
    if _Q_TAIL.search(text):
        return False
    return True

# 「还能打游戏吗」这种没有指代词，但显然是在问刚才那台。
# 判据：带匹配度疑问 + 不带「我要/想买」这类需求表达 + 没在说范围。
DEMAND_WORDS = ["我要", "我想", "我想要", "想买", "想换个", "给我推荐", "帮我推荐",
                "买个", "换一个", "再推荐"]

# 「保修几年」这种没有指代词的追问，只有在**没在提新条件**时才算问当前这台。
# 阻止误伤的例子：
#   「要 32G 内存，多重无所谓」   ← 在提新条件，不是问当前这台的重量
#   「预算 8000 的有没有保修好的」← 在提需求
#   「推荐个轻的，多重都行」      ← 同上
NEW_DEMAND_NOUN = ["内存", "硬盘", "固态", "预算", "品牌", "推荐", "要买", "想买",
                   "买一台", "买一个", "换个", "换一台", "还有别的", "别家",
                   "同价位", "这个价位", "其他",
                   # 「这个机器的**升级版/下一代/新款**」——库里没有这种机器，
                   # 是在提一个新东西，不是问当前这台。实测 2026-11-11（第七轮）。
                   "升级版", "升级款", "下一代", "新款", "继任", "后继"]

# 需求**对象**：说了这些词就是在说"我要什么样的机器"，不是在问手上这台。
# 和 NEW_DEMAND_NOUN 的区别：那个偏"属性/配置"（内存、预算、品牌），
# 这个是"品类"（游戏本、轻薄本、台式机）。
# 实测 2026-11-11（意图单测）：「我要一台游戏本」只有需求动词、没命中属性词，
# 掉进 unknown —— 用户说了要游戏本，系统没听见。
NEED_OBJECT_NOUN = ["游戏本", "轻薄本", "办公本", "全能本", "设计师本", "工作站",
                    "台式", "主机", "裸机", "笔记本", "一体机", "迷你主机",
                    "内存条", "固态硬盘", "硬盘", "显示器", "外设"]


# 机型名里的**泛词/词缀**：单独出现说明不了是哪台。
#
# 🔴 为什么必须有这张表（2026-11-11，v1~v6 六版都栽在"切词"上）：
# 前几版用「特征串长度 >= 3」当准入门槛，逻辑是"太短的词太泛"。但这条阈值两头都不对：
#   · 「小新」只有 2 个字，却**确实**指向一台机器 → 被误杀（「联想小新16如何」MISS）
#   · 「book」有 4 个字母，纯属词缀 → 放进来，「ThinkBook 14 怎么样」凑出
#     book/pro/14 三分，误匹配到 Redmi Book Pro 14（用户问 A、系统答 B）
# 长度和"泛不泛"没有关系，所以按词表判。
#
# 🔴 更关键的教训（v6 → v7）：**不要去切词**。
# v6 把机型名切成 token 再比，切出来的东西全不对：
#     Redmi Book Pro 14  → ['14']        品牌被当泛词剥掉，只剩个 14
#     DDR5 16G 单条      → [..., '516']  数字连读切出无意义的 516
#     戴尔灵越 15        → ['灵越','15'] 15 和"灵越"是两个 token，各自都太泛
# 切词这一步本身就不可逆地丢了信息。改成**别名法**：不拆原串，而是枚举
# "用户可能怎么称呼它"，每个别名都是一个完整子串，命中即认。
GENERIC_TOKENS = {
    # 英文词缀/泛称
    "book", "pro", "plus", "max", "air", "pad", "note", "mate", "magic",
    "think", "series", "edition", "gen", "gt", "se", "ultra", "mode",
    # 中文泛称
    "笔记本", "电脑", "游戏本", "轻薄本", "办公本", "全能本", "整机",
    "战斗版", "系列", "款", "代", "标准版", "高配", "低配",
    # ⚠️ 「锐龙版 / 酷睿版 / 英特尔版」**不是泛词，不能放进来**（2026-11-12）：
    #   它们是用户真正用来区分机型的词 —— 「暗影精灵 11」有锐龙版和酷睿版两代，
    #   价格差 4000 多。把它们当泛词剥掉，两条分数就一样了，只能弃权反问；
    #   而用户明明已经说清要哪一版。
}


def _norm(s):
    """匹配用的规范化：小写、去所有空白、全角括号转半角。"""
    s = (s or "").lower()
    s = s.replace("（", "(").replace("）", ")")
    s = re.sub(r"\s+", "", s)
    return s


def _model_aliases(name, brand):
    """枚举「用户可能怎么称呼这台机器」→ 返回别名字符串列表。

    🔴 为什么不切词（见 GENERIC_TOKENS 的注释）：
    切词不可逆地丢信息。改成**保留原串**、只做删减，生成几个完整的候选串，
    每个候选串都是"用户真的会打出来的一截"。

    以「联想小新 Air15 2026」为例，生成：
      联想小新air152026   （全名，去空格）
      小新air152026       （去品牌）
      小新air15           （去年份）
      小新air15           （去泛词）
      小新                （去型号块，只留中文主体）
    ∪「联想小新16」生成的小新 → 两台都命中"小新"，靠完整度打分区分。

    ⚠️ 别名必须**够长才有意义**。`小新` 单独出现时两台都中 —— 这不是 bug，
    交给打分环节：谁命中的别名更长、更完整，就是谁。
    """
    n = _norm(name)
    if not n:
        return []
    # 🔴 先剥掉括号里的配置说明（2026-11-12）。
    #   采集层的名字长这样：「暗影精灵 11（2026，Ultra7-251HX/RTX5060）」
    #   `_norm` 只转全角括号、不删内容，于是「只留中文主体」那步得到的是
    #   `暗影精灵，`（逗号是括号里的），永远匹配不上用户说的「暗影精灵」。
    #   型号本体在括号外 —— 括号里放的是配置，删掉不影响识别。
    n = re.sub(r"\([^)]*\)", "", n).strip("，,·、 ")
    if not n:
        return []
    alts = {n}

    # 去品牌
    nb = n
    if brand:
        nb = n.replace(_norm(brand), "")
        if nb:
            alts.add(nb)
    # 去年份
    for base in list(alts):
        y = re.sub(r"20[12]\d", "", base)
        if y and y != base:
            alts.add(y)
    # 去泛词后缀（迭代两轮，处理 "pro"+"15" 这类叠加）
    # 🔴 2026-11-12 实测漏了一类：「无界 14X」和「无界 14」是**两台不同的机器**。
    #   去泛词那步会把 14X 尾部的 x 当噪声剥掉（GENERIC_TOKENS 里有 "max" 之类，
    #   迭代两轮后单字母 x 也可能被切出来），于是「无界14x」的别名退化成「无界14」，
    #   两条同分 → 弃权 → 用户点名称型号反而认不出。
    #   ⇒ **数字后紧跟的单个字母（x / s / k）是型号后缀，不是泛词**，先保护起来。
    _suffix_guarded = set()
    for base in alts:
        if re.search(r"\d[a-z]$", base):
            _suffix_guarded.add(base)
    for _ in range(2):
        for base in list(alts):
            for g in GENERIC_TOKENS:
                if base.endswith(g) and len(base) - len(g) >= 2:
                    cand = base[:-len(g)]
                    if cand in _suffix_guarded:
                        continue        # 剥完正好落在一个受保护的型号后缀上 → 不剥
                    alts.add(cand)
                if base.startswith(g) and len(base) - len(g) >= 2:
                    alts.add(base[len(g):])
    # 只留中文主体（小新 / 天选 / 隐星 / 暗影精灵）
    for base in list(alts):
        zh = re.sub(r"[a-z0-9()（）+\-.：:]", "", base)
        if len(zh) >= 2:
            alts.add(zh)
    # 只留型号块（d16 / air15 / 16se）
    for base in list(alts):
        for m in re.findall(r"[a-z]+\d+[a-z]*", base):
            if len(m) >= 3:
                alts.add(m)

    # 🔴 中文+数字粘连：「战 66」「灵越 15」「天选 7」—— 数字紧跟在中文名后，
    # 这才是用户实际会打的写法。上一步"只留中文主体"和"只留型号块"都把它拆没了：
    #   惠普战 66 八代锐龙版 → 中文主体只剩「战」被 len>=2 过滤，
    #                          型号块一个都没有 → 这台**根本没有可用别名** → 永远认不出
    # 所以单独再生成一遍：从去品牌/去年份/去泛词后的串里，取「中文+数字」片段。
    for base in list(alts):
        for m in re.findall(r"[\u4e00-\u9fa5]{1,6}\d+[a-z]*", base):
            if len(m) >= 2:
                alts.add(m)
    # 反向：数字+中文（"14X 无界"这种倒装，库里有"无界 14X"）
    for base in list(alts):
        for m in re.findall(r"\d+[a-z]*[\u4e00-\u9fa5]{1,6}", base):
            if len(m) >= 3:
                alts.add(m)

    # 清洗：太短的别名不要（"7" / "x" 这种单独出现毫无区分力）
    brand_n = _norm(brand) if brand else ""
    out = []
    for a in alts:
        a = a.strip("()+-.：: /")
        if len(a) < 2:
            continue
        if a in GENERIC_TOKENS:
            continue
        # 🔴 品牌名本身绝不能当别名。
        # 实测 2026-11-11：「华为 MateBook D16」的别名里生成了「华为」，
        # 用户只说「华为怎么样」（一个字没提型号）→ 命中别名「华为」→ 认成 D16。
        # 这是最典型的"用户问 A 系统答 B"。
        if brand_n and a == brand_n:
            continue
        if re.fullmatch(r"20[12]\d", a):
            continue
        if re.fullmatch(r"\d{1,2}", a):     # 纯 1~2 位数字：太泛
            continue
        # 🔴 只有中文、且是"品牌残渣"的不要（去品牌后剩下的单字/碎片）
        if re.fullmatch(r"[\u4e00-\u9fa5]{1}", a):
            continue
        out.append(a)
    return sorted(set(out), key=len, reverse=True)


def unmatched_model_name(text, data=None):
    """句子里像是在**点名一台机型**，但库里没有这台 → 返回那串名字；否则 None。

    为什么必须有（2026-11-11 演示走查实测）：
      U「ThinkBook 14 怎么样」   （库里没有 ThinkBook）
      A「这台机器对你做设计来说只能算部分匹配…」  ← 拿**天选 7** 去答的
    用户问的是一台库里根本没有的机器，系统却把当前 focus 那台当成答案讲了
    一通。这不是"答得不全"，是答了另一个问题 —— 演示时最容易被当场问穿。

    根因：'怎么样' 命中 FIT_KW，classify_intent 判成 ASK_CURRENT，
    于是走 on_current 分支用 focus 那台回答。match_named_model 返回 None
    （它按设计弃权），但没有任何人处理"弃权"这个结果。

    判据：句子里有**字母+数字型号块**（thinkbook14 / y7000p / xps13），
    且这个块在库里任何一台的别名里都找不到 → 就是"点了一台库里没有的型号"。
    纯品牌（"华为怎么样"）不算 —— 那个该反问型号，不是该说"没有"。

    🔴 2026-11-12：查的池子改成**合并池**（100 台）。
      原来查 load() 的 22 台，于是采集池那 78 台会被判定成"库里没有" ——
      而它们正躺在推荐列表第 1 名。用户点名追问刚被推荐的机器，
      系统答「不在我这份数据里」，等于否认自己刚说过的话。
    """
    tc = _norm(text)
    if not tc:
        return None
    blocks = re.findall(r"[a-z]+\d+[a-z]*", tc)
    if not blocks:
        return None

    all_aliases = set()
    for o in _pool_offers_for_lookup(data):
        for a in _model_aliases(o.get("name"), o.get("brand")):
            all_aliases.add(a)
    # 别名里只保留了有用片段，像 "matebook" 这种单看没意义。
    # 所以判断时用"块是否出现在任一别名里"以及反向包含。
    # 🔴 2026-11-16（ZOL 换源后 test_neg 抓到）：**双向包含太宽，改成前缀对齐**。
    #    原判据 `b in a or a in b` 会被**中间子串**误命中：
    #      「VAIO SX14」→ 块 `vaiosx14`，荣耀 X14 的别名 `x14` 是它的**中间**
    #      子串 → 误判"库里可能有这台" → 该报"库里没有"的没报。
    #    前缀对齐（startswith）才能表达"这串说的是同一台"：
    #      xps13 ↔ xps（池内真有戴尔XPS）✓ 照样命中；
    #      vaiosx14 ↔ x14 双向都不是前缀 ✓ 正确判为库里没有。
    for b in blocks:
        if len(b) < 4:
            continue                      # "p16" "14x" 这种太短，太容易撞
        ok = any(a.startswith(b) or b.startswith(a) for a in all_aliases)
        if not ok:
            return b
    return None


def _pool_offers_for_lookup(data=None):
    """点名/幽灵判定要查的**池子** —— 必须和推荐池是同一个。

    🔴🔴 为什么必须有（2026-11-12 端到端彩排抓到的同类最严重错误）：
      v0.4 把推荐池扩到 100 台（人工 22 + 京东采集 78），但 `match_named_model`
      和 `unmatched_model_name` 还在查 `core.load()` —— 那只有 22 台。
      后果：采集池那 78 台**就摆在推荐列表第 1 名**，用户点名追问，系统答
        「库里没采到这台 —— 你说的「MateBook 14 2026」不在我这份数据里」
      然后紧跟一句「我现在能查的是这 22 台」。
      这是「有数据说没有」的最恶劣形态：它刚被推荐给用户，转头就不认识自己推荐的东西。
      比编造更伤 —— 编造是说了假话，这个是**否认自己刚说过的话**。

    ⚠️ `data` 显式传入时（测试切源）保持原行为：只查那一份，不并采集池。
        理由和 merged_offers 的 with_pool 完全一致，否则「只用淘宝源」的
        测试里会混进 78 台京东机，测的就不是淘宝源。
    """
    if data is not None:
        return [o for o in (data.get("offers") or [])
                if o.get("cat") in core.ALLOWED_CATS]
    return core.merged_offers()


def _bare_subject_aliases(pool):
    """哪些别名是「只有主体名、没有型号区分」的裸叫法 → 返回集合。

    🔴 为什么必须动态算、不能硬编码（2026-11-12）：
      「暗影精灵怎么样」被认成「暗影精灵 Pro 15」，而池里的暗影精灵共 3 台
      （11 酷睿版 / 11 锐龙版 / Pro 15）。用户只说了系列名，认成任何一台都是
      "答了另一台"。但「天选 Air」这种名字本身就是主体，不能一起弃权。
      所以判据不是"这词像不像泛称"，而是——**这个别名在池里被几台机器共享**。

    规则：
      ① 别名里含数字 → 不是裸主体（「天选7」「暗影精灵11」都能锁到具体机型）
      ② 别名里含平台/档位后缀（pro / air / plus / se / 锐龙版 / 酷睿版 …）→ 不是裸主体
      ③ 剩下且在 **≥2 台**的别名集合里出现过的 → 是裸主体，命中即弃权
    """
    from collections import Counter
    cnt = Counter()
    for o in pool:
        brand = (o.get("brand") or "").strip()
        for a in _model_aliases(o.get("name"), brand):
            if re.search(r"\d", a):
                continue
            if any(g in a for g in _SHARP_SUFFIX):
                continue
            cnt[a] += 1
    return {a for a, c in cnt.items() if c >= 2}


# 能锁定具体机型的后缀 —— 有这些词的别名不算"裸主体"
_SHARP_SUFFIX = ("pro", "air", "plus", "max", "se", "ultra", "book",
                 "锐龙版", "酷睿版", "战斗版", "超能本", "旗舰版", "柔光版")


def match_named_model(text, data=None):
    """用户在句子里**直接点名**了库里某台机型 → 返回那台；否则 None。

    为什么要有（2026-11-11 演示前实测）：
      Q「华为MateBook D16怎么样」→ 反问「是笔记本还是台式？」
      用户已经指名道姓了，系统还在问最基础的问题 —— 最伤体验的一类。

    🔴 设计原则：**宁可返回 None，也不能匹配到别的机器。**
    用户问 A、系统答 B，比反问"笔记本还是台式"糟得多 —— 后者只是啰嗦，前者是答非所问。

    判据（v7 最终版，别名法）：
      1. 为每台机型生成"用户可能怎么称呼它"的**完整别名串**（不切词，见 _model_aliases）
      2. 别名必须作为**完整子串**出现在句子里才算命中
      3. 分数 = 命中最长别名的长度（越长越具体），品牌对上再加一点
      4. **并列即弃权**：最高分和次高分差不到 30%，说明分不清 → 返回 None
      5. 三道否决：
         ① 句子里有别的字母+数字型号块（thinkbook14/y7000p），和这台对不上
         ② 句子里提到另一个库内品牌，却没提这台的品牌
         ③ 命中的别名只是"小新"这种两台共享的泛主体，且句子里没有区分信息

    实测清单（2026-11-11）：
      认对：华为MateBook D16 / matebookd16 / 联想小新16 / 小新 Air15 /
            Redmi Book Pro 14 / 天选7 / 机械革命无界14X / 隐星P16 / 戴尔灵越15 / 战66
      弃权：ThinkBook 14 / XPS 13 / 拯救者Y7000P / 苹果笔记本 / 华为 / 联想 /
            有什么推荐 / 学设计买什么 / 天选6 / 暗影精灵
    """
    tc = _norm(text)
    if len(tc) < 3:
        return None

    # 句子里所有字母+数字型号块（否决①用）
    text_blocks = set(re.findall(r"[a-z]+\d+[a-z]*", tc))

    # 🔴 必须查合并池（100 台），不能查 load() 那 22 台 —— 见 _pool_offers_for_lookup
    pool = _pool_offers_for_lookup(data)
    all_brands = {b for b in (x.get("brand") for x in pool) if b}
    mentioned_brands = {b for b in all_brands if _norm(b) in tc}

    scored = []
    for o in pool:
        brand = (o.get("brand") or "").strip()
        aliases = _model_aliases(o.get("name"), brand)
        best_alias = ""
        for a in aliases:
            if a in tc and len(a) > len(best_alias):
                best_alias = a
        if not best_alias:
            continue
        # 别名至少要有区分力：「小新」「天选」这类 2 字中文主体算合格，
        # 但单纯的 2 字泛词（"笔记本"/"电脑"）已在 _model_aliases 里过滤掉了。
        score = len(best_alias)
        # 别名里带数字 → 更具体，加权
        if re.search(r"\d", best_alias):
            score += 3
        # 品牌被明确提到，加成
        if brand and _norm(brand) in tc:
            score += 2
        scored.append((score, len(best_alias), o, brand, best_alias))

    if not scored:
        return None

    scored.sort(key=lambda x: (-x[0], -x[1]))
    top = scored[0]
    top_score = top[0]

    # --- 否决①：句子里有别的字母+数字型号块，和这台完全对不上 ---
    # 例：「ThinkBook 14 怎么样」→ text_blocks={'thinkbook14'}，
    # 而 Redmi Book Pro 14 的别名里没有这个块 → 弃权，不认成 Redmi。
    top_aliases = set(_model_aliases(top[2].get("name"), top[3]))
    for b in text_blocks:
        if any(b in a or a in b for a in top_aliases):
            continue
        # 该块和这台毫无关系 → 用户问的肯定是别的型号，弃权
        # 但只在它是"型号块"（含字母且含数字）时才否决，「2026」这种已被规范化过滤
        if re.search(r"[a-z]", b) and re.search(r"\d", b):
            return None

    # --- 否决②：提到另一个库内品牌，却没提这台的品牌 ---
    top_brand = (top[3] or "").strip()
    if mentioned_brands and top_brand and _norm(top_brand) not in tc:
        return None

    # --- 否决③：数字对不上 → 弃权 ---
    # 实测 2026-11-11（反向压测抓到的唯一误判）：
    #   「天选6怎么样」→ 命中别名「天选」→ 认成「华硕天选 7」
    # 用户问 6 代，系统答 7 代。这是典型的"答非所问"，比 MISS 严重得多。
    # 判据：句子里有**独立的数字**（1~2 位，紧邻中文型号词），而该数字既不在
    # 命中的别名里、也不在机型全名的任何位置 → 说的是另一代，弃权。
    if re.search(r"\d", tc):
        full = _norm(top[2].get("name"))
        for num in re.findall(r"\d{1,2}", tc):
            if num in full or num in top[4]:
                continue
            # 只对"型号代数"这类小数字追责，16 / 32 / 64 这种规格数字不追
            if int(num) <= 30:
                return None

    # --- 否决④：并列 → 弃权 ---
    # 实测：「联想小新16如何」会同时命中"联想小新air152026"（别名"小新"）和
    # "联想小新16"（别名"联想小新16"），后者分高，能切开。
    # 但「小新怎么样」两台都是"小新"，分一样 → 弃权，反问"是小新哪一款"。
    #
    # ⚠️ 阈值必须**同时**看比例和绝对差（2026-11-12 实测打回）：
    #   原来只有 `second[0] >= top_score * 0.7`。实测「暗影精灵 11 锐龙版 怎么样」：
    #     top  = 暗影精灵11锐龙版（9 字，+3 含数字 = 12 分）
    #     次名 = 暗影精灵11（6 字，+3 = 9 分）
    #   9 >= 12*0.7=8.4 → 被判成"分不清"，弃权反问。
    #   可用户已经把「锐龙版」说出来了，而次名那个是**酷睿版**（Ultra7）。
    #   这不是分不清，是判据太松 —— 短名字天然分数低，比例一定贴得近。
    #   ⇒ 加一道绝对差：命中的别名比次名**长出 3 个字以上**，就算切开了。
    #     3 个字大约是"锐龙版""Pro 15""Air 14"这种区分后缀的量级。
    if len(scored) > 1:
        second = scored[1]
        longer = top[1] - second[1]        # top[1] 就是"命中最长别名的长度"
        # 🔴 短别名是多出来的那个别名**完整包含**在长的里面（用户说的确实更全）。
        #   实测「无界14x怎么样」：
        #     top  = 无界14x（5 字，+3 = 8 分）
        #     次名 = 无界14（4 字，+3 = 7 分）
        #   只差 1 个字，但差的正是型号后缀 X —— **14X 和 14 是两台机器**。
        #   长度差 1 判不出语义，所以再看一眼：多出来的那个字符是不是字母/数字。
        #   「无界14」→「无界14x」多出的是 x（型号后缀，语义不同）
        #   「小新」  →「小新16」  多出的是 16（型号代数，语义不同）
        #   而「暗影精灵」→「暗影精灵11」这种，长的那条本身是裸主体，交给否决⑤。
        extra_is_model_char = False
        if longer == 1 and len(top[4]) == len(second[4]) + 1:
            if second[4] and top[4].startswith(second[4]):
                tail = top[4][len(second[4]):]
                extra_is_model_char = bool(re.fullmatch(r"[a-z0-9]", tail))
        if second[0] >= top_score * 0.7 and longer < 2 and not extra_is_model_char:
            return None

    # --- 否决⑤：句子里**只有品牌+系列名**，没有型号数字/后缀 → 弃权 ---
    # 🔴 2026-11-12 实测的误判：
    #   「暗影精灵怎么样」原样认成了「暗影精灵 Pro 15」。
    #   用户只说了系列名，库里暗影精灵有好几台（11 酷睿 / 11 锐龙 / Pro 15），
    #   认成 Pro 15 就是"答了另一台" —— 比反问严重。
    #
    # 判据：命中的别名里**不含数字、也不含平台/档位后缀**（pro / air / plus /
    #   锐龙版 / 酷睿版 / se …），说明用户只说了主体名 → 弃权。
    #   「天选7」含数字 → 不弃权，能认；
    #   「暗影精灵」既无数字也无后缀 → 弃权，反问是 11 还是 Pro。
    if not re.search(r"\d", top[4]) and top[4] in _bare_subject_aliases(pool):
        return None

    return top[2]


# ── 「别的/其他」什么时候**不算**换台（2026-11-13 收尾加）──────────
# 见 _is_switch_request 里的注释。三个正则分工：
#   _SWITCH_VERB  真正表示"挑一台新的"的动作词
#   _BARE_OTHER   光秃秃的"别的/其他"（不带动作就是纯粹指"另一批"）
#   _ASK_MORE     「还有什么别的」—— 要列表
#   _EXCEPT_OTHER 「除了 X 其他都行」—— 表达接受
_SWITCH_VERB = re.compile(r"换|来一台|来一个|给我|推荐|挑|选|找一?[台个款]|整一?[台个]")
_BARE_OTHER = re.compile(r"别的|其他|其它")
# 「要更多候选」—— **必须有明确的索要动作**（还有/再看/能看…）。
#
# 🔴 只收带动作的说法，不收裸的「别的呢」：
#    第一版我写成了 `(别的|其他).{0,4}(呢|吗|么)`，于是「别的呢」被排掉，
#    而它在改动前是判换台的 —— 这是我自己造出来的一条回归（没有测试覆盖，
#    是我跑对照集时看出来的）。判据越窄越安全：**只排除确实坏掉的那两类**。
_ASK_MORE = re.compile(
    r"(还有|再看|能看|想看|有没有|有没|给多).{0,6}(别的|其他|其它)")
# 「除了 X，其他都行」—— 这是**接受**，不是拒绝。
# ⚠️ 收「无所谓」：「其他都无所谓」和「其他都行」是一个意思。
_EXCEPT_OTHER = re.compile(
    r"除了.{0,8}(其他|其它|别的).{0,6}(都|均可|就行|可以|没问题|行|无所谓)"
    r"|(其他|其它|别的).{0,4}(都行|都可以|没问题|都无所谓|无所谓)")


def _is_switch_request(text):
    """这句是不是真的要求换台。

    「别的」是换台信号，但「比别的便宜多少」「别的品牌都贵」是在比价，不是换台。
    这个判断只能有一处 —— 实测 2026-11-11：run() 里排掉了、refers_to_current()
    里没排，结果同一句"帮我算一下它比别的便宜多少"还是被当成换台。

    🔴 2026-11-13 晚：本函数**只做规则的确定判断**，不调模型。
       上一版这里写了 `import switch_layer`，而 switch_layer.py 从来没被创建过 ——
       那段代码只在 except 里静默失败，等于什么都没做，却让读代码的人以为
       模型已经参与进来了。这是最坏的一种死代码：它不报错，它假装在工作。

       分工定清楚（两处不许合并，也不许各判一次）：
         · 本函数   = 规则能**确定**认的（换一台/换掉/下一个），秒答、不花钱。
                      它同时是意图层判不出时的退路（离线也能跑）。
         · 意图层   = 开放式说法（"这个价有点离谱了吧"），0.2 秒，认得准。
       接线在 run() 的 want_switch：**取两者之并**。不在本函数里问模型，
       因为本函数会被 _classify_intent_rule 反调，在那儿问模型会绕成死循环。
    """
    if not any(k in text for k in SWITCH_KW):
        return False
    if any(k in text for k in COMPARE_KW):
        return False
    if SWITCH_NOT.search(text):
        return False
    # 🔴 2026-11-13 深夜（换血收尾，test_attack4 抓到 2 条）：
    #    「别的 / 其他」这两个词**本身不表示换台**，它们只表示"另一批东西"。
    #    真正表示换台的是「换/来/给 + 别的」。裸判「别的」会误伤这两类：
    #
    #      「这个价位还有什么别的」   → 要的是**列表**，不是换掉这台
    #      「除了屏幕其他都行」       → 这是**接受**，还指定了保留哪台
    #
    #    实测后果（都在 test_attack4 里）：
    #      Q02 被当成细节追问（因为在换台之前先被别的分支接走了）
    #      R01 focus 从 MateBook 14 换成了小新 Air14 —— 用户说"其他都行"，
    #          系统却把机器给换了，等于把"接受"读成了"拒绝"。
    #
    #    判据：这两个词只有在**伴随挑选动作**时才算换台信号；
    #    只是提到"别的存在"的，交给 LIST_OTHERS_PAT / 意图层去判。
    #    ⚠️ 只在句子里**没有**明确换台动作时才排除 ——
    #       「换台别的」既有动作又有"别的"，那必须还是换台。
    if not _SWITCH_VERB.search(text) and _BARE_OTHER.search(text):
        # 「还有什么别的」「除了…其他…」—— 不是在换台
        if _ASK_MORE.search(text) or _EXCEPT_OTHER.search(text):
            return False
    return True


def classify_intent(text, focus=None, allow_model=True):
    """把用户这句话归类成 6 种意图之一。

    🔴 为什么要有这个函数（2026-11-11 第七轮之后重构）：
    原来「这句是不是在问当前这台」是一串 if 顺序判断，9 条规则互相压制。
    每加一条新判据都要猜它该插第几位，插错就出事：
      · 「我说的就是刚刚你给我推荐的那一台」被新需求规则压掉 → test_neg 回退
      · 「这个机器怎么样」被范围规则吃掉 → 问这台的路整条断掉
    两套词表（CURRENT_REF_PAT / REF_NOT_CURRENT）互相拉扯，越补越脆。

    ⇒ 改成**先判意图，再由意图推导指代**。顺序集中在这里一处。

    🔴 2026-11-13 晚：这一层改为**规则 + 模型协作**（intent_layer.py）。
       为什么必须改 —— 实测真人说法 47 句：

           规则         24/47 = 51%   （按实际分支影响算）
           模型 0-shot  40/47 = 85%
           协作         47/47 = 100%

       规则错的 23 条里，14 条被判成 UNKNOWN（"能撑四年不""散热行不行"
       "六七千的有什么""最好轻一点"）—— 它的问题在于**根本读不懂**，
       而不在于方向判错。UNKNOWN 的后果是反问一句，用户会觉得这机器听不懂话。

       用户怎么说话是完全开放的，词表是封闭的，穷举不完。

       但**保留 allow_model=False 的纯规则路径**：离线/模型挂掉时必须还能跑，
       代价是准确率退回 51%，而不是整个系统不可用。

    判据设计原则（不变）：**先排除"不是"的，最后才认"是"**。
    因为把 ASK_CURRENT 判错成别的，代价是用户被打回第一句（烦但能忍）；
    把别的判错成 ASK_CURRENT，代价是用户提了新需求却被当成追问（需求直接丢了）。
    """
    if allow_model:
        # 协作层自己会处理"无实义不必问模型"和"模型挂了退回规则"。
        # 这里只做一件事：把异常兜住 —— 意图层出任何问题都不许让整轮失败。
        try:
            import intent_layer as _il
            intent, _why = _il.classify(text, focus)
            return intent
        except Exception:
            pass
    return _classify_intent_rule(text, focus)


def _classify_intent_rule(text, focus=None):
    """纯规则版意图分类（协作层的退化路径，也是协作层判不出时的退路）。

    🔴 这个函数不许被别处直接调用 —— 一律走 classify_intent()。
       直接调用会绕过协作层，导致同一个判断在两处给出不同答案（判据漂移）。
    """
    t = (text or "").strip()

    # --- 0. 空输入 / 纯标点 / 纯 emoji：什么都没说 ---
    # 「啊」重复 400 次这种也算 —— 没有汉字实义就不猜意图。
    if not t:
        return INTENT_UNKNOWN
    han = re.findall(r"[\u4e00-\u9fa5]", t)
    if len(han) < 2:
        return INTENT_UNKNOWN

    # --- 1. 要清单：把其余候选列出来 ---
    # 必须排在"换台"之前：「其余推荐的给我列举出信息」里有"推荐"，
    # 但用户要的是把剩下的都看看，不是把第一台换成第二台。
    if LIST_OTHERS_PAT.search(t):
        return INTENT_LIST_OTHERS

    # --- 2. 明确不要 / 要换台 ---
    if _is_switch_request(t):
        return INTENT_REFUSE_SWITCH
    if _negates_current(t):
        return INTENT_REFUSE_SWITCH

    # --- 2. 说范围（价位段 / 品类 / 条件），不是某一台 ---
    if REF_NOT_CURRENT.search(t):
        return INTENT_STATE_RANGE

    # --- 3. 确认就是这台（要在"新需求"之前，否则会被压掉）---
    # 但**没有焦点时不能确认** —— 「就是这台」在没聊过任何机器的上下文里没有指代对象。
    # 实测 2026-11-11（意图单测）：这条原来排在 focus 检查之前，无 focus 也返回 ask_current。
    if focus and CONFIRM_CURRENT.search(t):
        return INTENT_ASK_CURRENT

    # --- 4. 提新需求：有需求动词，且说了要什么东西 ---
    # 「我要一台游戏本」只有需求动词、没命中 NEW_DEMAND_NOUN（那是个偏"属性"的词表），
    # 但「游戏本/轻薄本/台式机」本身就是需求对象，必须算新需求。
    # 实测 2026-11-11（意图单测）：这条原来掉进 unknown，等于用户说了要游戏本、系统没听见。
    if any(w in t for w in DEMAND_WORDS):
        if (any(w in t for w in NEW_DEMAND_NOUN)
                or any(w in t for w in NEED_OBJECT_NOUN)):
            return INTENT_STATE_NEW_NEED

    if not focus:
        # 没有当前讨论对象，剩下的只能是提需求或不知道
        return INTENT_STATE_NEW_NEED if any(w in t for w in DEMAND_WORDS) else INTENT_UNKNOWN

    # --- 5. 指向当前这台 ---
    # 5a 有指代词（词表 + 构词两路，构词那路覆盖"这机器/这笔记本/该机型"这类变体）
    if any(k in t for k in CURRENT_REF) or CURRENT_REF_PAT.search(t):
        return INTENT_ASK_CURRENT
    # 5b 没指代词，但问的是匹配度（「还能打游戏吗」「能用四年吗」）
    if any(k in t for k in FIT_KW) and not any(w in t for w in DEMAND_WORDS):
        return INTENT_ASK_CURRENT
    # 5c 没指代词，但问的是"只有这台才有意义"的维度（「保修几年」「多重啊」）
    if (any(k in t for k in FOLLOWUP_KW)
            and not any(w in t for w in DEMAND_WORDS)
            and not any(w in t for w in NEW_DEMAND_NOUN)):
        return INTENT_ASK_CURRENT

    return INTENT_UNKNOWN


def refers_to_current(text, focus):
    """这句话是不是在说「刚才那台」。

    ⚠️ 这里现在只剩一层：**问意图，再由意图推导指代**。
    以前这里是 9 条 `if` 顺序排列（switch → negate → 范围 → 确认 → 新需求 → 指代词
    → 匹配疑问 → 维度词），每条都在猜「这句是不是在说本台」，
    加一条新规则就得重新想它该插在第几位 —— 第七轮就是插错位置，把
    「我说的就是刚刚你给我推荐的那一台」判成了"提新需求"。
    现在统一走 classify_intent()，顺序集中在一处，且有单测覆盖。
    """
    return classify_intent(text, focus) == INTENT_ASK_CURRENT

FOLLOWUP_SYS = """用户在追问某台机器的细节。数据如下，你只能说数据里有的。

规则：
1. 只谈数据里出现过的内容，不许改写得更好听或更概括。
2. 直接回答他问的那一点就停。他问优点就只说优点，问配置就只说配置。
   不要画蛇添足补一句"库里没有故障率数据"——他没问故障率。
   只有当数据里确实没有他要问的那一项时，才说"库里没有这项数据"。
2b. **说人话，不要念字段名。** 数据里的键名是给人看的索引，不是给用户念的：
   - 「质保年数为 1 年」→ 应该说「整机质保 1 年」
   - 「支持触控：否」→ 应该说「不支持触控」
   - 「续航_小时：5」→ 应该说「续航大约 5 小时」
   把键名和值揉成一句自然的话，不要"XX为 YY"这种格式。
2c. **保修/售后**：只要数据里有「质保年数」「保修政策」「质保备注」中的任意一项，
   就必须直接答出来，**不许说"库里没有记录"**。
   - 问「保修几年」→ 说几年（如「整机质保 1 年」）
   - 问「售后怎么样」→ 说保修政策（全国联保/全球联保/上门服务）+ 年数
   - 只有这三项**全都没有**时，才说没记录
   **不许拿「售后网点_满分5」的评分冒充保修年限** ——
   那是 1-5 档的相对好坏，不是几年；但可以作为"网点覆盖"的补充信息一起说。
3. 特别注意：「一年上门保修」是一项服务，不等于"整机保修一年"。
   数据里写的是服务，你就说服务，不许把它说成保修期。
   同一个道理：「军标认证」不等于"通过了所有军标测试"。
4. 不要重新推荐别的机型，不要重复整段推荐理由。
5. 两到三句。
6. **数据里「有没有人写过优缺点」= 没有时**：这台只有配置和价格。
   你可以报参数（说 2880×1920、OLED、120Hz 都行），但**一个评价词都不许用**：
   - 不许写观感：「细腻」「通透」「跟手」「丝滑」「看着很舒服」
   - 不许判断定位：「定位就是高端商务本」「主打给设计师用」
   - 不许提保值率 —— 库里根本没有这个字段
   - 不许说「不算便宜」「值得买」「性价比高」
   参数是真的，**感受不是**。不要解释数据来源，也不要说「没人评过」。
7. 品牌备注里如果讲的是**别的型号**，不要把这台的名字换成那台的事继续讲。
8. **数据里有「这块屏幕的规格」时，那就是这台屏幕的真实参数，必须直接用。**
   它已经从「配置」那一长串里拆好了（尺寸/分辨率/面板/刷新率/色域）。
   🔴 绝对不许说「库里没有屏幕记录」—— 数据就在你眼前。
   实测 2026-11-13：用户问「屏幕要 2K 以上」，配置里明明写着 2560×1600，
   却答成「库里对这块屏没有单独记录」，用户会以为整个库都是空的。
   反过来，**没有这个字段**时才许说没记 —— 那是这台真的没写。
9. 这一条是上一轮踩过的坑，务必照做：
   **不许把内部字段名、JSON 键名、null、None 这类字样写进回答。**
   实测 2026-11-13：数据里一个字段是空值时，回答写出了
   「屏幕参数为 null。」—— 用户看到的是一句程序调试信息。
   要说"没记"，就用「库里没有记这一项」，不是「字段为 null」。
10. 🔴 **数据里有「接口」时，必须逐个报出来。**
    问「接口够不够」「有没有雷电」「能外接显示器吗」——
    直接把「接口」那栏的型号和数量念出来（USB-A ×2、雷电4 ×1、HDMI 2.1…），
    然后说明够不够用要看你的外设。
    **不许只念 CPU/内存/显卡就结束** —— 那是答非所问。
    实测 2026-11-21：数据里明明有「USB-A ×2、USB-C ×1、雷电4 ×1」，
    回答却把整份配置念了一遍，一个字没提接口。
11. 🔴 **问散热时，不许给「中规中矩」「表现不错」这类评价。**
    数据里能说的只有：散热系统描述（如果有）、CPU TDP、显卡 TGP、机身厚度。
    这些是**发热源和设计**，不是散热效果。
    正确的说法：「这台显卡 TGP 115W、机身 17.6mm，用的是双风扇三热管；
    实际的温度和噪音表现库里没有实测数据，判断不了。」
    **不许说**「散热表现中规中矩」「能维持高负载」「符合预期」——
    库里没有任何散热实测，这些全是编的。
    实测 2026-11-21：用户问「散热行不行」，回答写了
    「散热表现中规中矩」「作为游戏本的核心优势就是能维持高负载下的性能释放」
    —— 两句都是凭定位猜的。"""


# ══════════════════════════════════════════════════════════════
# 追问的主题切分 —— **词表只此一份**（宪法第 9 条）
# ══════════════════════════════════════════════════════════════
# 为什么要集中：原来这套词只活在 `_followup_template()` 里，
# 于是模板会收窄，模型那条路照旧把 6 条优缺点全念一遍。
# 实测 2026-11-12（页面首屏）：
#   问「屏幕怎么样」→「屏幕素质在同价位不算突出。内存形态要按 SKU 确认，
#   机身偏大，14 寸包放不下。」—— 后两句跟屏幕无关。
# 与 §4.5「问屏幕不许念整条 spec」是同一个洞，只是那次修了 spec，没修 pros/cons。
SCR_KW = ["屏幕", "色域", "色彩", "色准", "sRGB", "刷新率", "分辨率",
          "亮度", "雾面", "镜面", "触控", "寸大屏", "OLED"]
# ⚠️ 不能用单字「屏」——「黑屏」里也有个屏字，那是故障不是屏幕素质。
SCR_BAD_KW = ["黑屏", "花屏", "闪屏", "蓝屏", "死机", "虚焊", "通病"]

# 问句触发词（左侧）→ 事实匹配词（右侧）。两侧不能混用：
#   「黑屏」该触发"故障"话题，但不该被当成屏幕素质的证据。
TOPIC_TRIGGER = {
    # 🔴 2026-11-17：**顺序即优先级**（`_topic_of` 返回第一个命中的）。
    #    「充电」必须排在「续航」前面，否则「充电器多少瓦」会被续航抢走
    #    （续航的触发词里有「充电」）。实测踩过。
    "充电": ["充电器", "适配器", "快充", "多少瓦", "电源适配", "充电快", "充电速度"],
    "屏幕": ["屏幕", "色域", "色彩", "显示", "屏"],
    "散热": ["散热", "发热", "温度", "风扇", "噪音", "烫"],
    "续航": ["续航", "电池", "充电", "能用多久"],
    "键盘": ["键盘", "手感", "键程", "打字"],
    "接口": ["接口", "USB", "HDMI", "雷电", "读卡器", "插口"],
    "重量": ["重量", "多重", "轻薄", "便携", "带着走"],
    "内存硬盘": ["内存", "硬盘", "固态", "存储", "容量"],
    "性能": ["性能", "跑分", "处理器", "显卡", "卡不卡"],
    # 🔴 2026-11-17 新增：创作类用途追问。
    #    「能剪视频吗」「能跑 PS 吗」「能做设计吗」——这些问的是**能不能干某件事**，
    #    事实来自显卡/内存/屏幕，不是 pros/cons。
    #    原来没有这个主题，「能剪视频吗」走兜底 → 答"要看实机或第三方评测"，
    #    而数据里明明有 RTX 5060 + 32G。
    #    ⚠️ 不写裸「设计」（那是专业匹配的事），只收具体的创作动作。
    "创作": ["剪视频", "剪辑", "做设计", "跑PS", "跑ps", "修图", "渲染",
             "建模", "画图", "做视频", "调色"],
    "售后": ["保修", "质保", "售后", "维修", "返修", "上门", "联保", "三包"],
    "颜色": ["颜色", "配色"],
    "触控板": ["触控板", "触摸板", "触摸屏"],
    # 做工放最后：「手感」不在它的触发词里（那是键盘），但「机身」这类泛词
    # 容易和别的面撞，排在后面让它只接住真正没人认领的句子。
    "做工": ["做工", "材质", "外壳", "机身", "金属", "塑料", "模具"],
}
TOPIC_FACT_KW = {
    "散热": ["散热", "发热", "温度", "风扇", "噪音"],
    "续航": ["续航", "电池", "充电"],
    "键盘": ["键盘", "手感", "键程"],
    "接口": ["接口", "USB", "HDMI", "雷电", "读卡器"],
    "重量": ["重量", "kg", "克", "轻薄", "便携"],
    "内存硬盘": ["内存", "硬盘", "固态", "存储", "M.2", "插槽"],
    "性能": ["性能", "跑分", "处理器", "显卡", "帧"],
}


def _is_screen_fact(s):
    """一条事实是不是在讲**屏幕本身**（不是黑屏之类的故障）。"""
    if any(b in s for b in SCR_BAD_KW):
        return False
    return any(k in s for k in SCR_KW)


def _topic_of(user_text):
    """这句话问的是哪一项；问不出具体项（"怎么样/值不值"）就返回 None。"""
    q = user_text or ""
    for name, trig in TOPIC_TRIGGER.items():
        if any(t in q for t in trig):
            return name
    return None


def _topic_facts(m, user_text):
    """按提问主题裁一次事实：返回 (主题名, 优点子集, 缺点子集)。

    🔴 2026-11-16（毕设架构反转）：主题**模型优先** ——
       本轮 route() 已让模型识别过 topic（英文枚举），这里映射回中文主题名；
       模型没给或给了 none，才退回词表 `_topic_of`。
       为什么值得接：词表认「接口够不够」靠 TOPIC_TRIGGER 逐词命中，
       而「插U盘方便吗」「外接两个显示器行吗」这类说法它永远接不住 ——
       那正是模型该干的活。

    ⚠️ 裁不到就**原样返回**，不能把数据裁空 ——
    裁空会让模型只能答"库里没有"，那是另一种错误（见宪法第 2 条）。

    🔴 2026-11-13 深夜（换血收尾体检，端到端抓到）：
       「屏幕怎么样」问的是无界 14X，它 6 条优缺点里**没有一条讲屏幕**，
       于是裁完是空的 → 走下面第 1110 行那条"不许裁空"的回退 → 把 6 条全还给模型
       → 用户问屏幕，得到「优点：1.4kg 出头，背着不累」。

       这正是本文件一直在修的那一类（问屏幕答整份配置），只是这次的洞在**回退路径**上。

       为什么"不许裁空"这条规则本身没错：裁空之后模型只能答"库里没有"，
       会把**整台机器**说成没数据。但这一条只对"整台"成立，对"某一面"不成立。
       ⇒ 判据：**这一面裁不到 ≠ 整台没数据**。
          这一面裁空时，事实该是「这一面没人写过」，而不是"把别的面塞给你"。
          所以我加一个空事实标记，让模型知道"这是查不到，不是不给你"。
    """
    # 模型路由的英文主题 → 词表体系的中文主题名。
    # service（品控售后保修维修质量耐用）在 TOPIC_TRIGGER 里没有独立键，
    # 它的事实散在各面里 —— 映射到 None 让回退逻辑原样返回全部优缺点。
    _ROUTE2CN = {"screen": "屏幕", "noise": "散热", "battery": "续航",
                 "keyboard": "键盘", "weight": "重量",
                 "config": "接口", "performance": "性能"}
    topic = None
    lr = _LAST_ROUTE[0]
    if lr and lr.get("model_ok") and lr.get("topic"):
        topic = _ROUTE2CN.get(lr["topic"])       # service/price/pros_cons → None（无对应面）
    if not topic:
        topic = _topic_of(user_text)
    if not topic:
        return None, list(m.get("pros") or []), list(m.get("cons") or [])
    pros = list(m.get("pros") or [])
    cons = list(m.get("cons") or [])
    # 🔴 2026-11-21：屏幕/散热/接口并入「结构化字段」这一组。
    #
    #    原来「屏幕」单独一支，只查 pros/cons 里带屏幕关键词的句子。
    #    问题：采集池 223 台里只有 34 台有人工优缺点，
    #    屏幕参数（尺寸/分辨率/刷新率/色域）明明 100% 覆盖，
    #    却因为"没人写过屏幕评价"而裁成空 → 用户问屏幕得到"要看实机"。
    #
    #    现在它们和售后/重量一样走结构化字段通道（见下面 topic == "屏幕" 分支）。
    #    pros/cons 里的屏幕评价仍然会被 _is_screen_fact 挑出来补充。
    if topic in ("售后", "做工", "充电", "颜色", "触控板", "创作", "续航",
                 "重量", "内存硬盘", "性能", "键盘",
                 "屏幕", "散热", "接口"):
        # 🔴 2026-11-16：这几面的事实**在结构化字段里，不在 pros/cons 里**。
        #    「保修几年」→ warrantyYears / warrantyPolicy / warrantyNote
        #    「什么材质」→ shellMaterial
        #    「充电快吗」→ adapterW / adapterText（2026-11-17 补）
        #    「有别的颜色吗」→ shellColor
        #    「触控板好用吗」→ touchpad / touchScreen
        #    只从 pros/cons 裁的话永远裁空 → 回退 → 答"库里没有"，
        #    而数据其实有。做法：把字段拼成事实句子塞进 pros，让下游照常处理。
        facts = []
        if topic == "售后":
            y = m.get("warrantyYears")
            if y:
                yi = int(y) if float(y).is_integer() else y
                facts.append("整机质保 %s 年" % yi)
            if m.get("warrantyPolicy"):
                facts.append("保修政策：%s" % m["warrantyPolicy"])
            if m.get("warrantyNote"):
                facts.append("质保备注：%s" % m["warrantyNote"])
            # 🔴 2026-11-17 修死循环：品牌售后评分要**现算**，不能只读 m["brandService"]。
            #
            #    实测（用户第三次实测）：连续三轮问售后（「售后怎么样」
            #    「我说的是好售后吗」「我的意思是，售后网点多吗」），
            #    回答**一模一样**，都是那段"具体几年我不敢替厂商说"。
            #
            #    根因：`m` 是 core.get_offer() 返回的**原始 offer**，
            #    里面没有 brandService（那个字段只在 brief() 里临时算过）。
            #    所以 facts 永远是空的 → 每次走同一条兜底模板 → 死循环。
            #
            #    而 `core.brand_info(m)` 明明能查到「联想 service=5」。
            #    做法：这里现调 brand_info，取品牌级数据。
            _bs = m.get("brandService")
            _bnote = m.get("brandNote")
            if _bs is None or _bnote is None:
                try:
                    _bi = core.brand_info(m) or {}
                    if _bs is None:
                        _bs = _bi.get("service")
                    if _bnote is None:
                        _bnote = _bi.get("note")
                    # 品牌结论也一并带上（帮用户理解"为什么不能按品牌判断"）
                    if _bi.get("verdict"):
                        facts.append("品牌结论：%s" % _bi["verdict"])
                except Exception:
                    pass
            if _bs is not None:
                facts.append("品牌售后网点评分 %s / 5（5 = 覆盖最广）" % _bs)
            if _bnote:
                facts.append("品牌备注：%s" % _bnote)
        elif topic == "充电":
            if m.get("adapterW"):
                facts.append("标配 %s W 电源适配器" % m["adapterW"])
            if m.get("adapterText"):
                facts.append("适配器：%s" % m["adapterText"])
            if m.get("batteryLifeH"):
                # 🔴 2026-11-17：必须标明这是**厂商标称**，不是实测。
                #    参数页写「12小时左右，视具体使用环境而定」——
                #    那是厂商在理想条件下测的，实际通常只有 60~70%。
                #    只说"续航约 12 小时"会让用户以为是实测值。
                facts.append("厂商标称续航 %s 小时（不是实测）" % m["batteryLifeH"])
            if m.get("batteryWh"):
                facts.append("电池容量 %s Wh" % m["batteryWh"])
        elif topic == "颜色":
            if m.get("shellColor"):
                facts.append("机身颜色：%s" % m["shellColor"])
        elif topic == "续航":
            # 🔴 2026-11-17：续航原来没有独立主题，问「电池能用多久」
            #    topic 判成「续航」但 facts 是空的 → 走兜底模板 →
            #    答「这一项的具体表现要看实机」。而数据里明明有标称续航。
            if m.get("batteryLifeH"):
                # 必须标明是厂商标称，不是实测（实测通常只有标称的 60~70%）
                facts.append("厂商标称续航 %s 小时（不是实测值）"
                             % m["batteryLifeH"])
            if m.get("batteryLifeText"):
                facts.append("厂商原文：%s" % m["batteryLifeText"][:60])
            if m.get("batteryWh"):
                facts.append("电池容量 %s Wh" % m["batteryWh"])
            if m.get("adapterW"):
                facts.append("标配 %s W 充电器" % m["adapterW"])
        elif topic == "重量":
            # 🔴 2026-11-17：重量 189 台有数据，但 facts 通道是空的 →
            #    问「多重啊」走兜底模板答「要看实机」。这是最不该漏的一面。
            _w = core.effective_weight(m)
            if _w:
                facts.append("整机重量 %s kg" % _w)
                # 给个参照系（不评价，只报同品类区间）
                try:
                    _same = [core.effective_weight(x) for x in core.pool_offers()
                             if x.get("cat") == m.get("cat")]
                    _same = [w for w in _same if w]
                    if len(_same) >= 10:
                        facts.append("同品类 %d 台里，最轻 %s kg、最重 %s kg"
                                     % (len(_same), min(_same), max(_same)))
                except Exception:
                    pass
            if m.get("thicknessMm"):
                facts.append("机身厚度 %s mm" % m["thicknessMm"])
        elif topic == "内存硬盘":
            # 🔴 2026-11-17：内存 222 台有数据，facts 通道是空的。
            _r = core.ram_of(m)
            if _r:
                facts.append("内存 %sG" % _r)
            _ram = m.get("ram") or {}
            if isinstance(_ram, dict):
                if _ram.get("type"):
                    facts.append("内存类型 %s" % _ram["type"])
                if _ram.get("maxGB"):
                    facts.append("最大支持 %sG" % _ram["maxGB"])
            _up = m.get("upgrade")
            if _up == 0:
                facts.append("内存焊死，不可加装")
            elif _up:
                facts.append("可加装（升级空间 %s/3 档）" % _up)
            if m.get("storageGB"):
                facts.append("硬盘 %sG" % m["storageGB"])
        elif topic == "性能":
            # 🔴 2026-11-17：跑分 162 台有数据，facts 通道是空的。
            if m.get("perf") is not None:
                facts.append("性能分 %s / 100（Cinebench R23 标尺）" % m["perf"])
            else:
                facts.append("库里没有这台的跑分")
            if m.get("cpuModel"):
                facts.append("CPU：%s" % m["cpuModel"])
            if m.get("gpuModel"):
                facts.append("显卡：%s" % m["gpuModel"])
            if m.get("cpuTdpW"):
                facts.append("CPU 功耗 %s W" % m["cpuTdpW"])
            if m.get("gpuTgpW"):
                facts.append("显卡功耗 %s W" % m["gpuTgpW"])
        elif topic == "键盘":
            # 🔴 2026-11-17：键盘 131 台有数据，facts 通道是空的。
            if m.get("keyboard"):
                # 清掉抓取残留（参数页的 ">" 和多余空格）
                _kb = re.sub(r"[<>]|&gt;|&lt;", "", str(m["keyboard"]))
                _kb = re.sub(r"\s+", " ", _kb).strip(" ，,")
                if _kb:
                    facts.append("键盘：%s" % _kb)
            else:
                facts.append("库里没有这台的键盘描述")
        elif topic == "触控板":
            if m.get("touchpad"):
                facts.append("触控板：%s" % m["touchpad"])
            if m.get("touchScreen") is not None:
                facts.append("屏幕%s支持触控" % ("支持" if m["touchScreen"] else "不"))
        # ═══════════════════════════════════════════════════════════
        # 🔴 2026-11-21：补三个一直是空 facts 的主题
        #
        #    用户实测：「问屏幕怎么样、散热行不行、接口够不够，
        #    得到的都是"要看实机"」—— 而数据其实有：
        #    screen 100%、ports 91.5%、cooling 29.1%。
        #
        #    根因：这三个主题在 _topic_facts 里**根本没有分支**，
        #    走到 else 兜底。数据补了、也投影到 offer 了，
        #    但事实通道没接 —— 所以模型看不到。
        # ═══════════════════════════════════════════════════════════
        elif topic == "屏幕":
            sc = m.get("screen") or {}
            bits = []
            if sc.get("sizeInch"):
                bits.append("%g 寸" % sc["sizeInch"])
            if sc.get("widthPx") and sc.get("heightPx"):
                bits.append("%d×%d" % (sc["widthPx"], sc["heightPx"]))
            if sc.get("panel"):
                bits.append(str(sc["panel"]))
            if sc.get("refreshHz"):
                bits.append("%dHz" % sc["refreshHz"])
            if bits:
                facts.append("屏幕：%s" % " ".join(bits))
            # 色域：区分 sRGB / DCI-P3，别混成一个数
            gam = sc.get("colorGamut") or {}
            if isinstance(gam, dict) and gam:
                gp = []
                for key, label in (("sRGB", "sRGB"), ("srgb", "sRGB"),
                                   ("dciP3", "DCI-P3"), ("DCI-P3", "DCI-P3"),
                                   ("adobeRGB", "AdobeRGB")):
                    if gam.get(key):
                        gp.append("%s %s%%" % (label, gam[key]))
                if gp:
                    facts.append("色域：%s" % " / ".join(dict.fromkeys(gp)))
            # 亮度：两个可能的键名（brightnessNit 是池里的，brightness 是补录的）
            nit = sc.get("brightnessNit") or m.get("brightness")
            if nit:
                facts.append("亮度 %s nit" % nit)
            if m.get("screenTech"):
                facts.append("屏幕技术：%s" % m["screenTech"])
            if not facts:
                facts.append("库里没有这台的屏幕参数")

        elif topic == "散热":
            if m.get("cooling"):
                facts.append("散热系统：%s" % m["cooling"])
            # 散热能佐证的客观指标：CPU TDP + 显卡 TGP（都是发热源）
            tdp = m.get("cpuTdpW")
            tgp = m.get("gpuTgpW")
            if tdp or tgp:
                bits = []
                if tdp:
                    bits.append("CPU TDP %sW" % tdp)
                if tgp:
                    bits.append("显卡 TGP %sW" % tgp)
                facts.append("发热源：%s（这是芯片功耗上限，不是整机功耗）"
                             % " / ".join(bits))
            if m.get("thicknessMm"):
                facts.append("机身厚 %smm" % m["thicknessMm"])
            if not facts:
                facts.append("库里没有这台的散热描述")

        elif topic == "接口":
            if m.get("ports"):
                _p = m["ports"]
                # ports 可能是 list（池里存的是结构化列表）或 str（补录时拼的串）
                if isinstance(_p, (list, tuple)):
                    _p = "、".join(str(x) for x in _p if x)
                facts.append("接口：%s" % _p)
            if m.get("wifi"):
                facts.append("无线：%s" % m["wifi"])
            if m.get("bluetooth"):
                facts.append("蓝牙：%s" % m["bluetooth"])
            if not facts:
                facts.append("库里没有这台的接口信息")

        elif topic == "创作":
            # 「能不能剪视频/跑PS」——只报**硬件条件**，不判断"够不够"。
            # 判断够不够需要软件实测帧数，库里没有（红线：不许编）。
            gk = (m.get("gpuKind") or "").lower()
            vram = None
            gpu = m.get("gpu") or {}
            if isinstance(gpu, dict):
                vram = gpu.get("vramGB")
            if gk == "discrete":
                facts.append("独显 %s" % (m.get("gpuModel") or "有独立显卡"))
                if vram:
                    facts.append("显存 %sG" % vram)
            elif gk == "integrated":
                facts.append("核显机型，没有独立显存")
            if m.get("ram"):
                facts.append("内存 %sG" % m["ram"])
            else:
                # 🔴 offer 里没有 `ram` 字段（只有 `ram_of(spec)` 函数）——
                #    实测 `m.get("ram")` 恒为 None，所以这条事实从来没生成过。
                #    用 core.ram_of 从 spec 里取。
                _r = core.ram_of(m)
                if _r:
                    facts.append("内存 %sG" % _r)
            if m.get("screenTech"):
                facts.append("屏幕技术：%s" % m["screenTech"])
            scr = m.get("screen") or {}
            if isinstance(scr, dict) and scr.get("colorGamut"):
                cg = scr["colorGamut"] or {}
                p3 = cg.get("dciP3") if isinstance(cg, dict) else None
                if p3:
                    facts.append("色域 DCI-P3 %s%%" % p3)
        else:  # 做工
            if m.get("shellMaterial"):
                facts.append("外壳材质：%s" % m["shellMaterial"])
            if m.get("shellColor"):
                facts.append("颜色：%s" % m["shellColor"])
            # 🔴 重量必须走 core.effective_weight —— test_weight 的 W8 是结构性检查，
            #    出口层出现裸 weightKg 就报错（重量有四个出口，各读各的字段会漂）。
            _w = core.effective_weight(m)
            if _w:
                facts.append("重 %s kg" % _w)
        tp = facts + [x for x in pros if any(
            k in x for k in (TOPIC_FACT_KW.get(topic) or []))]
        tc = [x for x in cons if any(
            k in x for k in (TOPIC_FACT_KW.get(topic) or []))]
    else:
        kws = TOPIC_FACT_KW.get(topic) or []
        tp = [x for x in pros if any(k in x for k in kws)]
        tc = [x for x in cons if any(k in x for k in kws)]
    if not tp and not tc:
        # 这一面确实没人写过。
        # 屏幕这一面**不许回退**：屏幕有独立的参数通道（_screen_of），
        #   参数在就报参数、参数不在就明说没记 —— 两条都比"念重量"好。
        #   其余各面（散热/键盘/续航…）没有参数通道，只能回退到整份印象，
        #   但必须显式告诉模型"这些不是这个问题下的记录"，由它自己划清界限。
        if topic == "屏幕":
            return topic, [], []
        return topic, pros, cons
    return topic, tp, tc


def is_followup(text, slots):
    """这句是不是在追问当前这台的某个面。

    🔴 2026-11-13 深夜：**判据统一到 `asks_about_current()` 一处**。
       原来这里只有 `any(k in text for k in FOLLOWUP_KW)`，
       而 `_run` 的 on_current 分支另有 `ask_detail`（同一个词表、
       外加我新加的 `_topic_of`）。两份判断在"接口够不够""续航多久"
       这类句子上给出**不同答案**：前者 False、后者 True。
       同一个问题两处回答不一致，早晚有一处会答错（宪法第 9 条）。
    """
    if not core.ready_for_recommendation(slots):
        return False
    return asks_about_current(text)


def asks_about_current(text):
    """这句在问当前这台的某个面吗（细节/参数/价格）—— **全项目唯一入口**。

    两个来源取并集，因为它们覆盖的句子是**互补**的：
      · FOLLOWUP_KW  ：屏幕/保修/散热/多重/缺点/售后…（问"这一面"）
      · _topic_of    ：接口/续航/内存硬盘/性能/键盘…（主题识别，另有用途）

    实测（2026-11-13 深夜，16 句常见追问）：
        只有 FOLLOWUP_KW 认得的：保修几年 / 保值吗 / 做工怎么样 / 售后怎么样 / 有什么缺点
        只有 _topic_of  认得的：接口够不够 / 续航多久 / 内存能加吗 / 跑分多少
        两边都不认的：能玩几年 / 值不值
    ⇒ 单用任何一个都会漏掉近一半。并集之后只剩"能玩几年/值不值"两条，
      而这两条由意图层（ask_current）和 on_current 的兜底分支接住。

    ⚠️ 不许在这里加"价格评价"（划算吗/值不值）：那是 ask_price 的活，
       它要算库里真实排名，走的是另一条路（_answer_price_position）。
       混进来会让"这个价怎么样"被当成问细节。

    🔴 2026-11-13 深夜（M05 回归）：**"提要求"的句子不许算追问**。
       「我的要求是不要封装内存的」里有"内存"，`_topic_of` 返回"内存硬盘"，
       于是被当成"在问内存"→ 走追问回答，硬约束没落进槽位。
       多轮测试立刻挂掉（M05：换台推了封装机型）。
       判据：句子里有"我的要求是/我要/要求/必须/不要…的"这类**给条件**的形态
       → 这是 state_new_need，不是追问。详见 _CONSTRAINT_FORM。
    """
    t = text or ""
    # 🔴 形态硬否决永远排在模型前面（M05 真实事故）：
    #    「我的要求是不要封装内存的」表面在讲内存，实际在**给硬约束**。
    #    这个形态是封闭的、规则能确定认 —— 模型在这句上翻过车，不许它再碰。
    if _CONSTRAINT_FORM.search(t):
        return False
    # ── 模型为主（2026-11-16 毕设架构反转）────────────────────────
    # 本轮 route() 的结果优先：intent 判 ask_current、或模型识别出了具体
    # 追问主题 → 在问细节。模型明确判了别的动作且没识别出主题 → 不是追问。
    # 词表只在模型不可用（_LAST_ROUTE 为 None 或 model_ok=False）时兜底。
    lr = _LAST_ROUTE[0]
    if lr and lr.get("model_ok"):
        # 🔴 intent（主动作）的优先级**高于** topic（问的哪一面）——
        #    首版写反了：topic 非 none 就判追问，结果「预算提高到7000」
        #    被模型给了 topic=price → 判成追问 → 预算没更新（M03 挂）。
        #    topic 只是"如果 在问细节，问的是哪一面"的细分，不是追问的证据。
        _mi = lr.get("intent")
        if _mi == INTENT_ASK_CURRENT:
            # 🔴 给条件动词的否决也要作用于 ask_current（M03 实测抓到）：
            #    「预算提高到7000，屏幕素质我有要求」→ 模型判 ask_current
            #    （topic=screen，它看到了"屏幕"），于是改预算的话被当成
            #    "在问屏幕细节"，预算根本没更新 —— 用户说的每句话都被吞了。
            #    判据：改数动词在场（提高到/加到/控制在…）且无疑问形态
            #    = 在**更新槽位**，不是在问。疑问形态（"提到7000行吗"）仍是追问。
            if _GIVE_COND_VERB.search(t) and not _QUESTION_FORM.search(t):
                return False
            # 🔴 价格不算"细节追问"（attack6 回归抓到）：
            #    「这个价在市场上算什么水平」「贵不贵」→ 模型 topic=price →
            #    判成追问 → 走 answer_followup 念优缺点。
            #    但价格位置有**专门通道**（_answer_price_position，代码实算
            #    库内排名），"算什么水平"必须由代码算、模型只措辞 ——
            #    那是本项目"数字零写权限"的样板场景。topic=price 时放行，
            #    让 on_current 段的 ask_price 闸接住它。
            #    ⚠️ 「性价比高吗」「值不值」同理（attack6 第二轮修复）：模型把
            #       它们给了 topic=pros_cons，但词表时代 FOLLOWUP_KW 就不含这些词
            #       —— 它们一直走价格位置。模型不能把恢复原行为的词拉回来。
            #    🔴 但「它保值吗」要**留**在追问（followup 第三轮修复）：
            #       保值/二手残值是**这台机器的属性**（细节），"值不值"才是
            #       问价格划不划算（市场位置）。两个词都在 PRICE_Q_KW 里，
            #       且模型对「保值」给的 topic 也可能是 price ——
            #       所以排除保值类要**同时作用两支**，不然「它保值吗」被甩到
            #       价格位置，答的是"库里最便宜的一台"，完全答非所问。
            _price_ask = (lr.get("topic") in ("price", "pros_cons")
                          and any(k in t for k in PRICE_Q_KW)
                          and not re.search(r"保值|二手|残值", t))
            if _price_ask:
                return False
            return True
        if _mi in (INTENT_STATE_NEW_NEED, INTENT_REFUSE_SWITCH,
                   INTENT_STATE_RANGE, INTENT_LIST_OTHERS):
            # 模型明确判了别的动作。但「预算提高到7000」这类**给条件**的句子
            # 模型有时会判成 state_range（只看到数字）—— 补一道词表否决：
            # 带"提高/加/涨/升/控制在"这类**改数动词**的，是给条件不是范围。
            if _GIVE_COND_VERB.search(t):
                return False if not _QUESTION_FORM.search(t) else True
            return False
        # unknown → 词表兜底（走下面原逻辑）
    if any(k in t for k in FOLLOWUP_KW):
        return True
    # 🔴 2026-11-13 深夜：**主题詞必须带疑问形态才算追问**（M05 回归）。
    #
    #    `_topic_of` 里的词表本来是为"裁事实"设计的，里面有"轻薄"这类**品类词** ——
    #    「5000 的轻薄本，就上课写作业」被判成"在问重量"，
    #    于是第一轮本该推荐，却走了 followup。多轮测试的 M05 整条链就歪了。
    #
    #    判据：主题词只说明"这句跟哪一面有关"，**不说明它在问**。
    #    要算追问，必须有疑问形态（吗/呢/几/多/怎/怎样/行不行…）或者
    #    是个明显的问句（以问号结尾）。
    #    「轻薄本」「内存更大」这类陈述式 → 不是在问，是在给条件。
    if _topic_of(t) and _QUESTION_FORM.search(t):
        return True
    return False


# 「在给约束」的句子形态 —— 有它就不是追问，是提要求。
#
# 🔴 这条是从 M05 的回归里长出来的，不是凭空加的：
#    「我的要求是不要封装内存的」表面在讲内存（像追问），实际是在**加硬约束**。
#    判据：显式的要求动词（要求是/我要/必须/得能）+ 明确的排除（不要/不能是）。
_CONSTRAINT_FORM = re.compile(
    r"要求是|我的要求|我的条件是|我要(?!问|知道)|必须有|必须能|"
    r"不要(?!问)|不能是|得能|一定要|不接受")

# 「给条件/改数」动词 —— 句子带它就是在**更新槽位**，不是在问细节。
# 2026-11-16 反转后 M03 抓到：「预算提高到7000」被模型给了 topic=price
# 判成追问，预算没更新。给条件动词是封闭集合，词表打得中。
_GIVE_COND_VERB = re.compile(
    r"提高(到|至)|加(到|至)|涨(到|至)?|升(到|至)|控制(在|到)|改成|换(到|成)价|"
    r"最多(给|花|出)|预算(调|改|加|提)|上限(调|改|提|到)")

# 「疑问形态」—— 主题词 + 疑问形态 = 在问那个面；只有主题词 = 在说条件。
#
# 依据：中文里"这机器多重"和"5000 的轻薄本"都用到了重量词，
# 前者在问、后者在给条件。区别不在词，在**有没有问的形态**。
_QUESTION_FORM = re.compile(
    r"吗|呢|几|多少|多[重大久长]|怎么|怎样|如何|行不行|好不好|够不够|"
    r"能不能|会不会|是不是|有没有|大不大|高不高|贵不贵|值不值|[？?]")


# 「这台能不能干某件事」—— 问的是匹配度，不是要换一台。
# 这一类如果按"新需求"处理，系统就会自作主张换品类（16:27 的天选 7 就是这么来的）。
FIT_KW = ["合适吗", "适合吗", "能不能", "可不可以", "够用吗", "够不够", "能跑",
          # 2026-11-12 用户实测：「没独显确定够用？」没被认成匹配度问题 →
          # 走了重新推荐，把同一台又推了一遍。用户的原话是"它又推荐一次不回答我问题"。
          # 「够用」「可以吗」是最常见的口语问法，不能只收带"吗"的完整式。
          "够用", "可以吗",
          "能打", "带得动", "玩得动", "跑得动", "行吗", "行不行", "怎么样",
          # 「能用四年吗」「撑得住几年」—— 问的是寿命/耐受度，也是匹配度问题。
          # 实测 2026-11-11（第七轮）：这两类原来在 FOLLOWUP_KW 和 FIT_KW 里都找不到，
          # 于是 on_current 判对了、下游却没一个分支接住，还是掉回 clarify 反问品类。
          "能用", "用得", "能否用", "够用几年", "能用几年", "用得久",
          "撑得住", "撑得", "扛得住", "扛得", "够撑", "顶得住"]

# 「这个价怎么样」「划算吗」「值不值」—— 在问**这台的价**值不值，不是问用途匹配。
#
# 实测 2026-11-11（第六轮对抗）：这类问句原来命中 FIT_KW 的「怎么样」，
# 被当成"用途匹配"交给 _answer_current，而那个函数是判"这机器配不配你的用途"的，
# 于是回答跑偏成配置介绍。更糟的是，没命中任何关键词的（「这个价在市场上算什么水平」）
# 会**直接穿透 on_current**，一路掉进 recommend —— recommend 里模型看到"这是榜首"，
# 就编出「在轻薄本里算最贵的一台」（实际排第 3）。
#
# 所以价格评价必须**先于** FIT_KW 判断。
PRICE_Q_KW = ["这个价", "这价", "这价格", "这个价格", "划算", "值不值", "值吗",
              "贵不贵", "贵吗", "便宜吗", "好价", "性价比", "值这个价",
              "什么水平", "算什么水平", "什么档次", "占不占便宜", "亏不亏"]

# 用户在同一句里既改了条件又提问。这类不能被"追问优先"整段吞掉。
NEW_COND_PAT = re.compile(
    r"(预算|价位|价钱)?(提高|提到|提到到|加到|加到|上调|调高|改成|换成|变成|涨到|降到|降到)")
BUDGET_HIKE = re.compile(r"(预算|上限|价).{0,4}?(提高|提到|加到|上调|调高|改成|换成|涨到|变成)")

# 句子里出现了新的预算数字（提高/降低/改成 + 数字），说明条件变了
NUM_AFTER_HIKE = re.compile(
    r"(提高|提到|加到|上调|调高|改成|换成|涨到|降到|变成|变成)\s*[^\d]{0,4}(\d{3,5})")


def has_new_condition(text):
    """这句话里是不是带了新条件（改了预算 / 换了用途 / 换了品类）。
    只用来决定"要不要重新解析槽位"，不参与最终判断。
    16:25:59 那轮「预算提高到7000，屏幕素质我有要求」被追问逻辑整段吞掉，
    预算停在 5000，模型还复读了 3 遍"库里没有数据"。"""
    if NUM_AFTER_HIKE.search(text):
        return True
    if BUDGET_HIKE.search(text) and any(ch.isdigit() for ch in text):
        return True
    # 明确的用途/品类变化
    for w in ["改成", "换成", "变成", "不学", "改学", "不玩", "要打游戏", "加个"]:
        if w in text:
            return True
    return False


# 「能带进教室吗」「背着累不累」—— 这类是在问**当前这台**的属性，
# 不是在提新的购买条件。实测 2026-11-11（M08 回归）：
# 第 1 轮「8000 的游戏本，主要打游戏」cat=gaming，
# 第 2 轮「能带进教室吗」被 SLOT_SYS 规则 2 推成 cat=thin，
# 于是继承逻辑以为用户改了品类，把游戏本换成了轻薄本 —— 用户没这么说过。
MOBILITY_ASK = re.compile(
    r"(带得进|带进|背得动|背着.{0,4}(累|重|沉)|能不能(带|背)|可以(带|背))"
    r".{0,6}(吗|么|呢|不|？|\?)"
    r"|(重不重|沉不沉|轻不轻|便携吗|方便带)")

# 「要带去教室」「不用带，放宿舍」这类是 **carry 槽位**，不是"我要换轻薄本"。
# 🔴 实测 2026-11-12（用户当面反馈）：上一轮已经定了游戏本、也说了限电 500W，
#   用户补一句「要带去教室」→ 模型按"要带着走 ⇒ 轻薄本"把 cat 改回 thin
#   → 首位从暗影精灵 11 变成 MateBook 14（核显），打游戏这条直接没了。
#   这不是听懂，是把一个约束当成了换品类的命令。
#   MOBILITY_ASK 只覆盖问句，这里补陈述句 —— 两者共用同一个"保留 known 品类"的分支。
CARRY_ONLY = re.compile(
    r"(要|得|需要|打算)?(带|背)(着|去|进|回)?[^。，；]{0,6}(教室|图书馆|宿舍|家|学校|公司)"
    r"|不用带|不带出门|放宿舍")

# 用户**明确**点品类的时候，上面那条"别换品类"的护栏必须让路。
# 「我要轻薄本，能带就行」是在点品类；「我要带去教室」只是在说携带 —— 两者不能混。
CAT_EXPLICIT = re.compile(r"(轻薄本|超极本|游戏本|笔记本|手提|台式机?|整机|主机|内存条?|固态|硬盘|配件)")
# 🔴 「笔记本」原本漏掉了 —— 实测 2026-11-12（attack2 K17）：
#   「7000 的台式机」→「还是买笔记本吧，要带教室」，品类没切回，
#   模型只好顺着 desktop 槽位编出「库里没有笔记本数据」（库里明明有 50 台）。

# 用途词：说了用途，品类跟着变是**合理**的（"我就是要玩游戏" → 游戏本）。
# 品类词（CAT_EXPLICIT）是明说，用途词是语义上的明说，两者都放行；
# 其余情况一律保留已知品类 —— 见 _run 里 cat 那条护栏。
CAT_PURPOSE_WORDS = ["游戏", "打游戏", "网游", "办公", "上课", "写作业",
                     "剪视频", "剪辑", "写代码", "敲代码", "设计", "建模", "制图"]


# 数据里没有帧数，就不许预测"会不会卡" —— 这是同一条编造红线。
# 允许说"没有帧数数据，我判断不了实际体验"，不许说"会卡/会掉帧/流畅"。
# 2026-11-11 对抗测试又抓到一条：推 ¥6799 的天选 7，说"RTX 5050 能应付 3A 大作"。
# 库里根本没有这个结论，是模型自己补的。
FRAME_GUESS = ["会卡", "会掉帧", "带不动", "玩不动", "跑不动", "流畅玩", "满帧",
               "60帧", "帧数能到", "体验不错", "发热严重",
               "应付 3A", "应付3A", "跑满 3A", "跑满3A", "轻松跑", "足以应付",
               "随便玩", "通吃", "不在话下", "毫无压力"]

# 逐条补词永远补不完 —— 实测 2026-11-11 答案里写「玩大型游戏完全没压力」，
# 词表里只有「毫无压力」，就这么漏过去了。改用模式：只要出现
# 「(完全/毫无/一点/根本/丝毫不)+压力」或「(完全/轻松/稳稳)带得动/玩得转」都算。
FRAME_PAT = re.compile(
    r"(完全|毫无|一点|根本|丝毫|基本)?\s*"
    r"(没|没有|无)\s*(有)?\s*(任何)?\s*压力"
    r"|(轻松|完全|稳稳|随便)\s*(能|可以)?\s*(带得动|玩得转|跑得起来|拿下|应付)"
    r"|(性能|帧数|画面)\s*(拉满|全开)")

# 超预算时常见的自相矛盾措辞：「这个预算里唯一能买到的」其实是买不到。
BUDGET_LIE = ["唯一能买到", "唯一能开机", "这个价位里最", "预算内唯一",
              "这个预算能买到", "这价位能拿下",
              # 实测 2026-11-11「500 的轻薄本」：库里没有任何开机/合格性检测数据，
              # 却被写成"这个价位里唯一能正常开机的正经机器" —— 无出处断言。
              "唯一能正常开机", "唯一能开机", "正经机器", "能正常开机",
              "唯一能用的", "唯一靠谱", "唯一值得"]

VERDICT_KEY = "系统判定（最终结论）"


def _praise_no_review(text, m):
    """这台机器**没人写过优缺点**，回答却在替它说好话。

    🔴🔴 为什么必须有（2026-11-12 接入 80 台采集池后，演示彩排抓到）：
      U「预算 8000 打游戏」
      A「暗影精灵 11 锐龙版是首选，它配备了 R9-8945HX 处理器和 RTX 5060 显卡，
         屏幕刷新率高达 240Hz。这台机器在售后网点覆盖上得满分…」
      —— 这台来自采集池，pros/cons 是**空的**。240Hz 是真实参数，
      但"高达"、"首选"、"得满分"全是评语，而库里没有人评过这台。
      用户看到的是一个像模像样的推荐，实际系统对这台一无所知。

    ⚠️ 判据必须**双向**：只看"有没有夸"会误杀 ——
      人工层那 22 台有真实 pros，夸是应该的。
      所以先看 m["hasReview"]，没有评价才启动检查。

    ⚠️ 什么算"夸"：带评价色彩的词。**纯参数陈述不算** ——
      「屏幕 240Hz」「内存 32G」「是 RTX 5060」都是在报事实，必须允许。
      判据抓的是「高达 / 很够用 / 首选 / 得满分 / 值得 / 性价比」这类**价值判断**。
    """
    t = (text or "").strip()
    if not t or not m:
        return None
    # 有真实评价的机型不查 —— 它夸的是数据里的人话，不是模型自己编的
    if m.get("hasReview"):
        return None
    PRAISE = re.compile(
        r"高达|高达\s*\d|很够用|足够用|非常够|相当不错|表现出色|表现不俗"
        r"|首选|最值得|很值|值得买|性价比高|性价比不错|得满分|满分|"
        r"一大亮点|最大亮点|卖点|优势明显|碾压|吊打|诚意十足|堆料足"
        # 2026-11-12 实测漏掉的变体：
        #   「这台暗影精灵 11 锐龙版**配置很顶**」—— 参数一个没写错，
        #   但"配置很顶"是评价，而库里没人评过这台。
        # 这类"形容词+程度"的说法要补进来，单独加词永远补不完，
        # 所以再加一条模式：程度副词 + 形容词（很顶/挺强/相当能打…）。
        r"|配置很顶|很顶|挺能打|相当能打|很能打|挺强|很强劲"
        r"|(很|挺|相当|非常|特别|真)(顶|强|猛|香|值|能打|划算|扎实|厚道)"
        # 🔴🔴 2026-11-12 端到端彩排抓到的第二批漏网 —— 这批更隐蔽，
        #   因为一个脏字都没有，读起来像"专业评测"：
        #     实测输出「它**最大的亮点**就是那块 OLED 屏幕，分辨率高达 2880×1920…
        #               看着**非常细腻通透**，滑动滚动都很**跟手**」
        #              「这台**定位就是高端商务本**」
        #              「它的价格 6299 在同类里**不算便宜**，**保值率也就中等**」
        #   逐条看为什么该拦：
        #     ① 细腻 / 通透 / 跟手 / 丝滑 —— 观感评价。库里没人看过这块屏，
        #        色准观感一个字都没有。这属于"替用户看了一眼"。
        #     ② 保值率 —— 库里**根本没有**保值率这个字段。说"中等"是纯编。
        #     ③ 定位就是高端商务本 —— 市场定位结论，不是参数。
        #     ④ 不算便宜 —— 相对价格判断，需要同价位横向比，库里没这个结论。
        r"|细腻|通透|跟手|丝滑|顺滑|耐看|观感好|看着很|看起来很|上手很"
        # 「最大的亮点」中间夹了个"的"，上面那条"最大亮点"漏了这种写法
        r"|最(大|亮|主)的?亮点"
        r"|保值率|保值|不算便宜|不便宜|超值|良心|诚意"
        # 「适合预算有限的学生党」这类**对人群下结论**的表述。
        # ⚠️ 只收"适合/面向 + 人群"，不收"适合打游戏"——后者是拿用途判匹配度，
        #    数据里真有 fitVerdict，属于该说的。
        r"|适合.{0,8}(学生党|学生|小白|入门|预算有限|打工人|职场)"
        r"|(学生党|小白).{0,6}(的?首选|正合适|够用)"
        r"|定位就是|定位在|面向.{0,6}(用户|人群)|主打.{0,8}(职场|学生|设计|办公)"
        r"|(色彩|色域|屏幕).{0,6}(很好|不错|出色|优秀)"
        r"|(性能|散热|续航).{0,6}(很好|不错|出色|优秀)"
        # 🔴🔴 2026-11-12 第三批漏网 —— 这批最危险，因为它**像内行**：
        #   实测「暗影精灵 11 锐龙版 怎么样」（采集池机器，pros/cons 为空）：
        #     「这是典型的**入门级**游戏本，**主打性价比**」
        #     「属于**强核弱显**的配置」「16G 内存是**单通道**」
        #     「这台机器**没有独立显卡插槽**，想升级显卡基本没路了」
        #   两类问题：
        #     ① 市场定位/档位判断：入门级 / 主打性价比 / 强核弱显
        #        —— 这是拿参数推结论，库里没有人下过这个结论。
        #     ② **硬件形态推断**：单通道 / 独显插槽 / 能否升级
        #        —— 库里**根本没有这些字段**。说"是单通道"和说"是 32G 内存"
        #        完全不同：后者能查，前者是推的。而用户会当事实听。
        #   ⚠️ 注意"双内存插槽""双 SSD 位"这类**库里真有的**不算 ——
        #      所以判据只收"单通道/插槽有无"这种推断式表述，不收"插槽"二字。
        r"|入门级|进阶级|典型.{0,4}游戏本|主打性价比|强核弱显|弱显|水桶机"
        r"|是单通道|单通道内存|没有独显插槽|没有独立显卡插槽|不能升级显卡"
        r"|升级显卡基本没|内存是单通道|独显槽"
        r"|(这|该)(台|款).{0,8}(适合|定位|属于).{0,10}(学生|入门|主流|高端|旗舰)")
    m2 = PRAISE.search(t)
    if m2:
        return m2.group(0)
    # 🔴 反向断言（2026-11-12 页面实录）：
    #   同一句话里前后矛盾 ——「有人专门针对这台机器的优缺点做过评价」
    #   紧接着「没有人工写过的优缺点」。前一句是编的：这台 hasReview=False。
    #   这类错比夸它更离谱，因为用户在读第一句时已经建立"这机器有人背书"的印象。
    #   先去否定词再判，否则「没有人评过」会被自己误伤。
    t_pos = re.sub(r"(没有|没人|没人有|无)", "", t)
    # 「有人」和「评价」之间常夹一串定语：
    #   「有人**专门针对这台机器的优缺点**做过评价」
    # 所以不能要求两个词相邻，给 14 个字的窗。
    m3 = re.search(r"有人.{0,14}(评价|评测|评过|写过)"
                   r"|(这台|该机|它).{0,10}(评价|评测)(还)?(不错|很好|挺好)", t_pos)
    return m3.group(0) if m3 else None


def _field_echo(text):
    """回答里把**字段名**当内容念出来了。

    实测 2026-11-11 演示走查：
      「品牌售后网点分是 5 分制」      ← 这是数据库键名，不是人话
      「一句话标签是…」「要提醒的坑是…」
    数据给模型的时候用的是中文字段名（为了让它看懂），副作用是它会直接念出来。
    两条措施：① 字段名本身改得不那么像内容（售后网点_满分5）
             ② 出口再加一道，念出来就打回。
    """
    PAT = re.compile(
        r"售后网点分|品牌售后网点|售后网点_|保值分是|保值分_|保值_满分|"
        r"一句话标签|要提醒的坑是|要提醒的坑：|"
        r"满分\s*5\s*分制|满分5|分是\s*\d\s*分制|\d\s*分制")
    m = PAT.search(text or "")
    return m.group(0) if m else None


def _power_guess(text):
    """推测整机功耗/判断"限电够不够" —— 库里没有这个数据，说了就是编。

    🔴 2026-11-17 实测抓到（用户问「限电 500W」，机器没有任何功耗字段）：

      「这台 16 寸的机器大概率跑不满，因为它的功耗设计通常远超这个限制」
      「这意味着你要么得找能稳定供电的插座，要么就得接受性能被严重阉割」
      「否则这台机器在限电环境下根本没法正常用」

    每一句都是**推测**：库里既没有整机功耗，也没有实测瓦数。
    `adapterW`（适配器标称）不等于整机功耗，不能拿来推结论。

    为什么这类比"编数字"更危险：它读起来像内行经验，
    用户不会怀疑，但它决定了"这台能不能买"这个关键判断。

    判据分两组：
      ① 明确的功耗推测词（功耗设计/满载功耗/整机功耗 + 推测语气）
      ② 对"够不够供电"下结论（跑不满/带不动/没法正常用）
    """
    t = text or ""
    # 🔴 2026-11-18：**先排除"诚实声明"**，再做推测判定。
    #
    #    实测误杀（预算8000打游戏，模型原话）：
    #      「适配器标称 280W，但整机实际功耗数据未记录，宿舍限电通常还需预留余量」
    #
    #    这句**完全正确**：280W 是适配器真实数据，而且它明确说了
    #    「整机实际功耗数据未记录」—— 这正是我们要求的诚实回答。
    #    但旧判据命中「整机…功耗」+「280W」→ 判成"推测整机功耗"→ 重写
    #    重写后因为出现「充电器」又被 bad 判据拦 → 最终回退模板
    #    → 用户看到 117 字的干巴巴配置罗列。
    #
    #    教训：判据必须区分「编造」和「声明没有数据」。
    #    判据：同一句里出现"未记录/没有数据/查不到/判断不了/不知道"等
    #    免责声明，且没有断言性推测词 → 放行。
    _HONEST = (r"未记录|没有记录|没记录|无记录|未收录|没有数据|没数据|无数据|"
               r"查不到|找不到|判断不了|无法判断|不知道|不确定|不清楚|"
               r"库里没有|数据里没有|没有这个数据")
    _ASSERT = (r"大概率|肯定会|一定会|必然是|远超|根本没法|肯定跑|"
               r"严重阉割|必须换|肯定不够")
    if re.search(_HONEST, t) and not re.search(_ASSERT, t):
        # 诚实地说了"我没有这个数据" → 不是编造
        return None
    # ① 功耗推测：出现"功耗"且带推测/断言语气
    if re.search(r"(功耗|瓦数|功率)\s*(设计|通常|一般|大概|大约|约为|超过|远超)", t):
        return "功耗推测"
    # 「大概/通常 + 多少 W」也算推测（除非是适配器标称，那个有数据支撑）
    #
    # 🔴 2026-11-18：这条要排除"适配器/充电器"—— 那是真实数据（adapterW），
    #    说「适配器标称 280W」是**引用数据**，不是推测整机功耗。
    if re.search(r"(整机|满载|实际)\s*(功耗|功率)", t) and \
            re.search(r"\d+\s*[Ww瓦]", t):
        # 如果这句是在讲适配器/充电器，且有"标称/额定"这类限定 → 放行
        if re.search(r"(适配器|充电器|电源)\s*(标称|额定|是|为)", t) and \
                re.search(r"(标称|额定)", t):
            return None
        return "整机功耗数字"
    # ② 对供电够不够下结论
    if re.search(r"(限电|供电|插座|跳闸)", t) and \
            re.search(r"(跑不满|带不动|带不起来|没法正常用|根本没法|"
                      r"严重阉割|必须换|不能用)", t):
        return "对限电下结论"
    return None


def _overspec(text):
    """超出库内证据的断言。返回命中的词。

    词表 + 模式双管：词表抓固定说法，模式抓"完全没压力""轻松带走"这类变体。
    前缀下划线表示"内部用"，但 super_claims 也被测试直接调用，所以不加下划线。
    """
    hits = [w for w in FRAME_GUESS if w in text]
    for m in FRAME_PAT.finditer(text):
        s = m.group(0).strip()
        if s and s not in hits:
            hits.append(s)
    for m in RELIABILITY_PAT.finditer(text):
        s = m.group(0).strip()
        if s and s not in hits:
            hits.append(s)
    # 「最 X」里库里核不了的那部分（最好/最强/最值得/最耐用…）。
    # 可核实的（最贵/最便宜/最轻/最重）不在这里拦，见 super_claims 的注释。
    for s in super_claims(text):
        if s and s not in hits:
            hits.append(s)
    return hits


# 「能确保你四年都安心」「保证你不用跑网点」「绝对可靠，坏不了」
# —— 这类不是编造事实，是**替数据下可靠性保证**。
# 库里有"军标认证""一年上门保修"这两个事实，但没有任何一条能推出
# "四年不出问题"。实测 2026-11-11：六道校验全部漏掉这类说法。
#
# 只抓"把可靠性说成确定的"，不抓"转述保修条款"：
#   拦：「一年上门保修，保证你不用自己跑网点」
#   放：「一年上门保修，不用自己跑网点」（数据原话）
RELIABILITY_PAT = re.compile(
    r"(能|可以|足以|肯定能|绝对能)\s*(确保|保证|担保|保你|让你.{0,6}(放心|安心))"
    r"|(绝对|肯定|一定|百分百)\s*(可靠|耐用|没问题|不会坏|用得住|不会出毛病)"
    r"|(放心|闭眼)\s*(买|用|入)"
    r"|(坏不了|不会坏|不会出毛病|用不坏|不会有问题)"
    r"|(四年|五年|三年|几年|长期).{0,4}(不会坏|没问题|不用管|不用操心)"
    r"|(保证|确保).{0,8}(四年|五年|三年|不坏|不出事)"
    # 「保证你不会出问题」「保证不出毛病」—— 保证 + 否定式结果
    r"|(保证|确保|担保).{0,6}(不|没)\s*(会|用)?\s*(出问题|出毛病|坏|后悔)"
    # 「保证满意」「绝对不后悔」—— 主观感受也没法替用户保证
    r"|(保证|确保|绝对|肯定|百分百).{0,4}(满意|不后悔|不会后悔)"
    # 「耐用」「抗造」+ 年限/否定 —— 把主观评价说成客观结论
    r"|(耐用|抗造|结实|皮实).{0,6}(四年|五年|几年|不坏|不出|不用)"
    r"|(用|撑|扛).{0,2}(四年|五年).{0,4}(不坏|没问题|不用修)")


def _budget_lie(text, result):
    """超预算场景下说「这预算里能买到」属于自相矛盾。
    只在榜首确实超预算时才检查 —— 否则"这个价位里最划算"是正常措辞。"""
    ranked = result.get("ranked") or []
    if not ranked or not ranked[0].get("overBudget"):
        return []
    return [w for w in BUDGET_LIE if w in text]


def _is_fit_question(text):
    """这句话到底在问「能不能干某事」，还是在问「这台有什么毛病」。
    判据：命中 _asked_purpose（游戏/设计/剪辑/代码）且带能力疑问词 → 用途匹配。
    只是问缺点/屏幕/重量 → 细节追问。
    实测：'它有什么缺点' 含 FIT_KW 的'怎么样'变体，被误判成用途匹配。"""
    if not _asked_purpose(text):
        return False
    CAP = ["合适", "适合", "能不能", "可不可以", "够用", "够不够", "能跑",
           "能打", "带得动", "玩得动", "跑得动", "行不行", "行吗"]
    return any(w in text for w in CAP)


def _merge_offer(o, asked_topics=None):
    """把原始 offer 补上 answer_followup 要用的品牌分字段。

    🔴 2026-11-17：顺带把「已问过的主题历史」塞进去（`_askedTopics`）。
       这样 `answer_followup` 能知道"用户在重复问同一件事"，
       从而换角度而不是复读（修死循环，见 answer_followup 头注释）。
       为什么走 offer 而不是加函数参数：_merge_offer 是 6 处调用的唯一入口，
       在这里塞最省事，且不会漏掉任何一个分支。
    """
    # 走 core.brand_info，避免同名品牌被手机版覆盖（见那里注释）
    b = core.brand_info(o)
    r = dict(o)
    r["brandService"] = b.get("service")
    r["brandResale"] = b.get("resale")
    r["brandNote"] = b.get("note")
    if asked_topics:
        r["_askedTopics"] = list(asked_topics)
    return r


def _asked_purpose(text):
    """这句话里问的是哪个用途。用来判匹配度，不用来改槽位。
    16:27 的坑：用户说「打游戏这个合适吗」，如果拿旧槽位 purpose=['design'] 去判，
    系统会答"部分匹配"——因为他问的根本不是设计。"""
    hits = []
    if any(w in text for w in ["游戏", "打机", "3A", "网游", "永劫", "吃鸡", "原神", "LOL"]):
        hits.append("gaming")
    if any(w in text for w in ["设计", "ps", "PS", "修图", "调色", "AI ", "插画", "建模"]):
        hits.append("design")
    if any(w in text for w in ["剪视频", "剪辑", "PR", "Pr", "pr", "渲染", "后期"]):
        hits.append("video")
    if any(w in text for w in ["写代码", "编程", "开发", "虚拟机", "docker", "跑模型"]):
        hits.append("dev")
    return hits


def _answer_price_position(user_text, o, focus):
    """回答「这台的价在库里算什么水平」。

    🔴 核心：**价格位置由代码算，模型只负责措辞。**
    实测 2026-11-11：这句原来掉进 recommend 分支，模型看到"这是榜首"，
    就编出「在轻薄本里算最贵的一台」——实际 5100 在 10 台里排第 3。
    价格排名是纯计算，没有任何理由让模型猜。
    """
    cat = o.get("cat")
    peers = [x for x in core.load()["offers"]
             if x.get("cat") == cat and x.get("price") and x.get("id") != o.get("id")]
    price = o.get("price")
    cat_name = core.CAT_NAMES.get(cat, cat)

    if not price:
        return {"stage": "compare", "slots": {}, "reply":
                "这台库里没记价格，我算不了它在什么位置。", "focus": focus,
                "focusName": o.get("name"), "questions": [], "warnings": [],
                "dataAsOf": core.data_as_of(), "outside_products": [],
                "untraceable_numbers": [], "fabricated_words": []}

    allp = sorted([price] + [x["price"] for x in peers], reverse=True)
    rank = allp.index(price) + 1
    n = len(allp)
    cheaper = [x for x in peers if x["price"] < price]
    pricier = [x for x in peers if x["price"] > price]
    sub = core.subsidy_of(price)

    # 位置描述只用算出来的事实，不写"最X"除非真的是
    if rank == 1 and n > 1:
        pos = "在库里 %d 台%s里是最贵的" % (n, cat_name)
    elif rank == n and n > 1:
        pos = "在库里 %d 台%s里是最便宜的" % (n, cat_name)
    else:
        pos = "在库里 %d 台%s里排第 %d 贵（比它贵的有 %d 台，比它便宜的有 %d 台）" % (
            n, cat_name, rank, len(pricier), len(cheaper))

    lines = [
        "%s 到手 ¥%s，%s。" % (o["name"], price, pos),
        "价格我没有「市场均价」这个概念 —— 库里只有这 %d 台自己的到手价，"
        "所以「划算不划算」我只能按这个范围说，不代表市面。" % n,
    ]
    if pricier:
        cheapest_up = min(pricier, key=lambda x: x["price"])
        lines.append("比它贵的那台是 %s，¥%s，贵 ¥%d。"
                     % (cheapest_up["name"], cheapest_up["price"],
                        cheapest_up["price"] - price))
    if cheaper:
        near = max(cheaper, key=lambda x: x["price"])
        lines.append("比它便宜又最接近的是 %s，¥%s，便宜 ¥%d。"
                     % (near["name"], near["price"], price - near["price"]))
    if sub:
        lines.append("原价 ¥%s，其中含国补 ¥%s。" % (sub["original"], sub["subsidy"]))

    reply = "\n".join(lines)
    return {"stage": "compare", "slots": {}, "reply": reply,
            "focus": focus, "focusName": o.get("name"),
            "questions": [], "warnings": [], "dataAsOf": core.data_as_of(),
            "outside_products": [], "untraceable_numbers": [],
            "fabricated_words": [], "priceRank": {"rank": rank, "of": n}}


INTRO_SYS = """用户点名问一台具体的机器，但还没说拿它干什么。

硬规则：
1. 先给一句总评：这台是什么档次、给谁用的。依据只能是数据里的
   「一句话标签」「配置」「优点」「缺点」——不要自己评价"性价比高不高"，
   那需要跟别的机器比，这里没有别的机器的数据。
2. 再说两到三条实打实的点：配置、优点里最相关的、缺点里最该知道的。
3. **不许预测能不能跑某个软件、会不会卡、帧数多少** —— 库里没有这些数据。
4. 最后一句问一句用途（学习/游戏/剪视频/写代码），问他主要拿来干什么。
   这样下一轮就能按他的实际用途给判断，而不是干巴巴地说"数据不足"。
5. 三到四句，像同学帮你看机器，别用客服腔。不要念字段名。
6. 不要推荐别的机型，不要说"要不要看看另一台"。用户问的就是这台。
7. **数据里「有没有人写过优缺点」= 没有时**（这批机器只有配置和价格）：
   第 1 条的「总评」不许写。你没有依据判断它是什么档次、给谁用。
   - 不许写「典型的入门级游戏本」「主打性价比」「适合学生党」
   - 不许推断硬件形态：「内存是单通道」「没有独显插槽」「以后不能升级显卡」
     —— 库里没有这些字段，这些是**推**的不是**查**的
   - 不许说「最大的亮点是」
   改成：报配置 + 报价格 + 明说一句「这台我库里没人评过，我只按参数说」，
   然后问他用途。"""


def _intro_model(user_text, o):
    """用户指名问了某台，但还没说用途 —— 先介绍这台，再反问用途。

    为什么要有（2026-11-11 实测）：接上 match_named_model 之后，
    「华为MateBook D16怎么样」走 _answer_current，因为 purpose 为空，
    fit_verdict 是 None，回答变成「数据不足，目前没法判断它适不适合你」
    —— 用户问"这机器怎么样"，得到的是"我不知道"，比之前反问品类还差。

    正确做法：没有用途就先讲这台**本来是什么**，然后把用途问出来。
    这不是回避，是数据边界内能说的全部。
    """
    b = core.brief(o)
    data = {
        "机型": b["name"], "配置": b["spec"], _price_label(o): b["price"],
        "品类": core.CAT_NAMES.get(b["cat"], b["cat"]),
        "一句话标签": b["tag"],
        "优点": b["pros"], "缺点": b["cons"],
        # 过滤掉"讲的是别的型号"的那部分，见 _clean_caution
        "要提醒的坑": _clean_caution(b["caution"], o),
        "售后网点_满分5": b["brandService"],
        "保值_满分5": b["brandResale"],
        "品牌备注": b["brandNote"],
        "库里有没有性能实测数据": "有" if b.get("perf") else "没有",
        # 🔴🔴 2026-11-12：这里也漏了（判据漂移的第四处）。
        #   实测「暗影精灵 11 锐龙版 怎么样」走的是 _intro_model（还没给用途），
        #   输出「典型的入门级游戏本，主打性价比」「16G 内存是单通道」
        #   「没有独立显卡插槽，想升级显卡基本没路了」——
        #   _bad() 里六条判据全部放行，因为每个字都通顺得像内行写的。
        #
        # 🔴 2026-11-16：措辞改过了。原来要求模型说「没有人工写过的优缺点」
        #   「这台我库里没人评过」—— 用户反馈**不要强调人工/没人评**：
        #   这是毕设项目，数据是自己爬的，如实报数据就行，
        #   不需要向用户解释数据是怎么来的、有没有人评过。
        #   约束本身不变（不许编评价、不许判断定位），只是不再要求那句免责声明。
        "有没有人写过优缺点": "有" if o.get("hasReview") else "没有",
        "如果没人写过_你必须这么说":
            ("直接报配置和价格就行，不要解释数据来源、也不要说「没人评过」。"
             "可以报参数、报价格，但不许判断它的**市场定位**"
             "（「入门级游戏本」「主打性价比」不行），"
             "不许推断**硬件形态**（内存通道数、有没有独显插槽、能不能升级显卡 —— "
             "库里没这些字段），不许说「最大的亮点是」「适合学生党」这种评价。")
            if not o.get("hasReview") else
            ("按「优点」「缺点」两栏说，"
             "但不许超出这两栏自己加内容。"),
    }
    reply = chat([{"role": "system", "content": INTRO_SYS},
                  {"role": "user", "content":
                   "数据：" + json.dumps(data, ensure_ascii=False)
                   + "\n\n用户问：" + user_text}],
                 num_predict=220).strip()

    corpus = " ".join([b.get("tag") or "", b.get("caution") or ""]
                      + (b.get("pros") or []) + (b.get("cons") or []))

    def _bad(t):
        # _overspec 已经覆盖"会不会卡/帧数/流畅"这类预测（见 FRAME_GUESS/FRAME_PAT），
        # 不需要另写一个 _predict_lag —— 判据抄两遍一定会漂。
        return bool(check_fabrication(t, corpus)
                    or _overspec(t)
                    # 🔴 2026-11-17：不许推测整机功耗 / 对"限电够不够"下结论。
                    #    介绍机型时同样会犯（"这台限电 500W 带不动"）。
                    or _power_guess(t)
                    or _out_scope_product(t)
                    or check_scope(t)
                    # 把字段名当内容念出来（"售后网点分是 5 分制"）
                    or _field_echo(t)
                    # 偷换推荐对象：把"另一台更值得买"说成本机的理由。
                    # 实测 2026-11-11：介绍「联想小新 16」时输出
                    # 「同价位的小新 16SE 有双硬盘位，那个型号可能更值得看」
                    # —— 用户问的是小新 16，回答在安利 16SE。
                    or _other_model_pitch(t, {"ranked": [o]})
            # 2026-11-18：把当前这台说成别的品牌（「这台属于机械革命暗影精灵」）
            or _brand_mismatch(t, o)
                    # 🔴 没人写过优缺点的机器，不许替它下结论（2026-11-12 补）
                    or _praise_no_review(t, o))

    if _bad(reply):
        reply2 = chat([{"role": "system", "content": INTRO_SYS + STRICT_TAIL},
                       {"role": "user", "content":
                        "数据：" + json.dumps(data, ensure_ascii=False)
                        + "\n\n刚才那句有问题：写了数据里没有的东西，"
                          "或者预测了卡不卡/帧数。重写，只用数据里的内容。\n\n用户问："
                        + user_text}],
                      num_predict=220).strip()
        if _bad(reply2):
            # 模板兜底：全是库里原文，一个字不生成
            parts = ["%s，%s，现在到手 ¥%s。" % (b["name"], b["spec"], b["price"])]
            if b["tag"]:
                parts.append(b["tag"].rstrip("。") + "。")
            if b["pros"]:
                parts.append("好的一面：" + "；".join(b["pros"][:2]) + "。")
            if b["cons"]:
                parts.append("要留意的是：" + b["cons"][0].rstrip("。") + "。")
            parts.append("你主要拿它干什么？上课写作业、打游戏、剪视频还是写代码？"
                         "说了用途我才能判断这台对你够不够。")
            reply2 = "".join(parts)
        reply = reply2

    return {"stage": "fit", "slots": {}, "reply": reply,
            "focus": o["id"], "focusName": o["name"],
            "picked": o["name"], "questions": [], "warnings": [],
            "outside_products": check_outside_products(reply),
            "untraceable_numbers": [], "fabricated_words": [],
            "dataAsOf": core.data_as_of()}


def _answer_current(user_text, o, slots, focus):
    """回答「当前这台适不适合我这个用途」。
    16:27 的错误是直接换品类；正确做法是拿库里的字段回答匹配度，
    没有的字段（帧数、返修率）明说没有。"""
    # 用户这句话问的用途优先。他说"打游戏这个合适吗"时，要拿 gaming 去判，
    # 不能拿历史槽位里的 design —— 否则答的是另一个问题。
    asked = _asked_purpose(user_text)
    purpose = asked or (slots.get("purpose") or [])
    b = core.brief(o, purpose)
    VERDICT = {"match": "匹配", "partial": "部分匹配", "mismatch": "不匹配", None: "数据不足，判断不了"}
    data = {
        "机型": b["name"], "配置": b["spec"], _price_label(o): b["price"],
        "品类": core.CAT_NAMES.get(b["cat"], b["cat"]),
        "一句话标签": b["tag"], "优点": b["pros"], "缺点": b["cons"],
        # 过滤掉"讲的是别的型号"的那部分，见 _clean_caution
        "要提醒的坑": _clean_caution(b["caution"], o),
        VERDICT_KEY: VERDICT.get(b["fitVerdict"], "数据不足"),
        "判断依据": b["fit"],
        # 用户问「没独显够用吗」时，判断要靠专业配置表，不能靠模型常识
        "你的专业要求": _major_brief(slots) or "（没识别出专业，只按用途判）",
        "售后网点_满分5": b["brandService"],
        "保值_满分5": b["brandResale"], "品牌备注": b["brandNote"],
        "用户这次问的用途": purpose,
        "历史用途_仅作背景": slots.get("purpose") or [],
        # 🔴 2026-11-17：**限电事实通道**。
        #
        #    用户说「限电 500W」时，`dormWatt` 会落进 slots。
        #    但库里**没有整机功耗字段**，所以模型只能猜 ——
        #    实测它会写「功耗设计通常远超这个限制」「大概率跑不满」，
        #    全被 `_power_guess` 拦掉，重写后干脆不提限电了。
        #
        #    那也不对：用户问了，一个字不回等于没听懂。
        #
        #    正确做法（本字段就是给模型的脚本）：
        #      ① 有适配器标称功率 → 报出来（这是唯一有数据支撑的参考）
        #      ② 明说"整机实测功耗库里没有"
        #      ③ 指路（厂商规格页 / 客服）
        #    三句话都不需要编。
        **({"用户提到的限电": "%s W" % slots["dormWatt"],
            "限电这一项你必须这么说": (
                ("这台标配 %s W 电源适配器（适配器标称，不等于整机功耗）；"
                 % o["adapterW"] if o.get("adapterW") else
                 "库里没有这台的电源适配器功率；")
                + "整机实测功耗库里没有，所以限电 %s W 够不够用我判断不了。"
                  "要确切数字得看厂商规格页的「功耗」栏，或问客服要满载功耗。"
                  "⚠️ 不许推测「大概率跑不满」「功耗设计通常远超」「严重阉割」"
                  "这类话 —— 库里没有整机功耗数据。"
                % slots["dormWatt"])}
           if slots.get("dormWatt") else {}),
        # 🔴🔴 2026-11-12：这台到底有没有人评过（见 _praise_no_review）
        "有没有人写过优缺点": "有" if o.get("hasReview") else "没有",
        "如果没人写过_你必须这么说":
            ("可以报参数、报价格、按判断依据说清匹配度，"
             "但不许判断它的**市场定位**（「入门级游戏本」「主打性价比」不行），"
             "不许推断**硬件形态**（内存通道数、有没有独显插槽、能不能升级显卡 —— "
             "库里没这些字段，一个都不能猜），"
             "也不许说「最大的亮点是」「性价比高」「值得买」。"
             "不要解释数据来源，也不要说「没人评过」。")
            if not o.get("hasReview") else
            ("按「优点」「缺点」两栏说，"
             "但同样不许超出这两栏自己加内容。"),
        # ═══════════════════════════════════════════════════════════
        # 🔴 2026-11-21：**这条路原来完全没有接口/散热/屏幕结构化字段**。
        #
        #    实测：问「接口够不够」「散热行不行」时走的是 `_answer_current`
        #    （stage=fit），不是 answer_followup —— 所以那边改了没用。
        #    数据字典里只有「配置」一长串，模型只能从里面挑着念，
        #    挑不到接口就念配置，挑不到散热就凭定位猜「中规中矩」。
        #
        #    判据：**同一个事实要在所有输出路径都传**，
        #    不能只在一条路上补（这是这个项目第 N 次踩同一个坑，
        #    见 audit_matrix.py 的存在理由）。
        # ═══════════════════════════════════════════════════════════
        **({"屏幕尺寸_寸": (o.get("screen") or {})["sizeInch"]}
           if (o.get("screen") or {}).get("sizeInch") else {}),
        **({"屏幕分辨率": "%d×%d" % ((o["screen"])["widthPx"],
                                    (o["screen"])["heightPx"])}
           if (o.get("screen") or {}).get("widthPx")
           and (o.get("screen") or {}).get("heightPx") else {}),
        **({"屏幕刷新率_Hz": (o.get("screen") or {})["refreshHz"]}
           if (o.get("screen") or {}).get("refreshHz") else {}),
        **({"屏幕面板": (o.get("screen") or {})["panel"]}
           if (o.get("screen") or {}).get("panel") else {}),
        **({"屏幕亮度_nit": (o.get("screen") or {})["brightnessNit"]}
           if (o.get("screen") or {}).get("brightnessNit") else {}),
        **({"接口": ("、".join(str(x) for x in o["ports"] if x)
                     if isinstance(o["ports"], (list, tuple)) else o["ports"])}
           if o.get("ports") else {}),
        **({"散热系统": o["cooling"]} if o.get("cooling") else {}),
        **({"独显直连": o["dGPU"]} if o.get("dGPU") else {}),
        **({"无线网卡": o["wifi"]} if o.get("wifi") else {}),
        **({"蓝牙": o["bluetooth"]} if o.get("bluetooth") else {}),
    }
    sys = """用户在问「刚才推荐的那台机器，适不适合我某个用途」。

硬规则：
1. 第一句就回答系统判定（最终结论）这个值。不要改判，不要说成别的档位。
2. 只谈这台机器。绝对不要推荐别的机型，不要说"要不换个品类看看"，
   不要自作主张换成游戏本——用户问的是这台行不行。
3. 判断依据里的话就是理由，挑最相关的一到两条说出来，别自己另编理由。
4. 数据里没有的量（游戏帧数、返修率、故障率、续航小时），明说"库里没有"，
   然后用一句话说明这意味着什么。一个字都不许编。
5. 不要做任何减法或差价计算。
6. 三到四句，像给同学分析，别用客服腔。
7. 绝对不要把字段名念出来，比如不要说"系统判定：""判断依据："这种。
   直接用大白话讲结论。"""
    reply = chat([{"role": "system", "content": sys},
                  {"role": "user", "content":
                   "数据：" + json.dumps(data, ensure_ascii=False) + "\n\n用户问：" + user_text}],
                 num_predict=240).strip()
    # 追问也不许编数字。命中就重写，再命中走模板。
    fake = {"ranked": [o], "warnings": [], "dataAsOf": ""}
    want = VERDICT.get(b["fitVerdict"], "")

    def _bad_answer(rep):
        """回答要不要打回重写。集中一处，避免重写前后判据不一致。

        🔴 2026-11-12 补 praise：这是判据漂移的**第三处**。
           compose() 和 answer_followup() 都加了「参数当卖点」，
           fit 这条路径漏了。实测代价（端到端）：
             「暗影精灵 11 锐龙版 怎么样」→ 输出
               「这是典型的入门级游戏本，主打性价比」
               「属于"强核弱显"的配置」「16G 内存是单通道」
               「这台机器没有独立显卡插槽，未来想升级显卡基本没路了」
           —— 这台在采集池，pros/cons 是空的。以上每一句都是编的：
             入库级定位、通道数、插槽形态，库里都没有这些字段。
           而且它比编数字更危险：**编得像内行**，用户不会怀疑。
        """
        return bool(
            verify_answer(rep, fake, user_text)
            or check_fabrication(rep, _corpus_of([o]))
            or _verdict_wrong(rep, b["fitVerdict"])
            or _overspec(rep)
            # 出口也要做范围校验。实测 2026-11-11（演示前实跑）：
            #   「小米笔记本的售后体系不如手机」—— 回答里冒出"手机"，
            #   而 check_scope 只在入口校验用户输入，回答这一侧完全没管。
            #   「别指望它能完全替代专业设计工作站」—— "工作站"也是库里没有的品类。
            or check_scope(rep)
            or _out_scope_product(rep)
            or _field_echo(rep)
            # 🔴 2026-11-17：不许推测整机功耗 / 对"限电够不够"下结论。
            #    库里没有功耗字段，这类话全是编的（实测见函数注释）。
            or _power_guess(rep)
            # 🔴 没人写过优缺点的机器，不许替它下结论（2026-11-12）
            or _praise_no_review(rep, o)
            # 2026-11-21：泛泛评价（「中规中矩」「符合预期」）也要拦
            or _vague_praise(rep)
            or VERDICT_KEY in rep or "判断依据" in rep)

    bad = _bad_answer(reply)
    if bad:
        reply2 = chat([{"role": "system", "content": sys + STRICT_TAIL},
                       {"role": "user", "content":
                        "数据：" + json.dumps(data, ensure_ascii=False)
                        + "\n\n刚才那句有问题（结论说错了，或者写了数据里没有的东西，"
                          "或者提到了电脑之外的品类——手机、平板、工作站都不许提，"
                          "或者预测了会不会卡/流不流畅——库里没有帧数数据，不许预测）。"
                          "重写，结论必须是「%s」。\n\n用户问：%s" % (want, user_text)}],
                      num_predict=240).strip()
        if _bad_answer(reply2):
            reply2 = _fit_template(b)
        reply = reply2
    # 🔴 2026-11-17：限电兜底 —— 用户问了限电，回答必须提。
    #
    #    实测：`data` 里明明给了「用户提到的限电」+「限电这一项你必须这么说」，
    #    模型还是只答匹配度，一个字不提限电。
    #
    #    这和之前「模型不听话」是同一个模式（提示词约束不稳定）。
    #    所以用代码兜底：检测到 dormWatt 且回答没提限电 → 直接补一句。
    #
    #    ⚠️ 补的这句**只用库里有的**：适配器标称（如果有）+ 明说没整机功耗 + 指路。
    if slots.get("dormWatt") and not re.search(r"(限电|供电|功耗|瓦|W\b|适配器)", reply):
        _dw = slots["dormWatt"]
        _seg = []
        # 🔴 2026-11-17：CPU TDP + GPU TGP 能给一个**下界**，但要标清楚是下界。
        #
        #    实测（zol-2128664 暗影精灵 11）：CPU 55W + GPU 115W = 170W。
        #    整机还要算主板/内存/屏幕/风扇，实际肯定更高 —— 所以 170W 是**下界**。
        #
        #    判据：
        #      下界 > 限电  → 明确不够用（下界都超了，实际更超）
        #      下界 ≤ 限电  → 只能说"下界没超"，不能保证够（还要看整机）
        #    ⚠️ 不许把下界当成实际功耗说"够用"。
        _cpu = o.get("cpuTdpW")
        _gpu = o.get("gpuTgpW")
        _lower = (_cpu or 0) + (_gpu or 0)
        if _lower > 0:
            _parts = []
            if _cpu:
                _parts.append("CPU %sW" % _cpu)
            if _gpu:
                _parts.append("显卡 %sW" % _gpu)
            _seg.append("%s，加起来 %sW 是**下界**（不含主板/内存/屏幕）"
                        % (" + ".join(_parts), _lower))
            if _lower > _dw:
                _seg.append("这个下界已经超过限电 %sW 了，所以**肯定不够**" % _dw)
            else:
                _seg.append("下界没超限电 %sW，但整机实际功耗会更高，"
                            "够不够我判断不了" % _dw)
        if o.get("adapterW"):
            _seg.append("标配 %sW 适配器（适配器标称，是上界参考，不是实际功耗）"
                        % o["adapterW"])
        if not _lower and not o.get("adapterW"):
            _seg.append("库里没有这台的功耗数据")
        _seg.append("要确切数字得看厂商规格页的「功耗」栏，或问客服要满载功耗")
        reply = reply.rstrip("。") + "。\n\n关于限电：" + "；".join(_seg) + "。"
    return {"stage": "fit", "slots": dict(slots), "reply": reply,
            "focus": focus, "focusName": b["name"],
            "picked": b["name"], "questions": [], "warnings": [],
            "outside_products": check_outside_products(reply),
            "untraceable_numbers": [], "fabricated_words": [],
            "dataAsOf": core.data_as_of()}


# 结论词表。判据要能分辨：说岔了要被抓到，说对了不能误判。
_VERDICT_TOKENS = {"match": ["匹配", "合适", "适合", "够用", "没问题"],
                   "partial": ["部分匹配", "勉强", "一般", "够呛", "打折"],
                   "mismatch": ["不匹配", "不适合", "不合适", "不太行", "不是游戏本",
                                "别拿它", "不建议", "扛不住", "跑不动"]}


def _verdict_wrong(text, verdict):
    """检查模型说出口的结论和系统判定是否一致。
    分辨力说明：mismatch 时只要出现「部分匹配/勉强/一般」这类弱化词就算错；
    但「不合适」本身含「合适」，所以先长词优先匹配，避免把自己判错。"""
    if verdict is None:
        return False
    long_first = sorted(_VERDICT_TOKENS[verdict], key=len, reverse=True)
    said_ok = any(t in text for t in long_first)
    if verdict == "mismatch":
        # 说了"不合适"之后又冒出"部分匹配/勉强"的，是自相矛盾
        soft = [t for t in _VERDICT_TOKENS["partial"] if t in text]
        return bool(soft) or not said_ok
    if verdict == "match":
        return not said_ok
    return False


def _corpus_of(offers):
    parts = []
    for o in offers:
        parts += [o.get("spec") or "", o.get("tag") or "", o.get("caution") or "",
                  o.get("name") or ""]
        parts += o.get("pros") or []
        parts += o.get("cons") or []
    return " ".join(parts)


def _fit_template(b):
    """匹配度问答的兜底。全是库里原文，不生成。"""
    VERDICT = {"match": "匹配", "partial": "算部分匹配", "mismatch": "不太匹配"}
    head = VERDICT.get(b["fitVerdict"], "")
    parts = ["%s，%s，到手 ¥%s。" % (b["name"], b["spec"], b["price"])]
    if head:
        parts.append("就你的用途看，%s。" % head)
    if b["fit"]:
        parts.append("原因：" + "；".join(b["fit"]) + "。")
    if b["cons"]:
        parts.append("有件事得先说清楚：" + b["cons"][0].rstrip("。") + "。")
    return "".join(parts)


def _too_thin(text, user_text):
    """回答太短、太敷衍 —— 用户问了一句，只得到"库里没有"五个字。

    实测 2026-11-11 演示走查：
      U「这机器保修几年」
      A「库里没有这项数据。」          ← 7 个字，等于什么都没说
    这句话**没有编造**，所以 _warranty_stretch / _tangent 全部放行，
    但它对用户毫无用处：没告诉他这台有什么服务承诺、也没告诉他该去哪儿问。

    判据：长度 < 16 字，且只有"没有/不知道/不清楚"这类否信息，没有一个具体名词。
    只在这种"又短又空"时才打回，不误伤"这台是 16G 内存"这种正常短答。

    ⚠️ 只有这一条不够（2026-11-11 演示彩排实测）：
      A「库里没有这项数据。这台机器提供「一年上门保修」服务。」
    28 个字，含"保修"，本条判据全部放行 —— 但用户拿这句话**什么也做不了**：
    还是不知道保修几年，也不知道该问谁。缺的不是长度，是**着落**。
    ⇒ 另加 _no_landing()，两条判据各管一件事，互不替代。
    """
    t = (text or "").strip()
    if len(t) >= 16:
        return False
    has_neg = any(w in t for w in ["没有", "没记", "不知道", "不清楚", "查不到",
                                   "无数据", "没有数据", "无法"])
    if not has_neg:
        return False
    # 有没有给出任何具体信息（型号/配置/年份/数字）
    has_info = bool(re.search(r"\d", t)) or any(
        w in t for w in ["保修", "售后", "网点", "客服", "上门", "条款", "详情页"])
    return not has_info


def _no_landing(text, user_text):
    """说了"库里没有"，但没告诉用户**接下来该怎么办**。

    实测 2026-11-11 演示彩排：
      U「这机器保修几年」（问的是年限，库里只有"一年上门保修"这项**服务**）
      A「库里没有这项数据。这台机器提供「一年上门保修」服务。」
    —— 28 个字，不编造、不跑题、也念了服务，前面三条判据全放行。
    但它把问题原样退回给用户了：那到底几年？我去哪儿问？

    本产品的立场是「没有数据也要给个着落」：说清楚这台有什么承诺、
    这个数只有谁能定、以及去哪个页面／问谁。这三样都不需要编数字。

    判据（两条同时成立才打回）：
      ① 回答里有"库里没有/查不到"这类否信息
      ② 全篇没有任何一个**可执行的出口**（详情页/客服/条款/官网/下单页/问厂商）
    只命中①不打回 —— 「库里没有返修率数据，但网点覆盖还算广」是合格回答。

    ⚠️ "出口"必须是**能去查的地方**，不能是描述。
    第一版把 `售后网点` 也算出口，结果这条判据放行了
      「库里没有返修率数据，但这个牌子售后网点覆盖还算广。」
    —— "网点覆盖广"是描述，不是"去哪儿查返修率"，用户照样没着落。
    ⇒ 去掉 `售后网点`，只留 `售后政策 / 售后条款`（这两个是能被查的东西）。
    """
    t = (text or "").strip()
    if not t:
        return False
    neg = re.search(r"库里(没有|没记|查不到)|没有(这项|该项)?数据|无法确定|不确定", t)
    if not neg:
        return False
    landing = re.search(
        r"详情页|商品页|下单页|客服|保修卡|发票|说明书|官网|官方网站"
        r"|售后(政策|条款)|问(一下)?(厂商|卖家|店家|客服)|咨询(厂商|客服|卖家)", t)
    return not landing


# 「开放式提问」—— 用户问的是"怎么样"，期望一段话，不是一个字段。
# 「保修几年」「多重」这类是封闭式（问一个具体值），一句话答完就算合格。
OPEN_ENDED = ["怎么样", "好不好", "如何", "值不值", "行不行", "怎么样啊",
              "推荐吗", "值得买吗", "评价", "讲讲", "说说", "介绍一下"]


def _too_brief(text, user_text):
    """用户问开放式问题，回答只有一句话 —— 信息没错，但答不动。

    实测 2026-11-11 演示彩排：
      U「屏幕怎么样」（开放式，期望听两句）
      A「屏幕素质在同价位不算突出。」            ← 13 个字，就一句
    这句**完全正确**：数据里关于屏幕就只有这一条 cons，模型没有编、
    没有超出证据。但用户问"怎么样"，得到的是一句像标题的话，
    他会觉得系统在敷衍（或者以为我没别的可说）。

    数据只有一条也必须讲成人话：这条意味着什么、要不要紧、
    什么情况下会碍事 —— 这些都是**解释**，不是新事实，不需要编数据。

    判据：用户问的是开放式问题（OPEN_ENDED），回答 < 25 字或只有一句。

    ⚠️ 封闭式问题不走这条。「多重？」「保修几年？」一句话答完是对的，
    硬撑成三段反而是废话。
    """
    t = (text or "").strip()
    if not t:
        return False
    q = user_text or ""
    if not any(w in q for w in OPEN_ENDED):
        return False
    # 只数中文句号/问号/感叹号切出来的句子，逗号不算
    sentences = [s for s in re.split(r"[。！？!?]", t) if s.strip()]
    return len(t) < 25 or len(sentences) <= 1


# 从 spec 里把屏幕段拆出来。
#
# 🔴 2026-11-13 深夜（换血收尾时体检抓到）：
#    「屏幕要 2K 以上」→ 回复「库里对机械革命 无界 14X 的屏幕没有单独记录」
#    而这台的 spec 原文是「R7 H255 · 16G + 512G · 14 寸 2880×1800 120Hz」——
#    2880×1800 就是 2K+，参数**一直在库里**，只是排在整串配置的第 3 段。
#
#    根因：追问路径把 `spec` 当一整串字符串喂给模型，模型眼里它是一行"配置描述"，
#    不会主动把它拆成"尺寸/分辨率/面板/刷新/色域"五项，于是"
#    没在这行里看到'屏幕'两个字"就答成了"没记录"。
#    这属于**有数据却说没数据**，比编造更隐蔽 —— 用户不会怀疑，只会觉得库太薄。
#
#    实测覆盖面：全库 76 台里 75 台的 spec 含屏幕段（99%），
#    只有「旷世X」那台是裸的（没有"寸"字）。所以这一改不是补个案，是补 99% 的话。
#
#    ⚠️ 只做**抽取**，不做评价。抽出来的都是型号自己写的数字，
#       「细腻/通透/跟手」这类观感词一个都不许进来（见下面 FOLLOWUP_SYS 的红线）。
_SCR_SIZE = re.compile(r"(\d{2}(?:\.\d)?)\s*寸")
_SCR_RES = re.compile(r"(\d{3,4})\s*[×xX]\s*(\d{3,4})")
_SCR_PANEL = re.compile(r"\b(OLED|IPS|LCD|TN|VA)\b", re.I)
_SCR_HZ = re.compile(r"(\d{2,3})\s*Hz", re.I)
_SCR_GAMUT = re.compile(r"(\d{2,3})\s*%\s*(sRGB|DCI-P3|NTSC|Adobe\s*RGB)", re.I)


def _screen_of(spec):
    """从 spec 字符串里抽屏幕参数。抽不到就返回 None（宁可没有，不许猜）。

    返回示例：
        {"尺寸": "14 寸", "分辨率": "2880×1800", "面板": "OLED",
         "刷新率": "120Hz", "色域": "100% DCI-P3"}

    🔴 **切屏幕段这件事只许有一份实现**（宪法第 9 条）。
       原来我在这里另写了一套正则，而 `_screen_part()` 早就有一份 ——
       两套并存的直接后果：模板路径（走 `_screen_part`）和模型路径
       （走 `_screen_of`）对**同一台机器**给出不同答案。
       现在本函数的第一行就是 `_screen_part()`，正则只负责
       把已经切好的那一段**再拆成五个字段**，不重复承担"哪一段是屏幕"的判断。

    🔴 抽不到必须返回 None，不能返回空字典 ——
       下游要能分清「这台没写屏幕参数」和「写了但解析失败」，
       前者该说"库里没记"，后者是我代码的问题，不该推给用户。
    """
    seg = _screen_part(spec)
    if not seg:
        return None
    out = {}
    m = _SCR_SIZE.search(seg)
    if m:
        out["尺寸"] = m.group(1) + " 寸"
    m = _SCR_RES.search(seg)
    if m:
        out["分辨率"] = "%s×%s" % (m.group(1), m.group(2))
    m = _SCR_PANEL.search(seg)
    if m:
        out["面板"] = m.group(1).upper()
    m = _SCR_HZ.search(seg)
    if m:
        out["刷新率"] = m.group(1) + "Hz"
    m = _SCR_GAMUT.search(seg)
    if m:
        out["色域"] = m.group(1) + "% " + m.group(2)
    return out or None


def _price_label(o):
    """价格字段的**键名** —— 让口径跟着值一起传下去，不许在一处写死。

    🔴 2026-11-16（接 ZOL 数据后当场抓到）：
       在采进来的 163 台里，有 119 台的价是**平台标价**（ZOL 快照，不含国补/券），
       不是到手价。可下面的 data 字典里键名写死了「到手价」，
       模型照着念，用户看到的是：
           「这台 ThinkBook 到手价 4898 元」
       而 4898 只是标价 —— 实际到手可能更低，也可能这个价根本没货。

       这是本项目最难抓的一类错：**数字没错，口径错了**。
       用户不会怀疑，因为他看到的是一个真实存在的数字。

    判据：键名由 `priceIsEstimate` 决定；模型看到「平台标价（不含国补/券）」
    这个键名，就不会把它说成到手价。
    """
    return "平台标价（不含国补/券）" if o.get("priceIsEstimate") else "到手价"


def _render_analysis(user_text, res, q):
    """把分析结果组织成人话。

    🔴 2026-11-21：**模型组织语言，数字全部来自 res**。

    为什么不直接把 res 丢给模型让它说：
      那样它可能"顺手"改数字（实测编过「最贵的一台」）。
      这里先把结构化结果拼成事实句子，再让模型润色 ——
      模型看到的每个数字都是算好的，它没机会编。

    ⚠️ 模型失败时退回纯事实拼接（不能因为模型挂了就答不出来）。
    """
    n = res.get("n") or 0
    agg = res.get("agg")
    field = res.get("field")
    label = {
        "price": "价格", "perf": "性能分", "weightKg": "重量",
        "ram": "内存", "batteryWh": "电池容量", "thicknessMm": "厚度",
        "refreshHz": "刷新率", "sizeInch": "屏幕尺寸",
        "brand": "品牌", "cat": "品类", "gpuKind": "显卡类型",
    }.get(field, field or "")

    # ── 拼事实（纯代码，不靠模型）──
    facts = []
    if agg == "count":
        facts.append("符合条件的共 %d 台" % n)
    elif agg in ("mean", "median", "min", "max"):
        facts.append(res.get("text") or "")
    elif agg == "groupby":
        groups = res.get("groups") or {}
        facts.append("按「%s」共 %d 组" % (
            {"brand": "品牌", "cat": "品类", "gpuKind": "显卡类型"}.get(
                q.get("group_by") or "brand", q.get("group_by") or "品牌"),
            len(groups)))
        # 只报前 5 组，避免回答变成表格倾倒
        for g, v in list(groups.items())[:5]:
            if "mean" in v:
                facts.append("%s：%d 台，%s 平均 %s（%s~%s）" % (
                    g, v["n"], label, v["mean"], v["min"], v["max"]))
            else:
                facts.append("%s：%d 台" % (g, v["n"]))
        if len(groups) > 5:
            facts.append("其余 %d 组略" % (len(groups) - 5))
    elif agg == "distribution":
        buckets = res.get("value") or {}
        facts.append(res.get("text") or "")
        for k, v in buckets.items():
            facts.append("%s：%d 台" % (k, v))
    elif agg in ("top", "bottom"):
        for i, row in enumerate(res.get("rows") or [], 1):
            facts.append("%d. %s —— %s" % (i, row["name"], row["value"]))
    if res.get("note"):
        facts.append(res["note"])

    _fact_txt = "；".join(x for x in facts if x)

    # ── 让模型润色（数字不许改）──
    SYS = """你在回答一个**数据统计**问题。下面是系统算好的事实，你只负责组织成人话。

硬规则：
1. **每个数字都必须来自「事实」，一个都不许改、不许补充、不许推算。**
   事实里写「样本 18 台」就只能说 18，不许写成 80。
   事实里没说「其余 N 台」就不许提。
2. 不许推荐具体机型（除非事实里就是排行）。
3. 不许评价"性价比高""值得买"这类 —— 这是统计，不是导购。
4. 两到四句。先给结论，再补一句样本量或口径。
5. 不许把字段名念出来（不要写"agg""field"这种）。"""
    try:
        out = chat([{"role": "system", "content": SYS},
                    {"role": "user",
                     "content": "用户问：%s\n\n事实：%s" % (user_text, _fact_txt)}],
                   num_predict=260).strip()
        # 🔴 2026-11-21：**数字校验**。模型润色时会把「18 台」写成「80 台」
        #    （实测：引擎算 18 台，回答写"80 台有明确记录"+"其余 10 台没记录"，
        #    两个数都是编的）。这类错比不回答更坏 —— 用户会当真。
        #
        #    判据：回答里出现的每个数字，必须能在「事实」文本里找到。
        #    找不到 → 这个润色作废，退回纯事实拼接。
        if out and len(out) >= 20 and _numbers_ok(out, _fact_txt):
            return out
    except Exception:
        pass
    # 模型不可用 / 数字编了 → 纯事实拼接
    return _fact_txt


def _numbers_ok(reply, facts):
    """回答里的数字必须都能在事实里找到。

    只校验**2 位以上的数字**（"1.75" 拆成 1 和 75 会误判），
    以及带单位/百分号的。个位数（1-9）不校验 —— 太容易误伤
    （「5 台」「前 3 名」这类表述里的数字经常是序号）。
    """
    if not reply:
        return False
    # 抽出回答里的所有数字（含小数）
    nums = re.findall(r"\d+(?:\.\d+)?", reply)
    for x in nums:
        if len(x.replace(".", "")) < 2:
            continue          # 个位数不校验
        if x in facts:
            continue
        # 允许「2.49」在事实里写成「2.49 kg」或「2.49kg」
        if any(x in f for f in facts.split("；")):
            continue
        return False
    return True


def answer_followup(user_text, m, asked_topics=None):

    """回答某台的细节追问。

    `asked_topics`：本轮之前**已经问过的主题**（由 _run 从 asked 里取出）。
    🔴 2026-11-17 新增，为了修死循环：
       实测（用户第三次实测）连续三轮问售后（「售后怎么样」
       「我说的是好售后吗」「我的意思是，售后网点多吗」），
       系统三次输出**完全一样**那段话。

       根因不只是数据缺失（这台确实只有「品牌 5/5」一条售后信息），
       更在于**系统不知道用户在重复问同一件事**。
       用户换三种说法，说明他对第一个回答不满意 ——
       这时候正确动作不是把同一段话再说一遍，而是：
         ① 承认刚才没答到点上
         ② 换个角度（这次答品牌覆盖，下次答"怎么自己核实"）
         ③ 或者直接说清"库里就这一条，再问也只有这个"

       ⚠️ 不许编新数据来"显得不同"。变化的只能是**措辞和角度**，
          事实永远是库里那几条。
    """
    # 🔴 按提问主题裁一次事实（见 _topic_facts 的注释）：
    #   问屏幕就只给屏幕相关的优缺点，别把"机身偏大""内存形态"一起倒出来。
    topic, pros, cons = _topic_facts(m, user_text)
    # 屏幕参数：先在代码里拼成人话再交出去。
    #
    # 🔴 2026-11-13 深夜踩到的坑：第一版传的是 dict 或 None，
    #    模型对着 `"屏幕参数": null` 写出了**「屏幕参数为 null。」**——
    #    把一个内部字段名和一个编程字面量直接念给了用户。
    #    判据：**内部字段名和 null 绝不许出现在用户可见的句子里**。
    #    做法：① 有参数就在代码里拼好，模型只负责组织语言；
    #         ② 没参数就**连这个键都不传**，让它没有机会说出字段名。
    _scr = _screen_of(m.get("spec"))
    _scr_txt = "、".join("%s %s" % (k, v) for k, v in _scr.items()) if _scr else None
    # 🔴 2026-11-17：检测"同一主题重复问"，给模型换角度的指令。
    #
    #    实测死循环：连续三轮问售后，三次输出完全一样。
    #    用户换三种说法 = 对第一个回答不满意。
    #    正确动作：承认没答到点上 + 换角度 + 说清库里的边界。
    #
    #    历史来源：`m["_askedTopics"]` —— 由 _run 从 known 里取出来塞进 offer。
    #    为什么走 known 而不是加函数参数：
    #      run()/_run() 的签名被 6 处调用 + server + 前端共用，
    #      加参数要改一圈；known 本来就是自由字典，塞个下划线键最省事。
    if asked_topics is None:
        asked_topics = m.get("_askedTopics") or []
    _repeat = 0
    if topic and asked_topics:
        _repeat = sum(1 for t in asked_topics if t == topic)
    data = {
        "机型": m["name"],
        "配置": m["spec"],
        "一句话标签": m.get("tag"),
        # 🔴 2026-11-16：空列表**不许进 data**。
        #
        #    实测（端到端两轮）：`"优点": []` / `"缺点": []` 喂给模型后，
        #    它把内部字段名念成了用户可见的句子 ——
        #        「这台缺点为空。优点为空。要提醒的坑为空。」
        #    这违反项目既有判据「内部字段名和 null 绝不许出现在用户可见的句子里」
        #    （同 _screen_of 那处的注释）。做法照旧：**没有就连键都不传**。
        #
        #    有内容时才传，且只在真有的时候。
        **({"优点": pros} if pros else {}),
        **({"缺点": cons} if cons else {}),
        # 🔴 2026-11-12（第五次判据漂移）：三条路径都用了 _clean_caution，
        #   只有追问这条路把 caution 原样喂给模型。
        #   实测代价（端到端 + 页面首屏同时复现）：
        #     问「屏幕怎么样」→「小新 16SE 有双 M.2 硬盘位，同价位更值得看」
        #   这句是数据里小新 16 的 caution 原文，但它在说**另一台**。
        #   更糟的是它绕过了 _foreign_fact：那台的语料本身就含这句，
        #   "这句是不是这台的"双向核对在这里天然失效 —— 必须在入口就洗掉。
        # ⚠️ 空值同样不传（同上面「优点/缺点」的理由：模型会念"要提醒的坑为空"）。
        **({"要提醒的坑": _clean_caution(m.get("caution"), m)}
           if _clean_caution(m.get("caution"), m) else {}),
        # 只问他问的那一项 —— 这条字段是给模型看的边界，不是给前端渲染的。
        "用户这次只问了": topic or "（整机整体）",
        # 🔴 2026-11-17：重复提问时给换角度的指令（见函数头注释）。
        **({"用户在重复问同一件事": (
            "用户已经问过 %d 次「%s」了，说明前几次没答到点上。"
            "这次**不许把同样的句子再说一遍**。请："
            "① 先承认一句「刚才没说到你要的」；"
            "② 换个角度答 —— 上次给了评分，这次就给「怎么自己核实」"
            "（去商品页看哪一栏、问客服问什么）；"
            "③ 如果库里确实只有这一条数据，就明说「关于这一项库里就这一条」，"
            "别假装还有别的。"
            "⚠️ 不许为了显得不同而编造新数据。"
            % (_repeat + 1, topic))} if _repeat >= 1 else {}),
        "品牌": m.get("brand"),
        "售后网点_满分5": m.get("brandService"),
        "保值_满分5": m.get("brandResale"),
        "品牌备注": m.get("brandNote"),
        # ── 2026-11-16 新增：用户会追问、而参数页里本来就有的维度 ──
        # 用户反馈「提示里能追问保修几年，但问了答不知道」。
        # 查下来不是没数据，是 `zol_map_fields.py` 的映射表漏了这些键 ——
        # 参数页里 60 台有「质保时间=2年」，抓回来了却没进池。
        # 这里补上，让追问能真答。
        #
        # ⚠️ 键名要像人话（「质保年数」而不是「warrantyYears」），
        #    否则模型会念「质保年数为 1.0 年」这种字段名口吻（实测过）。
        **({"质保年数": int(m["warrantyYears"])
           if float(m["warrantyYears"]).is_integer() else m["warrantyYears"]}
           if m.get("warrantyYears") else {}),
        **({"保修政策": m["warrantyPolicy"]} if m.get("warrantyPolicy") else {}),
        **({"质保备注": m["warrantyNote"]} if m.get("warrantyNote") else {}),
        **({"续航_小时": m["batteryLifeH"]} if m.get("batteryLifeH") else {}),
        **({"续航原文": m["batteryLifeText"]} if m.get("batteryLifeText") else {}),
        **({"厚度_mm": m["thicknessMm"]} if m.get("thicknessMm") else {}),
        **({"支持触控": "是" if m.get("touchScreen") else "否"}
           if m.get("touchScreen") is not None else {}),
        **({"操作系统": m["os"]} if m.get("os") else {}),
        **({"无线网卡": m["wifi"]} if m.get("wifi") else {}),
        **({"蓝牙": m["bluetooth"]} if m.get("bluetooth") else {}),
        **({"摄像头": m["webcam"]} if m.get("webcam") else {}),
        **({"扬声器": m["speakers"]} if m.get("speakers") else {}),
        **({"音频系统": m["audioSystem"]} if m.get("audioSystem") else {}),
        **({"键盘": m["keyboard"]} if m.get("keyboard") else {}),
        **({"外壳材质": m["shellMaterial"]} if m.get("shellMaterial") else {}),
        **({"上市时间": m["launchDate"]} if m.get("launchDate") else {}),
        # ── 2026-11-17 第二批：用户会追问、参数页里本来就有的 ──
        **({"充电器功率_W": m["adapterW"]} if m.get("adapterW") else {}),
        **({"充电器原文": m["adapterText"]} if m.get("adapterText") else {}),
        **({"颜色": m["shellColor"]} if m.get("shellColor") else {}),
        **({"屏幕技术": m["screenTech"]} if m.get("screenTech") else {}),
        **({"触控板": m["touchpad"]} if m.get("touchpad") else {}),
        **({"机身长_mm": m["bodyLengthMm"], "机身高_mm": m["bodyWidthMm"]}
           if m.get("bodyLengthMm") and m.get("bodyWidthMm") else {}),
        # ═══════════════════════════════════════════════════════════
        # 🔴 2026-11-21：补传屏幕结构化参数 / 接口 / 散热 / 独显直连
        #
        #    实测问题：问「屏幕怎么样」只报了尺寸分辨率，
        #    问「接口够不够」直接念配置、问「散热行不行」给了
        #    「中规中矩」这种评价 —— 而数据其实有。
        #
        #    根因：`_topic_facts` 已经把这些拼成事实了，
        #    但**数据字典里没有对应键**，模型看不到结构化值，
        #    只能自由发挥 → 发挥成评价词 → 违反"没人评过不许评价"。
        #
        #    键名用中文人话（同上面「质保年数」的教训：
        #    英文字段名会让模型念「warrantyYears 为 1.0」这种口吻）。
        # ═══════════════════════════════════════════════════════════
        **({"屏幕尺寸_寸": m["screen"]["sizeInch"]}
           if (m.get("screen") or {}).get("sizeInch") else {}),
        **({"屏幕分辨率": "%d×%d" % (m["screen"]["widthPx"],
                                    m["screen"]["heightPx"])}
           if (m.get("screen") or {}).get("widthPx")
           and (m.get("screen") or {}).get("heightPx") else {}),
        **({"屏幕刷新率_Hz": m["screen"]["refreshHz"]}
           if (m.get("screen") or {}).get("refreshHz") else {}),
        **({"屏幕面板": m["screen"]["panel"]}
           if (m.get("screen") or {}).get("panel") else {}),
        **({"屏幕色域": "、".join(
                "%s %s%%" % (k.upper() if k.lower() == "srgb" else k, v)
                for k, v in (m["screen"].get("colorGamut") or {}).items()
                if isinstance(v, (int, float)))}
           if isinstance((m.get("screen") or {}).get("colorGamut"), dict)
           and (m.get("screen") or {}).get("colorGamut") else {}),
        **({"屏幕亮度_nit": m["screen"]["brightnessNit"]}
           if (m.get("screen") or {}).get("brightnessNit") else {}),
        **({"接口": ("、".join(str(x) for x in m["ports"] if x)
                     if isinstance(m["ports"], (list, tuple))
                     else m["ports"])}
           if m.get("ports") else {}),
        **({"散热系统": m["cooling"]} if m.get("cooling") else {}),
        **({"独显直连": m["dGPU"]} if m.get("dGPU") else {}),
        # 🔴🔴 2026-11-12：追问路径原来**没告诉模型这台有没有人评过**。
        #   实测代价（端到端彩排）：「MateBook 14 2026 屏幕怎么样」被答成
        #     「最大的亮点是那块 OLED，分辨率高达 2880×1920，看着非常细腻通透」
        #     「这台定位就是高端商务本」「保值率也就中等」
        #   —— 这台在采集池，pros/cons 是空的，库里没人看过这块屏。
        #   参数（2880×1920 / OLED / 120Hz）是真的，但"细腻通透""保值率中等"
        #   "定位高端商务本"全是凭外观参数顺手编的评价 —— 同一条红线，
        #   只是从"编数字"换成了"编感受"，比编数字更难抓。
        # 🔴 2026-11-16：措辞已改（用户要求不要强调"人工/没人评"）。
        #   约束不变：不许编观感、不许判断定位、不许提保值率。
        #   只是不再要求模型念那句"这项我库里没人评过，我只报参数"。
        "有没有人写过优缺点": "有" if m.get("hasReview") else "没有",
        "如果没人写过_你必须这么说":
            ("直接报参数和价格，不要解释数据来源、也不要说「没人评过」。"
             "可以报参数、报价格、说它属于什么档次，"
             "但不许给观感评价（「细腻」「通透」「跟手」都不行），"
             "不许判断定位（「就是高端商务本」不行），"
             "不许提保值率（库里没这个数据），"
             "也不许说「不算便宜」「值得买」。")
            if not m.get("hasReview") else
            ("按「优点」「缺点」两栏说，"
             "但不许超出这两栏自己加内容。"),
    }
    # 🔴 2026-11-16：从规格推导出来的客观提示（derivedNotes）。
    #
    #    它解决的是「189 台没人写过优缺点 → 问缺点只能答'没评价'」。
    #    但它**不是评价**，是数据事实的转述，所以：
    #      · 单独一个键，不混进「优点」「缺点」两栏
    #      · 提示词明确要求：说成「从规格能看出来」，不能说成「评测说」
    #      · 不许在此之上加任何形容词（"很够用""很值"仍然禁止）
    #
    #    ⚠️ 不动 hasReview —— 出口审计仍按"没人写过评价"拦主观词。
    _dn = [d for d in (m.get("derivedNotes") or [])
           if d.get("kind") in ("con", "pro", "note")]
    if _dn:
        # 🔴 用户问缺点时，**把 con 排到最前**。
        #    实测（2026-11-16，战66）：它的 con 只有 1 条（核显），
        #    夹在 4 条的第 3 位、前后都是 pro，模型就整个放弃了，
        #    输出了「库里记的缺点是：。」这种空模板。
        #    同样的机型只要 con 在前面（星 Book Pro 14 两条 con 打头），
        #    模型就能正常逐条说。
        #    → 这是"信息顺序影响生成"的典型，不是模型不会。
        _dn = sorted(_dn, key=lambda d: {"con": 0, "pro": 1, "note": 2}
                     .get(d.get("kind"), 3))
    if _dn:
        # 🔴 必须**逐条**给，不能拼成一句话。
        #    实测（2026-11-16）：拼成「；」分隔的单串时，模型只挑了一条说
        #    （3 条只报了"未查到能效备案"）。逐条给数组，它才会全说。
        data["按规格能确认的几点"] = [d.get("text") for d in _dn]
        # 🔴 只有 pro/note、没有 con 的情况必须单独交代。
        #    实测（2026-11-16，战66）：4 条全是 pro，模型不知道说什么缺点，
        #    输出成了「库里记的缺点是：。」—— 空模板 + 句号，比不说还糟。
        _has_con = any(d.get("kind") == "con" for d in _dn)
        if not _has_con:
            data["这台没有明显短板"] = (
                "按规格看，这台**没有能确认的明显短板**（不是「缺点很多」）。"
                "**只说一次**，不许重复这句；"
                "不许编一条缺点出来凑数，也不许说「缺点是：」。")
        data["这几条怎么用"] = (
            "上面是**从硬件规格直接推出来的事实**，不是评测、不是观感。"
            "用户问缺点/短板时，如果里面有不利的（核显、内存焊死、偏重、无备案），"
            "**必须全部说出来**，一条都不许漏；有利的可以一并说。"
            "措辞用「按规格看…」「从参数上看…」；"
            "不许说「评测认为」「口碑上」「用起来」，"
            "也不许在它之上加形容词（很够用/很值/性价比高都不行）。")
    # 屏幕参数只在**真有**的时候才进数据（见上面 _scr 处的注释）。
    if _scr_txt:
        data["这块屏幕的规格"] = _scr_txt
    reply = chat([{"role": "system", "content": FOLLOWUP_SYS},
                  {"role": "user", "content":
                   "数据：" + json.dumps(data, ensure_ascii=False) + "\n\n用户问：" + user_text}],
                 num_predict=200).strip()
    corpus = " ".join([m.get("tag") or "", m.get("caution") or ""]
                      + (m.get("pros") or []) + (m.get("cons") or []))
    # 追问路径的完整审计。**首轮和重写后必须共用这一个函数。**
    # 判据抄两遍一定会漂 —— 见 compose() 里 _audit 的注释，那里踩过一次。
    def _f_audit(t):
        return dict(
            # 传 m 进去：结构化保修年限存在时不该判"语义扩大"（见函数注释）
            stretch=_warranty_stretch(t, corpus, m),
            tangent=_tangent(t, user_text),
            thin=_too_thin(t, user_text),
            nolanding=_no_landing(t, user_text),
            brief=_too_brief(t, user_text),
            # 🔴 串台：说的是**别的机型**的信息（2026-11-11 演示彩排出的事故）
            foreign=_foreign_fact(t, m),
            # 🔴🔴 参数当卖点（2026-11-12 补）。
            #   这条在 compose() 的 _audit 里早就有了，但**这里漏了** ——
            #   正是「判据抄两遍就一定会漂」那个老毛病的第二次复现。
            #   后果实测：追问「MateBook 14 2026 屏幕怎么样」，
            #   模型输出了「看着非常细腻通透」「保值率也就中等」「定位就是高端商务本」，
            #   六条判据全部放行，因为每个数字都是真的。
            praise=_praise_no_review(t, m),
            vague=_vague_praise(t),
            # 🔴🔴 2026-11-12（第六次漂移）：偷换推荐对象这条判据
            #   compose() 和 _intro_model() 都挂了，追问这条路又漏了。
            #   实测代价：数据 caution 里那句「小新 16SE …同价位更值得看」
            #   被原样念出来，所有判据放行 —— 用户问的是小新 16，
            #   回答在首屏安利另一台。
            #   ⚠️ 光在入口洗 caution 不够：模型可能从 spec / pros 里再拼一次，
            #      出口必须有一条判据兜底 —— 入口洗 + 出口拦，两处都要。
            pitch=_other_model_pitch(t, {"ranked": [m]}),
            brand=_brand_mismatch(t, m),
            # 🔴🔴 2026-11-17：补齐三条**在 compose / _answer_current 有、
            #    这条路一直漏**的判据。
            #
            #    这是"判据抄两遍一定会漂"的第七次复现。查法：把四条路径
            #    （compose / answer_followup / _answer_current / _intro_model）
            #    各自用到的判据列成矩阵，一眼就看出谁漏了谁。
            #
            #    · _power_guess：追问「限电 500W 够用吗」时同样会编
            #      「功耗设计通常远超这个限制」—— 库里没有功耗字段。
            #    · check_fabrication：编造数字（这条路径原来完全没有）
            #    · _overspec：超出库内证据的断言（"绝对够劲""完全没压力"）
            power=_power_guess(t),
            fabrication=check_fabrication(t, _corpus_of([m])),
            overspec=_overspec(t),
        )

    a1 = _f_audit(reply)

    if any(a1.values()):
        why = []
        if a1["stretch"]:
            why.append("把「一年上门保修」这项服务说成了保修期")
        if a1["tangent"]:
            why.append("扯了他没问的东西（他没问故障率/返修率，就不用提）")
        if a1["thin"]:
            why.append("只回了句「没有数据」——那等于什么都没说")
        if a1["nolanding"]:
            why.append("说了「库里没有」却没告诉他接下来该去哪儿查")
        if a1["brief"]:
            why.append("他问的是「怎么样」这种开放问题，你只回了一句话")
        if a1["foreign"]:
            why.append(
                "「%s」是**%s** 的信息，不是这台 %s 的 —— "
                "你把这台没有的东西说成它有，比编造更糟"
                % (a1["foreign"]["frag"], a1["foreign"]["from"], m["name"]))
        if a1["praise"]:
            why.append(
                "「%s」是**评价**，不是参数 —— 这台库里**没人写过优缺点**，"
                "你替它下了结论。观感（细腻/通透/跟手）、定位（就是高端商务本）、"
                "保值率、划算不划算，这些库里一个字都没有，一个都不许说。"
                "只报参数，不要解释数据来源" % a1["praise"])
        if a1["pitch"]:
            why.append(
                "你把**另一台型号**当成了这台的卖点或坑 —— 数据里那条讲的是别的机器，"
                "搬到这台头上等于偷偷换了推荐对象。用户问的是 %s，"
                "不许拿别的机型来比较、更不许说「更值得看」" % m["name"])
        if a1.get("vague"):
            why.append(
                "「%s」是**凭定位猜的结论**，不是数据 —— "
                "库里没有任何散热/性能实测。这类泛泛评价（中规中矩/符合预期/"
                "核心优势/能维持）读起来像实测，用户会当真。"
                "只能说数据里有的（散热系统描述、TDP/TGP、厚度），"
                "然后明说实测表现判断不了。"
                % a1["vague"])

        # 🔴 2026-11-18：把当前这台说成别的品牌
        if a1.get("brand"):
            why.append(
                "你把当前这台说成了**%s**，但它的品牌是**%s** —— "
                "品牌归属说错了会直接误导售后/保值判断。"
                "用户上一句提到的品牌不等于这台的品牌，不许把它安到这台上。"
                % (a1["brand"]["said"], a1["brand"]["actual"]))
        # 🔴 2026-11-17 补的三条（对应上面 _f_audit 新增的判据）
        if a1.get("power"):
            why.append(
                "你推测了**整机功耗**或对「限电够不够」下了结论（%s）——"
                "库里没有整机功耗、没有实测瓦数，"
                "只有「充电器功率_W」（适配器标称，不等于整机功耗）。"
                "只许说适配器标称多少瓦，"
                "然后明说「整机实测功耗库里没有，我判断不了」，"
                "再指路（厂商规格页的功耗栏、问客服要满载功耗）。"
                "**不许写「大概率跑不满」「功耗设计通常远超」「严重阉割」这类推测。**"
                % a1["power"])
        if a1.get("fabrication"):
            why.append(
                "回答里有库里查不到的数字（%s）—— 每个数字都必须能在数据里找到出处"
                % str(a1["fabrication"])[:60])
        if a1.get("overspec"):
            why.append(
                "「%s」是超出库内证据的断言 —— 库里没有帧数/实测/返修率，"
                "只能说配置本身" % str(a1["overspec"])[:40])
        reply2 = chat([{"role": "system", "content": FOLLOWUP_SYS + STRICT_TAIL},
                       {"role": "user", "content":
                        "数据：" + json.dumps(data, ensure_ascii=False)
                        + "\n\n刚才那句有问题：" + "；".join(why) + "。"
                          "重写：库里有就讲清楚这条**对你意味着什么**（要不要紧、"
                          "什么情况下碍事），别只把字段抄一遍；库里没有的明说没有，"
                          "但要**给个着落**——这台有什么服务承诺就说，没有就指路"
                          "（商品详情页的保修栏、问客服），不要只说一句没有就完了。"
                          "⚠️ 只能用上面「数据」里属于这台的内容，"
                          "别的机型的东西一个字都不许搬过来。\n\n用户问：" + user_text}],
                      num_predict=200).strip()
        # 重写后必须用**同一个**审计再查一遍
        if any(_f_audit(reply2).values()):
            reply2 = _followup_template(m, user_text)
        reply = reply2
    # 🔴 2026-11-17：重复提问时，**代码层兜底换角度**，不指望模型听话。
    #
    #    实测：连续三轮问售后，第 2 轮模型听话换了角度（"刚才没说到你要的"），
    #    第 3 轮又复读第 1 轮的措辞 —— 提示词约束不稳定。
    #
    #    判据：用户第 N 次（N≥2）问同一主题，且这次回答的开头与上一轮雷同
    #    （前 20 字相同）→ 说明在复读，强制改写。
    #
    #    ⚠️ 改写只换**措辞和角度**，不加任何新事实：
    #      库里只有"品牌 5/5"这一条，就只能说这一条。
    if _repeat >= 1 and topic:
        _head = re.sub(r"\s+", "", reply)[:20]
        # 这一轮之前已经说过什么 —— 从 data 里拿不到历史原文，
        # 但可以用"回答是否又回到那句兜底模板"来判断。
        # 🔴 判据改成「只要重复问同一主题就换角度」，不再靠标记词。
        #
        #    实测教训：原来用 `_fallback_markers` 判断"是不是又在念兜底模板"，
        #    结果 DEBUG 显示 `_repeat=2` 但 `fb=False` —— 因为模型这次换了措辞，
        #    标记词没命中，兜底就不触发，用户看到的还是重复。
        #
        #    根因：**"是不是重复"不该由回答内容判断，该由提问历史判断。**
        #    用户已经问过 N 次同一主题，就是重复，不管这次模型说了什么。
        if _repeat >= 1:
            # 第 3 次及以上还在念兜底模板 → 直接用代码拼一句诚实的
            _bs2 = m.get("brandService")
            _facts = []
            if _bs2 is not None:
                _facts.append("品牌售后网点评分 %s / 5（5 = 覆盖最广）" % _bs2)
            _facts.append("这台具体整机几年，库里没有记录")
            # 按重复次数递进，避免第 2、3 次又说同一句（那还是循环）
            _n = _repeat + 1
            _lead = ("刚才没说到你要的，" if _n == 2
                     else "这已经是第 %d 次问这一项了，" % _n)
            if _n == 2:
                reply = (
                    "%s我直接说结论：%s。"
                    "关于「售后网点多不多」——这个评分说的就是网点覆盖广度，"
                    "5 分是最高档。再往细问（具体哪几个城市、上不上门），"
                    "库里就这些了，得看厂商的保修条款或问客服。"
                    % (_lead, "；".join(_facts)))
            else:
                # 第 3 次及以上：不再重复内容，直接把边界说死 + 给出路
                reply = (
                    "%s库里关于售后**就这一条**：%s。"
                    "我没有更多能说的了 —— 再问也是这个答案。"
                    "要确切数字只能走两条路：① 商品详情页找「保修」栏；"
                    "② 问客服要书面答复（口头承诺不算）。"
                    % (_lead, "；".join(_facts)))
    # 🔴 2026-11-17：**facts 有值但回答没提到** → 补一句。
    #
    #    实测：「键盘怎么样」这台有 `keyboard='全尺寸键盘> ，背光键盘'`，
    #    `_topic_facts` 也正确返回了，但模型输出的是
    #    「这一项的具体表现要看实机或第三方评测」—— 完全没读 facts。
    #
    #    这和限电那次是同一个模式：提示词约束不稳定。
    #    所以代码兜底：检查回答里有没有覆盖 facts 的关键内容，
    #    没有就补一句（只用 facts 里的事实，不加评价）。
    if topic and pros and len(reply) < 400:
        # 取 facts 里的数字/关键词，看回答有没有覆盖
        _missed = []
        for _f in pros[:2]:
            # 抽出这条事实里的"硬信息"（数字、英文型号、关键名词）
            _keys = re.findall(r"[A-Za-z]{2,}|\d+[A-Za-z]*", _f)
            if not _keys:
                # 没有硬信息，取前 6 个字做覆盖判断
                _keys = [_f[:6]]
            if not any(k.lower() in reply.lower() for k in _keys if len(k) >= 2):
                _missed.append(_f)
        # 只补第一条漏的，避免回答变成流水账
        if _missed and "要看实机" in reply:
            reply = reply.replace(
                "这一项的具体表现要看实机或第三方评测。",
                "库里记的是：%s。这一项用起来怎么样要看实机或第三方评测。"
                % _missed[0].rstrip("。"))
    return reply


# 用户没问这些，回答却主动说"库里没有" → 画蛇添足
UNASKED_TOPICS = {
    "故障率": ["故障", "返修", "坏"],
    "保修": ["保修", "售后", "维修", "修"],
    "屏幕": ["屏幕", "色域", "色彩"],
    "续航": ["续航", "电池"],
}


# 跨品类越界比较：用户问笔记本，回答却说"同价位台式机能给到 XX"。
# 实测 2026-11-11「8000 的游戏本」：末句写"这个价位的台式机能给你 32G 内存加桌面版显卡"，
# 但内核这轮根本没取台式机的数据，这句是模型凭常识补的 —— 说了也不算数。
CROSS_CAT = ["台式机能给你", "台式机的配置", "同价位台式", "换成台式机能",
             "台式机可以给", "台式的显卡", "桌面版显卡", "台式机至少要"]


def _cross_cat(text, result):
    """用户没问台式机，回答却拿台式机做比较 → 越界。
    只有本轮结果里确实带上了台式机条目时才放行。"""
    hits = [w for w in CROSS_CAT if w in text]
    if not hits:
        return []
    names = " ".join((r.get("name") or "") for r in (result.get("ranked") or []))
    if "台式" in names or "主机" in names or "DIY" in names:
        return []
    return hits


def _brand_mismatch(text, m):
    """回答把当前这台说成了**别的品牌**。

    🔴 2026-11-18 实测抓到（用户实测日志第 8 条）：
      当前机器是「暗影精灵11 锐龙版」，brand=惠普。
      用户上一句问「有没有**机械**革命的同配置的」——
      模型在回答里写：「这台机器属于**机械革命**暗影精灵系列」。

      暗影精灵是惠普的产品线，跟机械革命没关系。
      模型把用户刚提的品牌名，安到了当前机器头上。

    为什么这比"编数字"更危险：
      品牌归属是用户判断售后/保值的核心依据，说错了会直接误导决策。
      而且它读起来毫无破绽 —— 用户如果不熟这两个品牌，根本发现不了。

    判据：回答里出现「这台/该机/它 + 属于/是/来自 + 某品牌」这种归属句式，
    而那个品牌 ≠ 当前机器的 brand → 抓。

    只查品牌名，不查产品线名（暗影精灵/拯救者/天选这些是系列，
    模型说「属于暗影精灵系列」是对的）。
    """
    t = text or ""
    if not m:
        return None
    mine = (m.get("brand") or "").strip()
    if not mine:
        return None
    # 库里所有品牌名（用来识别"回答里提了哪个品牌"）
    try:
        brands = set()
        for o in core.pool_offers():
            b = (o.get("brand") or "").strip()
            if b and len(b) >= 2:
                brands.add(b)
    except Exception:
        return None
    if not brands:
        return None

    # 归属句式：这台/该机/它/本机 + (可选的"机器"/"笔记本"等) + 属于/是/来自/出自
    #
    # 🔴 第一版正则是 `(?:这台|该机|...)[^。；\n]{0,6}(?:属于|是|...)`，
    #    结果「这台属于机械革命」抓不到 —— 因为 `{0,6}` 贪婪吃掉了"属于"，
    #    后面的动词组又匹配不到，整体失配。
    #    改成把中间部分收窄成"可选的品类词"，不用泛化的 `{0,6}`。
    pat = re.compile(
        r"(?:这台|该机|这款|它|本机|此机)"
        r"(?:机器|笔记本|电脑|机型)?"
        r"(?:属于|是|来自|出自|为)"
        r"([\u4e00-\u9fa5A-Za-z]{2,10})")
    for mm in pat.finditer(t):
        cand = mm.group(1)
        # 找出这个候选里包含了哪个品牌名
        for b in brands:
            if b in cand and b != mine:
                return {"said": b, "actual": mine, "frag": mm.group(0)[:30]}
    return None


def _strip_violations(text, audit):
    """外科手术式修正：只删掉违规的句子/数字，保留其余内容。

    🔴 2026-11-18 新增。为什么需要它：

      旧逻辑「审计命中 → 整段换模板」代价太大。
      实测模型写的：
        「它属于高配游戏本，适配 240Hz 高刷新率屏幕，适合对画面流畅度
          有要求的玩家。适配器标称 280W，但整机实际功耗数据未记录…」
      第一句是**好的**，只有 280W 是编的（这台 adapterW=None）。
      整段丢掉 → 用户看到 117 字的配置罗列 → 感受是「死板」「low」。

      判据：**能精确删的就不要整段丢**。删不干净（剩余太短或还有违规）
      再由调用方退回模板。

    做法：
      ① 按句切分（。！？\\n）
      ② 逐句重新审计，只保留干净的句子
      ③ 如果删完不足原长 40%，认为手术失败，返回 None
    """
    if not text:
        return None
    # 按中文句末标点切句，保留标点
    parts = re.split(r"(?<=[。！？\n])", text)
    kept = []
    for seg in parts:
        if not seg.strip():
            continue
        a = audit(seg) if callable(audit) else audit
        if any(a.values()):
            continue          # 这句有违规 → 丢掉
        kept.append(seg)
    out = "".join(kept).strip()
    if not out:
        return None
    # 删太多说明原回答主要靠违规内容撑着，手术没意义
    if len(out) < max(60, int(len(text) * 0.4)):
        return None
    return out


def _vague_praise(text):
    """**泛泛的正面/中性评价** —— 没有具体名词，但实质是在下结论。

    🔴 2026-11-21 实测抓到（这台 hasReview=False，库里没有任何评测）：

      「这台机器散热表现**中规中矩**」
      「它作为游戏本的核心优势就是**能维持高负载下的性能释放**」
      「这点是**符合预期**的」
      「你只能参考它的配置和定位来**推测**它的散热能力」

    每一句都是**凭定位猜的结论**，但 `_praise_no_review` 抓不到 ——
    它靠「细腻/通透/高端」这类具体形容词匹配，而这些句子用的是
    「中规中矩」「符合预期」「核心优势」这种**更隐蔽的措辞**。

    为什么必须拦：用户问"散热行不行"，得到"中规中矩"，
    会当成实测结论去做购买决策 —— 而库里一个散热数据都没有。
    这比"库里没有"坏得多。

    判据：出现"评价性断言" + 句子里没有对应的数据支撑词。
    """
    t = text or ""
    # 这些词本身是"下结论"，不是"报数据"
    VAGUE = (
        r"中规中矩|符合预期|符合定位|表现不错|表现良好|表现一般|"
        r"核心优势|主要卖点|最大亮点|"
        r"能维持|足以应对|完全够用|绰绰有余|"
        r"推测它|大致可以判断|基本能扛|应该没问题"
    )
    m = re.search(VAGUE, t)
    if not m:
        return None
    return m.group(0)


def _other_model_pitch(text, result):
    """把「另一台更值得买」说成了推荐理由 —— 偷偷换了推荐对象。

    实测 2026-11-11（演示前实跑）：
      数据 caution 原文：「小新 16SE 有双 M.2 硬盘位，同价位更值得看」
      模型输出：「要提醒的坑是：小新 16SE 有双 M.2 硬盘位，同价位更值得看」
    这句话每个字都有出处（所以 verify_answer 放行），但它把"另一台更好"
    包装成了"这台的坑"，等于在首位推荐的段落里主推了另一个型号。

    判据：出现「更值得 / 更好 / 推荐 / 不如买」这类比较词，
    且同一个分句里出现了**当前首位机型名字之外**的型号线索。
    不能只按词判 —— 数据原话本身就含这些字，要能区分"复述"和"主推"。
    """
    ranked = (result or {}).get("ranked") or []
    if not ranked:
        return False
    cur = ranked[0].get("name") or ""
    # 拆分句，避免跨句误判
    for seg in re.split(r"[。；！？\n]", text or ""):
        if not seg.strip():
            continue
        if not re.search(r"更值得|更划算|更推荐|不如买|推荐买|更合适|更好|更强", seg):
            continue
        # 这一分句里有没有"当前机型"？有就说明在说它自己，放行。
        # 🔴 2026-11-12：原来只写 `if cur in seg`，会被**型号前缀**骗过 ——
        #   cur=「联想小新 16」，seg=「联想小新 16SE 更值得看」，
        #   子串命中就放行，等于"16SE"冒充"16"。
        #   （现有测试用的是「小新 16SE」不带联想，恰好躲过这个洞。）
        #   改判：命中处后面紧跟 SE/Pro/Plus/数字/字母 → 那是另一个型号，不算它自己。
        _self = False
        if cur and cur in seg:
            for _mm in re.finditer(re.escape(cur), seg):
                _tail = seg[_mm.end():_mm.end() + 4]
                if re.match(r"\s?(?:SE|Pro|Plus|Max|Air|锐龙|酷睿|Ultra|\d|[A-Za-z])",
                            _tail):
                    continue      # 只是前缀，说的是 16SE 这种另一台
                _self = True
                break
        if _self:
            continue
        # 🔴 虚指变体（2026-11-12 实测）：
        #   「且这个价位同价位更值得看的机型**可能不在当前推荐里**」
        # —— 没点名任何型号，所以上面那条"型号线索"判据放行了。
        # 但它比点名更糟：用户不知道说的是哪台，只知道"我可能被坑了还没被告知"。
        # 这种悬空比较必须拦 —— 要么说清楚是哪台，要么别说。
        if re.search(r"更值得看.{0,12}(机型|的|可能)|"
                     r"不在(当前|这次)?推荐|没在推荐里|还有个更好|"
                     r"(更好|更强|更划算)的(机型|机器|选择)", seg):
            return True
        # 有没有别的型号线索（英文+数字组合，或"XX SE / Pro / Plus / 系列"）
        if re.search(r"[A-Za-z]{1,6}\s?\d{2,4}(?:SE|Pro|Plus|Max|Air)?", seg) \
                or re.search(r"(?:SE|Pro|Plus|Max)\b", seg) \
                or re.search(r"另一台|别的型号|另一款", seg):
            return True
    return False


def _tangent(text, user_text):
    """回答扯了用户没问的话题。只抓明显的：说了"库里没有X"但X不是用户问的。"""
    for topic, kws in UNASKED_TOPICS.items():
        asked = any(k in user_text for k in kws)
        if asked:
            continue
        # 出现"库里没有…故障率" 这类，且用户没问
        if ("库里没有" in text or "库里没" in text) and topic in text:
            return True
        if "库里没有" in text and any(k in text for k in kws):
            return True
    return False


def _warranty_stretch(text, corpus, m=None):
    """「保修一年」「保修期一年」在数据里找不到原话 → 语义扩大。

    数据里只有「一年上门保修」这种说法时，那是服务，不是整机保修期。

    🔴 2026-11-16 修：这条判据原来**只认字面串**（corpus 里有「保修一年」才放行）。
       但 2026-11-16 起参数页补进了结构化字段 `warrantyYears`（60 台有），
       数据是 `warrantyYears=1` + `warrantyPolicy="全球联保"`，
       语料里**根本没有「保修一年」这四个字** ——
       于是模型说「整机质保 1 年」被这条判成"把服务说成保修期"，
       触发重写，重写后反而输出"库里没记录"。
       用户问「保修几年」得到"不知道"，根因就在这里。

       修法：**结构化字段有值就放行** —— 那是厂商参数页写的质保年数，
       比语料里的一句描述更权威。
    """
    import re as _re
    hits = _re.findall(r"保修\s*(期)?\s*(一年|1\s*年|两年|两年|三年|两年)", text)
    if not hits:
        return False
    # 结构化保修年限存在 → 模型说几年是**有据**的，不算扩大
    if m is not None and m.get("warrantyYears"):
        return False
    # 数据原话里如果有"保修一年"就不算扩大
    if "保修一年" in corpus or "保修期一年" in corpus:
        return False
    return True


def _foreign_fact(text, m):
    """回答里的信息属于**别的机型**，不属于当前这台。

    🔴🔴 为什么必须有（2026-11-11 演示彩排，本产品最严重的一次事故）：
      问：联想小新 16「这机器保修几年」
      答：「库里没有这项数据。这台机器提供「一年上门保修」服务。」

    这句话看起来完美：不编造、不跑题、还给了落点。但它说的
    **「一年上门保修」根本不是小新 16 的数据** ——
    全库只有一处写着这句，是 `offers[6]` **惠普战 66** 的 pros[2]。

    也就是说模型把 A 机器的售后信息，安到了 B 机器头上。
    这比编造更危险：
      · 编造容易被"数据里没有这个词"抓住
      · 串台用的是**真实存在的数据**，所有现成判据全部放行
      · 用户查证时能在库里找到这句，反而更信任 —— 但它是错的

    ⚠️ 判据必须**双向核对**，不能只看"数据里有没有"：
      · 只查"库里有这句" → 通过（战 66 有）→ 漏
      · 要查"这句是不是这台的" → 才能抓到

    实现：找出这句 / 这个短语是否是**别的机型独有**的。
    方法：把回答切成 6 字以上的片段，逐段检查 —— 若某段在这台的语料里
    找不到，却能匹配到**另一台**的语料，就是串台。

    只对追问路径用（数据面窄、可比对），并且要求片段足够长，
    避免"屏幕""内存"这类通用词互相碰撞。
    """
    t = (text or "").strip()
    if not t or not m:
        return None
    my_id = m.get("id")
    mine = _one_corpus(m)
    if not mine:
        return None

    # 收集别的机型的语料（只取有评价的那层，22 台，成本很低）
    try:
        others = []
        for o in core.load().get("offers") or []:
            if o.get("id") == my_id or o.get("cat") not in core.ALLOWED_CATS:
                continue
            c = _one_corpus(o)
            if c:
                others.append((o.get("name") or "", c))
    except Exception:
        return None
    if not others:
        return None

    # 从回答里切出"可能是事实陈述"的片段。
    # 🔴 固定长度 n-gram 这条路走不通，两个方向都试过：
    #   · N=6 → 误判 95%（撞上「屏幕素质在同」这类跨机型套话）
    #   · N=8 → 漏掉真正的事故（「一年上门保修」只有 6 字，短语生成不出来）
    #   根源：**事实的长度不确定**。"一年上门保修" 6 字，
    #   "一年上门保修，不用自己跑网点" 13 字，都是一件事。
    #
    # ⇒ 不用固定窗口，改成按**语义单元**取：先把别家语料按标点切成短句，
    #    再取每个短句里的「关键短语」（数字/专有词开头的那一小段）。
    #    这样长度跟着内容走，不跟窗口走。
    #
    # 判据三段：
    #   ① 这段在回答里出现
    #   ② 这台自己的语料里没有（不是它说的）
    #   ③ 全库只有**这一台**有（不是通用说法）
    ans = re.sub(r"\s+", "", t)
    all_corpora = [mine] + [c for _, c in others]

    # 「具体事实」的标志：数字，或这些专有名词
    CONCRETE = re.compile(
        r"\d|保修|上门|军标|认证|插槽|固态|独显|核显|色域|sRGB|刷新率|"
        r"分辨率|触控|雾面|镜面|泼溅|网点|模具|热管|雷电|"
        r"内存|硬盘|电池|续航|重量|Hz")

    for oname, ocurpus in others:
        # 按标点切短句，每句内再找"具体事实"片段
        for seg in re.split(r"[，。；、！？!?：:\n]", ocurpus):
            if len(seg) < 4:
                continue
            # ① 先尝试取"含具体标志"的最短片段（"一年上门保修"这种）
            cands = []
            for start in range(len(seg)):
                for end in range(start + 5, min(start + 16, len(seg)) + 1):
                    c = seg[start:end]
                    if CONCRETE.search(c):
                        while end - 1 > start + 4 and CONCRETE.search(seg[start:end - 1]):
                            end -= 1
                        cands.append(seg[start:end])
                        break
            # ② 兜底：整句本身就是短事实（"机身塑料感明显" 7 字、"接口给得比较全" 7 字）
            #    这类不含数字也不含专有词，但整句就是一件事。
            #    不加这条召回只有 46%（2772 次压测漏了 1491 次），
            #    漏的全是这种"描述型事实"。
            if len(seg) <= 18:
                cands.append(seg)

            for g in cands:
                if len(g) < 4:
                    continue
                if g in mine:                    # 这台也说了 → 不是串台
                    continue
                # 「多台共用」有两种情况，必须分开：
                #   ① 行业套话（"屏幕素质在同价位"）→ 不是谁的独有事实，说了不算串台
                #   ② 多台各自都有的事实（"内存板载"、"满载风扇噪音偏大"）
                #      → 仍然算串台！因为对**这台**来说它可能是假的。
                # 实测 2026-11-11：第一版一律排除共用短语，漏了 63 条 ——
                # 全是「满载风扇噪音偏大」和「内存板载」这两句，
                # 它们是 3 台各自的真实缺点，但对其它 19 台都是错的。
                # ⇒ 只有"含具体标志的短语"才享受"共用即通用"的豁免；
                #   "描述型短句"即使共用也照抓。
                if CONCRETE.search(g) and sum(1 for c in all_corpora if g in c) > 1:
                    continue
                if g in ans:
                    return {"frag": g, "from": oname}
    return None


def _one_corpus(o):
    """一台机器的可引用语料。

    🔴 字段之间必须留分隔符，不能直接拼。
    实测 2026-11-11：原来用空格 join 再去空白，字段边界就没了 ——
      战 66 的 pros 是「军标认证，键盘防泼溅」+「一年上门保修，不用自己跑网点」
      → 去空白后粘成「键盘防泼溅一年上门保修」
      → 从这个粘出来的假句子里取短语，取到的是跨字段的假片段，
        真正的「一年上门保修」反而没被识别成独立片段。
    改成用「。」连接：既保留字段边界（切句时能切开），
    又不引入英文标点导致后续正则失配。
    """
    if not o:
        return ""
    parts = [o.get("tag") or "", o.get("caution") or "", o.get("spec") or ""]
    parts += list(o.get("pros") or []) + list(o.get("cons") or [])
    # 🔴 2026-11-16：`derivedNotes` 也必须是这台的可引用语料。
    #
    #    实测事故（战66 八代 14 英寸）：这台 pros/cons 为空，语料只剩 spec 那 48 字，
    #    于是回答里「1.48kg」在自己语料里找不到，却命中了人工层
    #    「惠普战 66 八代锐龙版」的 cons「1.48kg 在 14 寸里偏重」
    #    → `_foreign_fact` 判成串台 → 触发重写 → 重写后输出「库里记的缺点是：。」
    #
    #    但 1.48kg 明明是**这台自己的** weightKg 推导出来的。根因是语料没收录
    #    derivedNotes，导致自家事实被当成别人家的。
    for d in (o.get("derivedNotes") or []):
        if isinstance(d, dict) and d.get("text"):
            parts.append(d["text"])
    s = "。".join(x for x in parts if x)
    return re.sub(r"\s+", "", s)


def _screen_part(spec):
    """从 spec 里**只切出屏幕那一段**，不要整条念。

    🔴🔴 为什么必须有（2026-11-12 实测）：
      天选 7 的 spec 是
        「R7 H260 · 16G + 512G · RTX 5050 · 2.5K 165Hz OLED」
      用户问「屏幕怎么样」，回答把**整条 spec** 念了出来 ——
      问屏幕，得到的是 CPU 和内存。原因是最外层判据写成
        `if any(k in spec for k in SCR_KW)`   # SCR_KW 含「OLED」
      只要 spec 里带 OLED 就整条命中，于是整句被当屏幕参数。
      判据必须落在**片段**上，不能落在整条上。

    做法：按 「·」 切段，逐段判是不是屏幕属性，只留中的段。
    ⚠️ 光按「·」切还不够：采集池生成的 spec 里屏幕跟显卡之间是用**空格**接的
      （「R9-9955HX · 16G + 1T · RTX 5070 16 寸 2560×1600 IPS 300Hz 100% sRGB」），
      整段会连着显卡一起被留下 —— 用户问屏幕，答里冒出「RTX 5070」。
      所以每段还要再按「屏幕从哪儿开始」切一刀，把前面的非屏幕部分剥掉。
    """
    s = (spec or "").strip()
    if not s:
        return ""
    # 屏幕相关的**部件属性**词。注意不能收「屏」这个单字 ——
    # 「黑屏」里也有屏字，那是故障现象不是屏幕规格（2026-11-11 踩过）。
    SCR = ["寸", "英寸", "×", "x2", "OLED", "IPS", "LCD", "VA", "MiniLED",
           "Hz", "刷新率", "分辨率", "2.5K", "2.8K", "2K", "3K", "4K", "1080",
           "16:9", "16:10", "sRGB", "DCI-P3", "AdobeRGB", "色域", "亮度",
           "nit", "雾面", "镜面", "触控", "防眩光"]
    BAD = ["黑屏", "花屏", "闪屏", "蓝屏", "死机", "虚焊", "通病"]
    # 「屏幕从哪儿开始」的锚点，取最早命中的那个位置
    ANCHOR = re.compile(
        r"\d+(?:\.\d+)?\s*(?:寸|英寸)"
        r"|\d{3,4}\s*[×xX]\s*\d{3,4}"
        r"|\b(?:2\.5K|2\.8K|2K|3K|4K|1080P|1440P|FHD|QHD)\b",
        re.I)
    keep = []
    for seg in re.split(r"\s*[·/|]\s*", s):
        seg = seg.strip()
        if not seg or any(b in seg for b in BAD):
            continue
        # 反例：「1TB」里含 T、但含 1T 不该算屏幕；这里靠 SCR 里没有裸 T 保证。
        if not any(k in seg for k in SCR):
            continue
        a = ANCHOR.search(seg)
        if a and a.start() > 0:
            seg = seg[a.start():].strip()
        keep.append(seg)
    return " · ".join(keep)


def _clean_caution(caution, m):
    """（2026-11-12 已迁到 core.clean_caution，这里只做转发，保留旧名字给测试用）

    为什么搬走：清洗必须发生在**接口返回的数据**上，而不只是喂给模型的提示词里。
    实测：模型没提 16SE，但前端卡片直接渲染了 caution 原文
    「小新 16SE 有双 M.2 硬盘位，同价位更值得看」——
    出口数据没洗，前端就有机会把别家的卖点当这台的坑展示出来。
    现在 core.build_recommendation 里已经洗过一次，这里是唯一入口，别再各写一份。
    """
    return core.clean_caution(caution, m)


def _clean_brand_note(note, m):
    """品牌级备注里如果夹带了**具体机型**的内容，不能当本机信息说。

    实测 2026-11-11（演示前实跑）：联想品牌的 note 原文是
      「同一个品牌里，E14 能加内存、X1C 不能 —— 别按品牌判断，按型号判断。
        小新 16SE 的双 M.2 硬盘位是今年的卖点。」
    后一句在说**另一台**（16SE），但它混在品牌备注里，
    用户问「这台保修几年」时，兜底模板把整段念了出来 ——
    等于在回答里安利了另一台，而且是库里未必有的型号。

    判据：品牌 note 按句拆开，含「型号线索」但又**不是这台**的句子丢掉。
    型号线索 = 英文+数字（E14/X1C/16SE）或「XX Pro/SE/Plus」。
    """
    note = (note or "").strip()
    if not note:
        return ""
    name = m.get("name") or ""
    keep = []
    for seg in re.split(r"[。；]", note):
        seg = seg.strip()
        if not seg:
            continue
        # 这一句里的型号线索
        others = re.findall(r"[A-Za-z]{1,6}\s?\d{1,4}(?:SE|Pro|Plus|Max|Air)?"
                            r"|\d{2}\s?(?:SE|Pro|Plus)", seg)
        if not others:
            keep.append(seg)
            continue
        if name and name in seg:
            keep.append(seg)
            continue
        # 🔴 含别的型号 —— **默认丢弃**，只有明确是"方法论/品牌整体判断"才保留。
        #    （2026-11-12 修：原来这里是默认保留，只在命中几个词时才丢，
        #      结果华为的 note「MateBook D16 在 4589 元给到 1TB，是这一档里存储最宽的选择」
        #      被原样念进了「MateBook 14 2026 保修几年」的回答里 ——
        #      用户问 A 的售后，回答在讲 B 的存储。
        #      方向必须反过来：品牌备注里提别的型号，可疑的默认扔。）
        #
        # 保留的两种例外，都必须有明确的"非本机配置"特征：
        #   「E14 能加内存、X1C 不能 —— 别按品牌判断」→ 后半句是方法论
        #   「这个品牌整体性价比不错」→ 没提具体型号（上面 others 就不会命中）
        hints = re.findall(r"(别按\w+判断[^，。；]*|按型号判断|要按?\w*型号\w*)", seg)
        if hints:
            keep.extend(hints)
            continue
        if re.search(r"品牌整体|这个牌子整体|整个品牌|同代都", seg):
            keep.append(seg)
            continue
        # 其余一律丢弃 —— 它在讲某台的**具体配置/价格**，不是这台，也不是品牌概括
        continue
    return "，".join(k.strip("，。；——") for k in keep if k.strip("，。；——"))


def _followup_template(m, user_text):
    """追问的兜底：只回数据原文，不外推。

    这里的目标不是"答满"，而是**答得有用**：
    库里没有保修年限时，只回一句"库里没有这项数据"等于什么都没说。
    能说的是：这台有什么服务承诺（有就念）、品牌这块整体什么情况（有就说）、
    以及**你该怎么办**（去问谁、看哪）。这三样都不需要编数字。
    """
    corpus = (m.get("pros") or []) + (m.get("cons") or [])
    q = user_text
    # 问保修/售后 → 只讲库里有的服务描述
    if any(w in q for w in ["保修", "售后", "维修", "修"]):
        svc = [p for p in (m.get("pros") or []) if "保修" in p or "售后" in p]
        # 品牌 note 可能夹带别的机型，先过滤（见 _clean_brand_note）
        note = _clean_brand_note(m.get("brandNote"), m)
        parts = []
        # 🔴 2026-11-16：这个兜底分支原来**只看 pros 里有没有"保修/售后"字样**，
        #    不认 2026-11-16 才补进来的结构化字段（warrantyYears 等）。
        #    结果：60 台有质保年数，问「售后怎么样」却答"库里没有记录"，
        #    还跟着一段"我不敢替厂商说"——用户问了等于没答。
        #    修法：结构化字段优先，有就直接报。
        wy = m.get("warrantyYears")
        wpol = m.get("warrantyPolicy")
        wnote = m.get("warrantyNote")
        # 🔴 2026-11-17 修死循环：`brandService` 也要现算。
        #
        #    实测（用户第三次实测）：连续三轮问售后，第 1、3 轮都答
        #    「保修年限这一项，库里对 联想拯救者Y9000P 没有记录」——
        #    因为这台 wy/wpol/wnote 全是 None，而 brandService 在原始 offer 里
        #    也是 None（只在 brief() 里临时算过）。
        #    但 core.brand_info(m) 能查到「联想 service=5」。
        #
        #    判据：**有品牌级售后数据就说品牌级，不要因为缺"具体年限"就说没有。**
        #    「售后网点多吗」问的本来就是品牌覆盖，不是质保年数。
        _bs = m.get("brandService")
        # 🔴 品牌 note 必须过 _clean_brand_note 过滤 —— 它常夹带**别的机型**。
        #    实测（test_neg 抓到）：MateBook 14 问保修，回答里出现了
        #    「MateBook D16 在 4589 元给到 1TB」—— 那是另一台的信息。
        #    这条测试本来就在，是我这次兜底绕过了过滤才复发的。
        _bnote = _clean_brand_note(m.get("brandNote"), m)
        if _bs is None or not _bnote:
            try:
                _bi = core.brand_info(m) or {}
                if _bs is None:
                    _bs = _bi.get("service")
                if not _bnote:
                    _bnote = _clean_brand_note(_bi.get("note"), m)
            except Exception:
                pass
        if wy or wpol or wnote:
            seg = []
            if wy:
                yi = int(wy) if float(wy).is_integer() else wy
                seg.append("整机质保 %s 年" % yi)
            if wpol:
                seg.append(str(wpol).rstrip("。"))
            if wnote:
                seg.append(str(wnote).rstrip("。"))
            parts.append("%s 的保修：%s。" % (m["name"], "；".join(seg)))
            if _bs is not None:
                parts.append("品牌售后网点评分 %s / 5。" % _bs)
            if svc:
                parts.append("另外：%s。" % "；".join(x.rstrip("。") for x in svc))
            return "".join(parts)
        # 没有具体年限，但有品牌级覆盖数据 → 答品牌级，别答"没记录"
        if _bs is not None or svc or _bnote:
            if _bs is not None:
                parts.append("%s 的品牌售后网点评分 %s / 5（5 = 覆盖最广）。"
                             % (m["brand"], _bs) if m.get("brand")
                             else "品牌售后网点评分 %s / 5。" % _bs)
            if svc:
                parts.append("库里关于 %s 的售后只有这些：" % m["name"])
                parts.append("；".join(svc) + "。")
            if _bnote:
                parts.append("品牌这块还有一句：")
                parts.append(_bnote.rstrip("。") + "。")
            parts.append("具体到这一台是整机几年，得看厂商的保修条款 —— "
                         "商品详情页的「保修」栏或问客服要书面答复才作数。")
            return "".join(parts)
        if not svc and not _bnote:
            parts.append("保修年限这一项，库里对 %s 没有记录。" % m["name"])
        # 不给年限也给个着落 —— 不然用户拿着一句"没有"就走了。
        # 这里不指定具体年数（那是编），只指路。
        parts.append("具体几年我不敢替厂商说 —— 这个数只有厂商的保修条款能定。"
                     "下单页的商品详情里有「保修」一栏，或者问客服要书面答复，"
                     "这两个地方的说法才作数。")
        return "".join(parts)
    if any(w in q for w in ["缺点", "短板", "问题", "不好"]):
        return ("%s 库里记的缺点是：%s。"
                % (m["name"], "；".join(c.rstrip("。") for c in (m.get("cons") or []))))
    # 问屏幕：只能讲数据里关于屏幕的那几条，不能把整份数据念一遍。
    # 实测 2026-11-11：兜底分支把 6 条优缺点全念了，用户问屏幕得到一段流水账。
    if any(w in q for w in ["屏幕", "色域", "色彩", "屏"]):
        # 词表在模块顶部（SCR_KW / SCR_BAD_KW / _is_screen_fact），
        # 模型那条路和这里共用同一份 —— 不再各写一遍。
        scr = [c for c in (m.get("cons") or []) if _is_screen_fact(c)]
        scr += [p for p in (m.get("pros") or []) if _is_screen_fact(p)]
        if scr:
            head = "库里关于 %s 屏幕就记了这些：" % m["name"]
            body = "；".join(x.rstrip("。") for x in scr) + "。"
            # 补一句它意味着什么 —— 这是解释，不是新事实，不需要编数据。
            tail = ""
            if any("不算突出" in x or "不突出" in x for x in scr):
                tail = ("说白了是同价位正常水平，写代码看文档没问题；"
                        "真要做调色，颜色不如标称高色域的机器准。")
            elif any("明显短板" in x or "低色域" in x or "窄" in x for x in scr):
                tail = ("这条对做设计/剪片是要紧的 —— 成片颜色会偏，"
                        "换台机器看可能和你调的色不一样。")
            return head + body + tail
        # 🔴 没有人工评价 ≠ 没有屏幕参数（2026-11-12 实测，很严重的一类错）
        #   问「MateBook 14 2026 屏幕怎么样」，原来答：
        #     「库里对这台屏幕没有单独记录 —— 是没查，不是查了没问题」
        #   可它的 spec 里明明写着「14.2 寸 2880×1920 OLED 120Hz 100% DCI-P3」。
        #   把**已有的数据说成没查**，和编造是同一条红线的两个方向：
        #   编造是"没有说有"，这个是"有说没有" —— 用户会因为这句放弃一台好机器。
        #   采集池那 78 台全部走这条缝：它们的 spec 带完整屏幕参数，但 pros/cons 为空。
        # ⚠️ 只能用 _screen_part() 切出屏幕那一段，**不能拿整条 spec 去判**
        #   （2026-11-12 二次实测：`any(k in spec for k in SCR_KW)` 里 SCR_KW 含
        #    「OLED」，天选 7 的 spec 带 OLED 就整条命中，于是问屏幕答出了
        #    「R7 H260 · 16G + 512G · RTX 5050」—— 问屏幕，答的是 CPU 和内存。）
        scr_spec = _screen_part(m.get("spec"))
        if scr_spec:
            return ("%s 的屏幕，参数是有的：%s。\n"
                    "这块屏的实测色准和观感，库里没有数据，"
                    "所以优点缺点我不替它说 —— 参数在这儿，好不好你去店里看一眼最准。"
                    % (m["name"], scr_spec))
        # 数据里一个字都没提屏幕 → 明说没查，不能沉默（沉默会被读成"没问题"）
        return ("库里对 %s 的屏幕没有单独记录 —— 是**没查**，不是查了没问题。"
                "这个参数在商品详情页的「规格参数」里有，认「色域」那一行就行。"
                % m["name"])
    # 🔴 兜底：用户问的是别的某项（散热/键盘/续航…），库里没有按项分类的记录。
    #   2026-11-12 实测：原来这里把 pros+cons **6 条全念一遍** ——
    #     问「散热怎么样」，答里混进了「到手价最低的一台」「留给内存插槽」。
    #   数量问题是次要的，**串台**才是要害：用户会以为那些也是在讲散热。
    #   做法：能按关键词捞到相关的就只念相关的，捞不到就限定条数并声明。
    kw = []
    for w in ["散热", "发热", "温度", "风扇", "噪音", "键盘", "手感", "续航",
              "电池", "重量", "接口", "充电", "性能", "跑分", "内存", "硬盘",
              "存储", "扬声器", "音响", "摄像头"]:
        if w in q:
            kw.append(w)
    hit = [c for c in corpus if any(k in c for k in kw)] if kw else []
    if hit:
        return ("%s 库里跟这一项相关的只有这些：%s。"
                % (m["name"], "；".join(x.rstrip("。") for x in hit)))
    head = "%s，%s。" % (m["name"], m.get("spec") or "")
    if corpus:
        return (head + "库里跟这一项相关的只有这些：%s。"
                % "；".join(x.rstrip("。") for x in corpus[:3]))
    # 🔴 2026-11-16：原来这句是「这台库里只有配置和价格，没有任何人写过评价 ——
    #    这一项好不好用得看实机或第三方评测」。用户要求不要解释数据来源，
    #    也不要把"没人写过"说出来。改成只报规格、不评价。
    return head + "这一项的具体表现要看实机或第三方评测。"

ASK_TEMPLATE = {
    "品类": "是笔记本还是台式？大概想放在宿舍用，还是要能带着走？",
    "预算": "预算大概多少？给个上限就行，不用太精确。",
    "用途": "主要拿来干什么？上课写作业、打游戏、剪视频，还是写代码？",
}

# 死循环兜底：同一项问过两次还没答上来，就按最常见情况假设，直接往下走。
# PRD §10.1 硬门槛要求「死循环澄清 0」——不靠前端传参正确，代码自己保证。
DEFAULTS = {"cat": "thin", "budget": 99999, "purpose": ["office"]}
DEFAULT_NOTE = {"cat": "按轻薄本算", "budget": "不限预算", "purpose": "按办公学习算"}


def apply_defaults(slots):
    s = dict(slots)
    assumed = []
    for k, v in DEFAULTS.items():
        cur = s.get(k)
        if cur is None or cur == [] or cur == "":
            s[k] = v
            assumed.append(k)
    return s, assumed


def chat(messages, fmt=None, num_predict=200, temperature=0):
    payload = {"model": MODEL, "stream": False, "think": False,
               "messages": messages,
               "options": {"num_predict": num_predict, "temperature": temperature}}
    if fmt:
        payload["format"] = fmt
    req = urllib.request.Request(
        API, data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=180) as r:
        return json.loads(r.read().decode("utf-8")).get("message", {}).get("content", "")


def extract_slots(user_text):
    out = chat([{"role": "system", "content": SLOT_SYS},
                {"role": "user", "content": user_text}],
               fmt="json", num_predict=160)
    try:
        s = json.loads(out)
    except Exception:
        return {}, "槽位解析失败: " + out[:80]
    if isinstance(s.get("purpose"), str):
        s["purpose"] = [s["purpose"]]
    s = normalize_slots(s)
    s = guard_budget(s, user_text)
    s = guard_purpose(s, user_text)
    return s, None


# 模型的枚举污染：实测把「学设计」写成 cat="design"，
# 于是品类校验失败，用户看到"品类不在覆盖范围"这种莫名其妙的回答。
# 枚举字段必须白名单，不许模型发明。
VALID_CAT = {"thin", "gaming", "desktop", "upgrade"}
VALID_PURPOSE = {"office", "gaming", "dev", "video", "design"}

# 硬约束（过滤条件，不是权重）。这些键跨轮必须继承，
# 否则「不要封装内存」「要 32G」「不要荣耀」会在下一轮悄悄失效。
# 新增硬约束时加到这里，不要再去写单点 if。
# 🔴 2026-11-18：加 `_minVram`（显存下限）。
#    专业要求里的 vramMin（如「车辆工程」要 4G 显存）必须跨轮继承，
#    否则第二轮「换一台」时约束就丢了 —— 那正是这次事故的形态之一。
HARD_KEYS = ("_minUpgrade", "_minRam", "_excludeBrand", "_cheapest",
             "_wantDgpu", "_minVram")


def normalize_slots(s):
    """把模型抽出来的槽位收敛到合法枚举。不合法的值降级处理，不要让它污染内核。"""
    cat = s.get("cat")
    if cat is not None and cat not in VALID_CAT:
        # 常见污染：cat 里写了用途词（design/game/office/study）
        low = str(cat).lower()
        if low in VALID_PURPOSE or low in ("study", "game", "work"):
            m = {"game": "gaming", "study": "office", "work": "office"}
            mapped = m.get(low, low)
            if mapped in VALID_PURPOSE:
                pl = s.get("purpose") or []
                if mapped not in pl:
                    pl.append(mapped)
                s["purpose"] = pl
        # 品类本身丢弃 → 让它缺，走追问，而不是报"不在覆盖范围"
        s["cat"] = None
        s["_cat_bypass"] = cat

    pl = s.get("purpose") or []
    if isinstance(pl, str):
        pl = [pl]
    s["purpose"] = [x for x in pl if x in VALID_PURPOSE]

    # 数字字段类型收敛
    for k in ("budget", "years", "dormWatt"):
        v = s.get(k)
        if isinstance(v, str):
            digits = re.sub(r"[^\d]", "", v)
            s[k] = int(digits) if digits else None
        elif isinstance(v, float):
            s[k] = int(v)
    return s


# 用户原话里根本没出现的预算数字 = 模型幻觉。
# 实测 2026-11-11：「轻薄本，越便宜越好」被抽成 budget=500，
# 于是推了 ¥3000 那台，还判成"超预算"。
# 这类错误按 PRD §3.1 属于模型越权写数字，必须拦，不能靠调提示词。
BUDGET_FREE = ["越便宜越好", "便宜就行", "看着办", "无所谓", "不差钱", "越贵越好"]
# 🔴 2026-11-13 晚（留出集 D）：「你看着办吧」被当成"越便宜越好"。
#
#    上面"看着办"这个裸词太宽 —— 它有两种意思：
#      ① "价格你看着办" = 价格不设限（= _cheapest，该推最便宜）
#      ② "整件事你看着办" = 我不管了，你来定（= 没有新信息，该反问/承接）
#    D 集测的正是 ②。判错后果：用户把选择权交回来，
#    系统理解成"要最便宜的"，直接把预算清了、推了全库最低价那台 ¥3000。
#
#    判据：**只有这句话带着"钱/预算/价格"语境时，"看着办"才指价格。**
#    不带钱的"看着办"是委托，不是降价要求 —— 交给意图层（4d 那条）处理。
#    所以下面用 BUDGET_FREE_CTX 做二次确认，而不是直接信 BUDGET_FREE。
MONEY_CTX = re.compile(r"价钱?|预算|花|块钱?|元|贵|便宜|省")

# 「便宜点」不能算"没有预算"：用户说「8000 的轻薄本，太贵了便宜点」，
# 意思是在 8000 以内挑更便宜的，不是放弃 8000 这个上限。
# 实测 2026-11-11（第五轮回归）：把它放进 BUDGET_FREE，预算被清成 null、
# 变成 _cheapest，推了全库最低价 ¥3000 那台 —— 用户要的是"便宜一点的 8000 内机器"。
# 这个 bug 之前被 known 兜底掩盖，兜底修好后立刻露出来。
BUDGET_LOWER = ["便宜点", "便宜些", "便宜一点", "再便宜", "降点价", "低一点"]

# 「都行」「随便」单独不能算数：用户说「除了荣耀其他都行」时也含"都行"，
# 但那是品牌排除，跟预算无关。实测 2026-11-11 就栽在这上面：
# 预算 5000 被丢掉、变成 _cheapest，推了 ¥3000 那台。
CN_NUM = {"零": 0, "一": 1, "两": 2, "二": 2, "三": 3, "四": 4, "五": 5,
          "六": 6, "七": 7, "八": 8, "九": 9}


UNIT = {"万": 10000, "千": 1000, "百": 100, "十": 10}
SMALL_UNIT = {"千": 1000, "百": 100, "十": 10}

# 「三四千」「五六千」「七八千」—— 两个数字连写表示区间。
# 实测 2026-11-11：_seg_val 把「三四」读成 34，于是「三四千」算出 34000，
# 「五六千」算出 56000，全错了一个量级。这是中文口语的固定格式，必须单独识别。
RANGE2 = re.compile(r"^([一二两三四五六七八九])([一二两三四五六七八九])([万千百])$")


def _range2_val(seg):
    """「三四千」→3500（区间中值）。不是金额语境时返回 None。"""
    m = RANGE2.match(seg)
    if not m:
        return None
    u = SMALL_UNIT[m.group(3)]
    lo, hi = CN_NUM[m.group(1)], CN_NUM[m.group(2)]
    if hi <= lo:          # 「九三」不是区间，交给原逻辑
        return None
    return (lo + hi) * u // 2


# 「六七千」「五六千」「三四千」—— 区间必须同时给出**下界、上界、中值**。
#
# 🔴 2026-11-13 用户实测：说「六七千的有什么」，预算变成空（budget=None）。
#    根因不是抽取失败，是**抽得太窄**：RANGE2 只产出中值 6500，
#    模型按用户意图给了 6000 或 7000，被 guard_budget 判成"原话里没有这个数"清掉，
#    于是预算丢失 → 系统反问"你预算多少"，用户刚说过。
#
#    这和「5000 到 7000」是同一类表达，那里本来就存 lo/hi/中值三个数，
#    这里只存中值就是两条判据不一致。中值是"我替你定的一个数"，
#    lo/hi 才是用户真说出来的两个数。
RANGE2_SCAN = re.compile(
    r"([一二两三四五六七八九])([一二两三四五六七八九])([万千百])")


def _range2_nums(t):
    """给出中文区间表达的全部合法取值：下界、上界、中值。

    「六七千」→ {6000, 6500, 7000}；「三四千」→ {3000, 3500, 4000}。
    只认 hi > lo 的（「九三」不是区间）。
    """
    out = set()
    for m in RANGE2_SCAN.finditer(t):
        u = SMALL_UNIT[m.group(3)]
        lo, hi = CN_NUM[m.group(1)], CN_NUM[m.group(2)]
        if hi <= lo:
            continue
        a, b = lo * u, hi * u
        if 500 <= a <= 200000 and 500 <= b <= 200000:
            out.update({a, b, (a + b) // 2})
    return out


def _seg_val(seg):
    """算不带「万」的一段：「七千五」→7500、「二千五」→2500、「五百五」→550、
    「三四千」→3500。"""
    r = _range2_val(seg)
    if r:
        return r
    val = 0
    sec = 0
    last = None
    for ch in seg:
        if ch.isdigit():
            sec = sec * 10 + int(ch)
        elif ch in CN_NUM:
            sec = sec * 10 + CN_NUM[ch] if sec else CN_NUM[ch]
        elif ch in SMALL_UNIT:
            u = SMALL_UNIT[ch]
            val += (sec or 1) * u
            sec = 0
            last = u
    if sec:
        val += sec * (last // 10) if last else sec
    return val


def _cn_to_int(s):
    """中文口语金额 → 整数。支持「五千」「七千五」「五千八」「一万二」「一万二千五」「1.2万」「六千万」。

    2026-11-11 第二次重写：先按「万」切段、每段用 _seg_val 算完整段值，再进位。
    上一版按字符流一趟累加，在「六千万」上算出 16000（正确是 6×1000×10000），
    根因是"万"前的"六千"被当成了系数 6。
    """
    if not s:
        return None
    s = s.replace("块", "").replace("元", "").replace("钱", "").strip()
    # 「1.2万」「0.8万」
    m = re.fullmatch(r"(\d+(?:\.\d+)?)\s*万", s)
    if m:
        return int(round(float(m.group(1)) * 10000))
    if "万" in s:
        left, _, right = s.partition("万")
        total = _seg_val(left) * 10000
        if not right:
            return total
        # 「一万二」：万后孤立一位裸数字，按千补
        if re.fullmatch(r"[零一两二三四五六七八九\d]", right):
            total += (int(right) if right.isdigit() else CN_NUM[right]) * 1000
            return total
        total += _seg_val(right)
        return total or None
    return _seg_val(s) or None


def _budget_in_text(text):
    """用户原话里到底有没有金额。返回所有可能被理解为预算的数。"""
    # 千分位先并掉，否则「12,000」会被 \d{3,6} 拆成 12 和 000 两个"金额"，
    # 实测就是这个让 12000 的预算认不出来、反而判成 0。
    t = re.sub(r"(?<=\d),(?=\d{3})", "", text)
    # 「六千万像素」不是预算。实测 2026-11-11 这条被当成 6000 元预算，
    # 直接把"要拍照好"的需求换成了一次预算判断。先把非金额的「万」剔掉。
    t = re.sub(r"[零一两二三四五六七八九十百千\d.]+\s*万\s*(像素|毫安|mAh|赫兹|Hz|转)",
               "", t)
    t = re.sub(r"[零一两二三四五六七八九十百千\d.]+\s*(万)?\s*(像素|毫安时)", "", t)
    # 🔴 规格单位跟着的数字不是预算。实测 2026-11-12：「6000mAh 大电池」
    #   被抽成 budget=6000，用户一句电池需求变成了一次预算判断。
    #   电池容量/功耗类单位彻底剔掉（数字+单位连写是规格，不是钱）。
    t = re.sub(r"\d+(?:\.\d+)?\s*(?:mAh|毫安|瓦时|Wh)", "", t, flags=re.I)
    # 刷新率同理：「165Hz」是屏幕参数，不是 165 元的预算
    t = re.sub(r"\d+(?:\.\d+)?\s*(?:Hz|赫兹|转)", "", t, flags=re.I)
    nums = set(int(x) for x in re.findall(r"\d{3,6}", t))
    # 区间「5000 到 7000」——模型取上限或中值都算有出处
    m = re.search(r"(\d{3,6})\s*[到\-~]\s*(\d{3,6})", t)
    if m:
        lo, hi = int(m.group(1)), int(m.group(2))
        nums.update({lo, hi, (lo + hi) // 2})
    # 🔴 2026-11-13 晚：「五千到八千之间」——**中文数字的"到"区间**上面那条正则认不了（只认 \d）。
    #    实测：抽取本身是对的（5000、8000 都在），但模型按区间给了 6500，
    #    guard_budget 判"原话里没这个数" → 预算被清空 → 系统反问"预算多少"，
    #    而用户刚刚才说过一个完整的区间。
    #    这和「六七千」是同一件事：**区间里的中值也是用户说过的话**，
    #    只要 lo/hi 都在原话里，区间内任何值都是有出处的。
    for m in re.finditer(
            r"([零一两二三四五六七八九\d]{1,3}[千])\s*[到\-~至]\s*"
            r"([零一两二三四五六七八九\d]{1,3}[千])", t):
        try:
            lo, hi = _cn_to_int(m.group(1)), _cn_to_int(m.group(2))
        except Exception:
            continue
        if lo and hi and 500 <= lo <= 200000 and 500 <= hi <= 200000 and lo < hi:
            nums.update({lo, hi, (lo + hi) // 2})
            # 🔴 2026-11-13 晚：区间里**任意整千的数**都算有出处。
            #    实测「五千到八千之间」，模型给 7000 —— 一个正常人会答的数，
            #    而且明确落在用户说的区间里。但抽取只给了 {5000, 6500, 8000}，
            #    7000 被判成"原话里没有这个数"，预算被清空 → 系统反问"预算多少"，
            #    用户刚说了一个完整区间。
            #    判据：用户说的是**范围**，范围内的取值就是用户授权过的。
            #    这里只放整千的（人嘴里说"六七千"时心里想的是 6000/7000 这种锚点），
            #    不是放整个区间 —— 否则"预算范围"就变成"任何数字都能通过校验"，
            #    guard_budget 的锚定作用就废了。
            k = (lo // 1000 + 1) * 1000
            while k < hi:
                nums.add(k)
                k += 1000
    # 「1.2万」「0.8 万」这种小数万
    for m in re.finditer(r"(\d+(?:\.\d+)?)\s*万", t):
        v = int(float(m.group(1)) * 10000)
        if 500 <= v <= 200000:
            nums.add(v)
    # 中文金额：「七千」「一万二」「五千八」「七千五」「一万五」「一万二千五」
    # (?<![\d.]) 防止「1.2万」里的 "2万" 被再算一次 20000
    for m in re.finditer(
            r"(?<![\d.])[零一两二三四五六七八九\d]{1,3}[万千百][零一两二三四五六七八九千百\d]{0,3}", t):
        v = _cn_to_int(m.group(0))
        if v and 500 <= v <= 200000:
            nums.add(v)
    # 「六七千」「五六千」这类中文区间：下界/上界/中值都算有出处，只给中值不够。
    # 详见 _range2_nums 的注释（2026-11-13 用户实测「六七千的有什么」预算丢失）。
    nums.update(_range2_nums(t))
    # 「六千上下浮动五百」「七千左右，能多五百」—— 基准 ± 浮动。
    # 实测 2026-11-11：模型给出 6500（=6000+500，完全正确），
    # 但语料里只有 6000 和 500，于是被判成编造、预算被清空。
    # 只要出现「上下/浮动/左右/多/少」这类词，就把 基准±浮动 都算成有出处。
    if re.search(r"(上下|浮动|左右|出头|以内|多|少|加|减)", t):
        base = [n for n in nums if n >= 1000]
        delta = [n for n in nums if n < 1000]
        for b in base:
            for d in delta:
                nums.add(b + d)
                if b - d >= 500:
                    nums.add(b - d)
    return nums


# 「不要七千的」「七千以上的别给我」——金额是被排除的对象，不是预算上限。
# 实测 2026-11-11：这句被读成 budget=7000，然后推了一台 6799 的，
# 正好落在"七千"这条线上，用户明确说过不要。
#
# 🔴 2026-11-13 晚：「别超过六千」被这里吃掉，预算直接丢了。
#    根因：前瞻 `(?<!不)超过` 只排除了「不超过」，没排除**「别超过」「不要超过」
#    「不能超过」「最多」** —— 而这几个恰恰都是"上限"的意思，是最标准的预算表达。
#    用户说「别超过六千」（= 预算 6000），系统把它当成"排除 6000 这个价位"，
#    于是预算被清空 → 反问"预算多少"。用户刚说完。
#    判据：**"不超过/别超过/最多"是上限，不是排除。** 只有"不要七千的""七千以上别给"
#    这种"整段排除某个价位带"才算排除。
#
#    ⚠️ 上一版尝试用前瞻 `(?<![不别])超过` 排除，结果把
#      「七千以上的别给我」整句打空了（"以上"前面是"千"不是"不别"）——
#      前瞻挂在"超过"上，救不了"以上"。所以这里**不用前瞻**，
#      改成先全抓、再用 BUDGET_CAP 白名单把"上限"那部分剔掉（见 _neg_budget）。
BUDGET_NEG = re.compile(
    r"(不要|不用|不想|别给|别要|除了|嫌|太贵|超过|高于|以上|以下|以内)[^，,。；;]{0,6}"
    r"([零一两二三四五六七八九\d]{1,6}[万千百]?|[0-9][0-9,]{2,6})")


# 「别超过六千」「不超过六千」「最多六千」「上限六千」——这些是**上限**，要当预算用，不当排除。
#
# 注意 pattern 里每条都要有**自己的捕获组**，_neg_budget 会把它们全部收进 caps 白名单。
# 上一版把 5 条分支写在同一个 group 序号上，`next(...)` 只取到第一个非空组，
# 「不能超过7000」因此只拿到 "0"（"以上"那支的空组）→ 排除集算成 {0}，等于没排。
# 现在每支独立编号，逐支扫。
BUDGET_CAP = re.compile(
    r"(?:别|不要|不能|不许|不可以)\s*超过\s*([零一两二三四五六七八九\d]{1,6}[万千百]?)"
    # 🔴 2026-11-13 晚（留出集 D）：「我不想花超过六千」被当成"否定 6000"。
    #
    #    原因：BUDGET_NEG 里有"不想"，匹配到"不想…超过六千"，把 6000 收进排除集；
    #    而 BUDGET_CAP 的白名单只有「别/不要/不能/不许/不可以 超过」，
    #    没有「不想超过」—— 6000 没能被捞回上限。
    #    结果：budget=None，系统反问"预算大概多少"，而用户刚说了 6000。
    #
    #    判据不变：「(否定词) + 超过 + 金额」= 上限。否定词要补齐同义说法，
    #    否则同句式的变体会掉进排除集。这里补三类：
    #      「不想/不打算/不准备 超过」  「花/用/出 不超过」  单独的「不想花超过」
    r"|(?:不|没)?(?:想|打算|准备|愿意)\s*(?:花|用|出|给)?\s*超过\s*([零一两二三四五六七八九\d]{1,6}[万千百]?)"
    r"|不超过\s*([零一两二三四五六七八九\d]{1,6}[万千百]?)"
    r"|最多\s*([零一两二三四五六七八九\d]{1,6}[万千百]?)"
    r"|上限\s*([零一两二三四五六七八九\d]{1,6}[万千百]?)"
    r"|(?:花|用|出)\s*(?:不超过|最多)\s*([零一两二三四五六七八九\d]{1,6}[万千百]?)"
    r"|([零一两二三四五六七八九\d]{1,6}[万千百]?)\s*(?:以内|以下)")


def _cap_amounts(user_text):
    """「别超过六千」「七千以内」里的上限金额集合（这些不是排除，是预算）。"""
    out = set()
    for m in BUDGET_CAP.finditer(user_text or ""):
        raw = next((g for g in m.groups() if g), "")
        v = _cn_to_int(raw) if raw else None
        if v:
            out.add(v)
    return out


def _neg_budget(s, user_text):
    """抽「被排除的金额」，并把误抽成预算的那个值清掉。

    只处理一种情况：这句话里既有「不要/如果超过」又有金额。
    此时金额不能当预算上限用 —— 要么去问，要么当排除线。
    """
    if not BUDGET_NEG.search(user_text):
        return None
    out = {_cn_to_int(m.group(2)) or 0 for m in BUDGET_NEG.finditer(user_text)}
    # 「别超过六千」里的 6000 是**上限**，不是被排除的金额 —— 先从排除集里剔掉。
    out -= _cap_amounts(user_text)
    out.discard(0)
    return out or None


# 「要独显」不等于「要打游戏」。实测 2026-11-12 16:34：用户（AI 专业）说
# 「我想要带独立显卡的」，模型捏造 purpose=gaming，回答开头断言"你要打游戏"。
# 游戏词表：purpose 里的 gaming 必须能在原话里找到出处，找不到就剥掉。
GAMING_WORDS = ("游戏", "网游", "3A", "吃鸡", "原神", "steam", "Steam",
                "电竞", "黑神话", "永劫", "lol", "LOL", "FPS", "fps")


def guard_purpose(s, user_text):
    """用途字段必须能在用户原话里找到出处，找不到就剥掉（与 guard_budget 同哲学）。"""
    pl = s.get("purpose") or []
    if "gaming" in pl and not any(w in (user_text or "") for w in GAMING_WORDS):
        s["purpose"] = [p for p in pl if p != "gaming"]
        s["_gaming_stripped"] = True
    return s


def guard_budget(s, user_text):
    """预算必须能在用户原话里找到出处。找不到就置空，让它去问，而不是编一个。"""
    b = s.get("budget")
    nums = _budget_in_text(user_text)
    # 「不要七千的」：金额出现在否定语境里，不是预算上限。
    # 这里不清空所有金额 —— 只在这个预算是被否定的那个数时才丢。
    neg = _neg_budget(s, user_text) or set()
    if neg and b in neg:
        s["_budget_dropped"] = b
        s["_budget_negated"] = b
        s["budget"] = None
        return s
    # 「越便宜越好」：只在原话里确实没有金额时才算数
    #
    # 🔴 2026-11-13 晚：加了 `_money_ctx` 这道闸（留出集 D「你看着办吧」）。
    #    BUDGET_FREE 里的"无所谓/看着办/不差钱"都是**省了宾语的**，
    #    必须确认省略掉的那个宾语是"钱"。不带钱味的"你看着办吧"
    #    是"这事情你决定"，不是"价格随便"，不许动预算。
    _money_ctx = bool(MONEY_CTX.search(user_text or ""))
    if any(w in user_text for w in BUDGET_FREE) and not nums and _money_ctx:
        s["budget"] = None
        s["_cheapest"] = True
        return s
    # 用户这轮给了明确金额，说明不再"看着办"了 -> 撤掉 _cheapest。
    # 不清的话，第一轮说过的"越便宜越好"会被 HARD_KEYS 继承到后面每一轮，
    # mode_of() 一直走 value 权重，用户后来给的预算只当过滤用、不当优先项。
    if nums and s.get("_cheapest"):
        s.pop("_cheapest", None)
    # 「太贵了，便宜点」——预算上限不变，但这轮按价格优先排。
    # 这是"在预算内找更便宜的"，不是"没有预算"。
    if any(w in user_text for w in BUDGET_LOWER):
        s.pop("_cheapest", None)
        s["_cheaper"] = True
    # 🔴 原话里一个金额都没有，模型却给了预算 —— 只能是编的。
    #   guard_budget 只在 extract_slots 的新鲜槽位上调用（跨轮继承合并不走
    #   这里），所以此时 s 里的 budget 只可能来自本轮原话；原话没金额还
    #   给预算，就是「6000mAh → budget=6000」那类规格数字污染的变形。
    if not nums:
        if b is not None:
            s["_budget_dropped"] = b
            s["budget"] = None
        return s
    if b is None:
        # 🔴 「预算七千，最多不超过八千」——模型有时不抽中文金额（实测
        #   2026-11-12 返回 budget=None）。预算词后面紧跟的金额就是预算，
        #   这里按规则兜底抽一次，且必须是 _budget_in_text 能追溯到的数。
        #   2026-11-13 补：原来只认「预算|花费|控制在」这三个词当锚点，
        #   用户说「预算提高到7000」时锚点和数字中间夹着"提高到"，
        #   抽不出来 → 预算丢 → 后面被放宽分支当成"没说具体数"改成 8000。
        #   锚点必须是"预算语义"而不是三个固定词，所以补上常见的动词。
        if re.search(r"预算|花费|控制在|加到|涨到|提高到|提到|放到", user_text):
            m = re.search(
                r"(?:预算|花费|控制在|加到|涨到|提高到|提到|放到)"
                r"[^0-9零一二三四五六七八九]{0,4}"
                r"([0-9][0-9,]{2,6}|[零一两二三四五六七八九]{1,3}[万千百][零一两二三四五六七八九千百\d]{0,3})",
                user_text)
            if m:
                raw = m.group(1).replace(",", "")
                v = int(raw) if raw.isdigit() else _cn_to_int(raw)
                if v and 500 <= v <= 200000 and v in nums:
                    s["budget"] = v
                    return s
        return s
    if b not in nums:
        s["_budget_dropped"] = b
        s["budget"] = None
    return s


# 这些词是模型最爱凭常识补的，但库里根本没有对应字段
FABRICATE_WORDS = ["保修", "上门", "防泼溅", "军标", "认证", "色域", "sRGB", "Nits",
                   "接口", "雷电", "Thunderbolt", "Wi-Fi", "蓝牙", "背光", "指纹",
                   "摄像头", "散热管", "热管", "风扇", "续航小时", "充电器", "三年", "两年",
                   "一年", "包换", "退换", "延保"]

STRICT_TAIL = """
再次强调：你只能使用数据中出现过的词。上面这句话里凡是涉及保修年限、上门服务、
防泼溅、军标认证、屏幕色域、接口数量、摄像头、电池续航的描述，数据里都没有，
一个字都不许写。只讲配置、价格、优点、缺点、坑。"""


def _data_corpus(result):
    parts = []
    for r in result["ranked"]:
        parts += [r.get("spec") or "", r.get("tag") or "", r.get("caution") or ""]
        parts += r.get("pros") or []
        parts += r.get("cons") or []
        parts += [r.get("brandNote") or ""]
    return " ".join(parts)


def check_fabrication(text, corpus):
    """回答里出现数据没有的硬件/服务描述 → 返回命中的词。

    🔴🔴 2026-11-18 修：**必须区分「声称有」和「说明没有」**。

      实测误杀（预算8000打游戏，模型原话）：
        「数据里**没有**记录保修年限和具体售后政策，购买前建议直接咨询客服」
        「只有**充电器**功率信息」

      这两句都是**诚实声明**（承认库里没有数据），却命中了
      FABRICATE_WORDS 里的「保修」「充电器」→ 判成编造 →
      整段被删 → 用户看到干巴配置罗列。

      判据：命中词所在的**分句**里如果有否定/缺失语义
      （没有/无/未/不/缺/查不到/未记录…），那是声明缺失，不是编造。

      为什么按"分句"而不是整段：
      一段话里可能既说「没有保修数据」又说「有上门服务」，
      按整段判断会漏掉真正的编造。所以切开看。
    """
    hits = []
    for w in FABRICATE_WORDS:
        if w not in text:
            continue
        if w in corpus:
            continue
        # 找出这个词出现的每个分句，逐个判断语境
        fabricated = False
        for m in re.finditer(re.escape(w), text):
            # 取该词所在分句（前后各切到标点）
            start = max(text.rfind(c, 0, m.start()) for c in "。！？；\n") + 1
            ends = [text.find(c, m.end()) for c in "。！？；\n"]
            ends = [x for x in ends if x >= 0]
            end = min(ends) if ends else len(text)
            clause = text[start:end]
            # 否定/缺失语境 → 这句是在说"没有"，不是编造
            if re.search(r"没有|没记录|未记录|无记录|未收录|没数据|无数据|"
                         r"没有数据|查不到|找不到|不清楚|不知道|不确定|"
                         r"缺|待确认|需确认|咨询客服|问客服|看厂商", clause):
                continue
            fabricated = True
            break
        if fabricated:
            hits.append(w)
    return hits


def parse_constraints(text, slots):
    """从用户话里提取硬性排除条件，放进 slots 跨轮保留。
    实测教训：用户说「不要封装内存」，系统还在推 upgrade=0 的机型，
    因为 upgrade 只是软权重、不是过滤条件。这类明确要求必须变成硬约束。"""
    t = text
    if any(k in t for k in ["不要封装", "别封装", "不要板载", "别板载", "不要焊",
                            "不能焊", "不要焊死", "不想要封装", "不要这种内存"]):
        # 双重否定：「不是不要封装」= 要封装，不能当硬约束
        if not re.search(r"不是\s*不要封装|并非\s*不要封装|不是\s*不想要封装", t):
            slots["_minUpgrade"] = 1
    if any(k in t for k in ["要能加内存", "能升级内存", "要能升级", "内存插槽",
                            "要可加装", "以后加内存", "留插槽"]):
        slots["_minUpgrade"] = 1
    if any(k in t for k in ["封装也行", "板载也行", "不用升级", "不能升级也没关系"]):
        slots.pop("_minUpgrade", None)

    # 内存容量下限：「32G 内存」「要 32G」→ _minRam=32
    m = re.search(r"(\d{1,3})\s*[Gg]\s*(内存|运存)?", t)
    if m and any(w in t for w in ["内存", "运存", "G"]):
        v = int(m.group(1))
        if v in (16, 24, 32, 48, 64):
            slots["_minRam"] = v
    # 「不要荣耀」「除了荣耀其他都行」→ 品牌排除。
    # 必须先确认后面那两个字真的是库里的品牌，否则「不要封装」会被当成排除品牌"封装"。
    m = re.search(r"(不要|别买|除了|不想要)\s*([\u4e00-\u9fa5]{2,4}?)(?=其他|都行|的|，|,|；|。|$)", t)
    if m:
        cand = m.group(2)
        real = {o.get("brand") for o in core.usable_offers(core.load())}
        if cand in real:
            slots.setdefault("_excludeBrand", [])
            if cand not in slots["_excludeBrand"]:
                slots["_excludeBrand"].append(cand)
    return slots


def template_reply(m):
    """换一台用模板拼，不调模型。
    实测：多轮「换一台」时模型会把当前这台说成「你不想要的」，
    还会冒出库外品牌。这类回答数据是现成的，稳定比文采重要。
    缺点优先挑「封装/板载」这类决定性信息 —— 之前只挑第一条，
    结果漏掉了「内存板载」，用户看到前后矛盾。"""
    parts = ["%s，%s，到手 ¥%s。" % (m["name"], m.get("spec") or "", m.get("price"))]
    pros = [p for p in (m.get("pros") or []) if p]
    if pros:
        parts.append(pros[0].rstrip("。") + "。")
    cons = [c for c in (m.get("cons") or []) if c]
    key = next((c for c in cons if any(w in c for w in ["封装", "板载", "焊"])), None)
    if key is None and cons:
        key = cons[0]
    if key:
        parts.append("有件事得先说清楚：" + key.rstrip("。") + "。")
    elif m.get("caution"):
        parts.append("不过要注意：" + m["caution"].rstrip("。") + "。")
    # 🔴 2026-11-16：原来这里追加「这台的评价库里还没有」——
    #    用户要求不要解释数据来源、不要暴露"有没有人写过"。
    #    直接不追加。反正配置和价格已经说清楚了，用户要问会继续问。
    return "".join(parts)


def _money(x):
    try:
        v = float(x)
    except (TypeError, ValueError):
        return "—"
    return ("%d" % v) if v.is_integer() else ("%.2f" % v)


def _list_others_reply(rest, slots):
    """把第 2 名之后的候选逐台写出来。**全部由代码生成**，不经过模型。

    为什么不让模型写：它每次都会把首位那台再介绍一遍（实测三次），
    因为它看到的"数据"里首位最完整，而"列其余"这个动作没有任何字段约束它。
    清单这种确定性输出，交给模板比交给模型稳。

    只说数据里有的：机型 / 配置 / 到手价 / 有没有人写过优缺点。
    ⚠️ 没人评过的机器**不许加一句评价**（宪法第 7 条）。
    """
    if not rest:
        return ""
    lines = ["除了刚才那台，同样条件下库里还有 %d 台（按同一套规则排出来的第 2 名往后，"
             "不是我另外换了一台）：" % len(rest)]
    for i, m in enumerate(rest, 2):
        seg = "%d. %s —— %s，到手 ¥%s。" % (
            i, m["name"], m.get("spec") or "配置未记", _money(m.get("price")))
        # 2026-11-16：不再区分"有没有人写过优缺点"，也不解释数据来源。
        # 想细看就点它问 —— 追问路径会给出按规格能确认的客观提示。
        if m.get("noPerfData"):
            seg += "另外它查不到跑分，排序是按价格排进来的。"
        lines.append(seg)
    lines.append("想看哪台的具体参数或短板，直接点名就行。")
    return "\n".join(lines)


def _compare_text(rows):
    """把 2–3 台摆在一起。**只报字段，不做推荐、不给评分。**

    为什么不交给模型：对比要求每个数字都对上号，
    4B 模型很容易把 A 的价格配到 B 的名字上（串台），模板反而更稳。
    结论行只做**可核对的数据比较**（谁最便宜、谁的跑分最高），
    不说"更值得买"。
    """
    if len(rows) < 2:
        return "库里这个条件下只有一台，没有可对比的第二台。"
    L = ["放一起看（每个数都是库里的字段，不是我算的印象）："]
    for r in rows:
        bits = ["到手 ¥%s" % _money(r.get("price"))]
        bits.append("%sG 内存" % r["ram"] if r.get("ram") else "内存未记")
        bits.append("跑分 %s" % r["perf"] if r.get("perf") is not None else "跑分库里没有")
        bits.append("重量 %s" % (("%s kg" % core.effective_weight(r))
                                if core.effective_weight(r) else "库里没记"))
        u = r.get("upgrade")
        bits.append("内存焊死" if not u else "可加装 %s/3 档" % u)
        # 2026-11-16：不再输出「没人写过优缺点」这类数据来源说明。
        L.append("· **%s** —— %s" % (r["name"], "，".join(bits)))

    # 结论：只用上面已列出的字段做比较，不引入任何新判断
    cheap = min(rows, key=lambda x: x.get("price") or 9e18)
    L.append("")
    L.append("光看数字：最便宜的是 %s（¥%s）。" % (cheap["name"], _money(cheap.get("price"))))
    perf_rows = [r for r in rows if r.get("perf") is not None]
    if len(perf_rows) >= 2:
        top = max(perf_rows, key=lambda x: x["perf"])
        if all(r["perf"] == top["perf"] for r in perf_rows):
            L.append("这三台的跑分都是 %s，性能这一项没有差别。" % top["perf"])
        else:
            L.append("跑分最高的是 %s（%s）。" % (top["name"], top["perf"]))
    wt = [r for r in rows if core.effective_weight(r)]
    if len(wt) >= 2:
        light = min(wt, key=lambda x: core.effective_weight(x))
        L.append("有重量记录的两台里，%s 最轻（%s kg）。"
                 % (light["name"], core.effective_weight(light)))
    elif len(wt) == 1:
        L.append("只有 %s 记了重量（%s kg），其余库里没记 —— 不拿没记的当轻。"
                 % (wt[0]["name"], core.effective_weight(wt[0])))
    return "\n".join(L)


def _dgpu_switch_note(slots, result):
    """「要独显」且当前品类预算内没有 → 说明为什么切到游戏本（代码生成，不经模型）。

    2026-11-12 16:34 真实彩排抓到的错误：模型捏造"你要打游戏"，
    还断言「同品类里带独显的只有拯救者 R7000P ¥12999」——那句排他断言是
    检索范围只看了当前品类导致的假话：游戏本品类 8000 内有 3 台独显机。
    这里把预算内的替代一起给，不再让用户以为只能加钱到 12999。
    """
    if not result or not result.get("dgpuCatSwitch"):
        return ""
    sl = result.get("slots") or slots or {}
    budget = sl.get("budget")
    scope = ("¥%d 以内" % budget) if budget and budget < 99999 else "库里"
    ms = result.get("dgpuBudgetModels") or []
    alt = ""
    if ms:
        parts = []
        for m in ms:
            nm = (m.get("name") or "").split("（")[0]
            p = m.get("price")
            if p is None:
                continue
            pv = ("%d" % p) if float(p).is_integer() else ("%.2f" % p)
            parts.append("%s（¥%s）" % (nm, pv))
        if parts:
            alt = "你预算内的独显游戏本有这几台：%s。" % "、".join(parts)
    return ("先说要紧的：你要独立显卡，但%s的轻薄本里没有一台带独显 —— "
            "带独显的全在游戏本里。%s下面按游戏本给你排。\n\n" % (scope, alt))


def _gaming_conflict_note(slots, result):
    """用途和品类打架时，把冲突写在推荐**前面**（宪法第 5 条）。

    为什么不让模型写：实测 2026-11-12 —— 已在提示词里写了「硬伤必须先说」，
    模型仍然整段在讲屏幕和价格，一个字没提"打游戏不行"；
    用户要到下一轮追问「华为这个能打游戏吗」才被告知"不适合"。
    同一件事前后矛盾，正是这套系统最不能出的错。

    这句话完全由代码生成，只引用 slots 里的预算和 result 里那台机器的价格，
    不经过模型，也不需要再过 verify_answer（它本来就是可信源）。
    """
    if not result or not result.get("noGamingInCat"):
        return ""
    sl = result.get("slots") or slots or {}
    cat = sl.get("cat")
    budget = sl.get("budget")
    cat_name = core.CAT_NAMES.get(cat, cat or "这一档")
    scope = ("¥%d 以内" % budget) if budget and budget < 99999 else "库里"
    s = ("先说要紧的：你要打游戏，但%s的%s里没有一台带独立显卡 —— "
         "打游戏这项在%s里满足不了。下面这台是按设计和便携排的，"
         "打游戏这条它做不到。" % (scope, cat_name, cat_name))
    h = result.get("noGamingHint") or {}
    if h.get("price") and budget and h["price"] > budget:
        # 名字里常带括号说明（「拯救者 R7000P 2026（R7000 系列自营在售款）」），
        # 直接拼「（¥12999）」会出现两层括号，读起来像 bug。
        nm = (h.get("name") or "").split("（")[0]
        s += "同品类里带独显的只有 %s 那台，¥%s，已经超你的预算。" % (
            nm, ("%d" % h["price"]) if float(h["price"]).is_integer()
            else ("%.2f" % h["price"]))
    s += "要不要我按游戏本再排一版？\n\n"
    return s


def _kg(x):
    """2.0 → "2"，2.10 → "2.1"，2.46 → "2.46"。别把重量写成 2.00kg。"""
    try:
        v = float(x)
    except (TypeError, ValueError):
        return None
    s = ("%.2f" % v).rstrip("0").rstrip(".")
    return s or "0"


def _carry_note(slots, result):
    """「要带出门」不等于「换成轻薄本」—— 该做的是**同品类内部比重量**。

    用户原话（2026-11-12）：
      「其实基本上学生用笔记本，都要带出去的，所以说可以做提醒给推荐的品类
        做一个重量比较，而不是直接退化到轻薄本，因为退化的轻薄本，
        大概率不满足性能需求了」

    所以这里只做两件事：报出这台的实测重量 + 同品类的重量区间。
    **不推荐别的型号** —— 一旦点名"XX 更轻"，就变成偷偷换推荐对象（宪法第 6 条）。

    数据边界：只有采集池记了 weightKg（78/80）；人工层只有 1-3 档 portable 分，
    那不是公斤数，两套单位绝不能混着比。
    """
    sl = result.get("slots") or slots or {}
    if not sl.get("carry"):
        return ""
    ranked = result.get("ranked") or []
    if not ranked:
        return ""
    first = ranked[0]
    # 🔴 2026-11-13：必须用 effective_weight —— 结构化字段优先，文本兜底。
    #   原来只有 `first.get("weightKg")`，于是 cons 里明明写着「1.48kg 在 14 寸
    #   里偏重」，这里却判成"没记"，正文和字段卡对同一事实说了两种话。
    w = core.effective_weight(first)
    if not w:
        return ("\n\n带出门这件事：库里没记 %s 的实测重量，商品页「净重」那一行能查到。"
                % first["name"])
    cat = sl.get("cat")
    budget = sl.get("budget") or 99999
    # 只在**同预算**里比：拿 12999 的 1.46kg 机器去比 7000 的预算，
    # 数字是真的，但对用户没有用 —— 那是他买不到的参照物。
    peers = [o for o in core.merged_offers()
             if o.get("cat") == cat and core.effective_weight(o)
             and (o.get("price") or 0) <= budget * 1.05]
    scope = "同品类同预算"
    if len(peers) < 3:
        peers = [o for o in core.merged_offers()
                 if o.get("cat") == cat and core.effective_weight(o)]
        scope = "同品类"
    if len(peers) < 3:
        return "\n\n带出门这件事：这台 %s kg。" % _kg(w)
    lo = min(peers, key=lambda o: core.effective_weight(o))
    hi = max(peers, key=lambda o: core.effective_weight(o))
    s = "\n\n带出门这件事：这台 %s kg；%s里记了实测重量的 %d 台，最轻 %s kg、最重 %s kg。" % (
        _kg(w), scope, len(peers),
        _kg(core.effective_weight(lo)), _kg(core.effective_weight(hi)))
    if abs(float(w) - float(core.effective_weight(lo))) < 1e-9:
        s += "这台就是里面最轻的。"
    return s


def _major_group(slots):
    gid = (slots or {}).get("_majorId")
    if not gid:
        return None
    return next((x for x in (core.majors_data().get("groups") or [])
                 if x.get("id") == gid), None)


def _major_brief(slots):
    """把 majors.json 里这组的配置要求压成一句人话（原表照搬，不加工）。"""
    g = _major_group(slots)
    if not g:
        return ""
    req = g.get("req") or {}
    parts = []
    if req.get("ramMin"):
        parts.append("内存 %s 起、%s 推荐" % (req.get("ramMin"), req.get("ramRec")))
    gpu = req.get("gpu")
    if gpu == "discrete":
        parts.append("要独立显卡（%sG 显存起）" % req.get("vramMin"))
    elif gpu:
        parts.append("显卡不设门槛（只有跑本地模型才看显存）")
    for gate in g.get("hardGates") or []:
        if gate.get("dim") == "upgrade":
            parts.append("内存要能加装 —— %s" % gate.get("why"))
    if not parts:
        return ""
    return "%s（%s组）：%s" % (slots.get("_majorName") or "",
                              g.get("name") or "", "；".join(parts))


def _major_note(slots, result):
    """把专业要求写在推荐后面，并说清这台差在哪。

    🔴 用户原话（2026-11-12）：「我是人工智能专业的大一新生，预算 7000，
       给我推荐一台笔记本」→ 系统推了 MateBook 14（16G / 核显 / 不可加装）。
       而 majors.json 里这一组写得很清楚：16G 只是底线、32G 才是推荐，
       而且**内存焊死等于四年没后路**是这组唯一的 hardGate。
       系统从来没读过这份表，所以推得"有理由"但没依据 —— 用户只能反复追问。
    """
    brief = _major_brief(slots)
    ranked = (result or {}).get("ranked") or []
    if not brief or not ranked:
        return ""
    g = _major_group(slots)
    req = (g or {}).get("req") or {}
    first = ranked[0]
    s = "\n\n按你的专业要求（库里那份专业配置表）：%s。" % brief
    ram, rec = first.get("ram"), req.get("ramRec")
    if ram and rec:
        s += ("这台 %dG，过了底线但没到 %dG 推荐档。" % (ram, rec)) if ram < rec \
            else ("这台 %dG，够推荐档。" % ram)
    if int(first.get("upgrade") or 0) >= 2:
        s += "内存可加装，以后能补。"
    return s


def answer_card(result, slots=None, note="", carry="", mnote=""):
    """把内核结果整理成**固定字段**的回答，供前端直接渲染。

    为什么要有它（2026-11-13 用户原话：「更希望每次回答的数据是规范格式输出，
    而不是一句一句话」）：
      正文是模型写的，同一台机器换个问法句子结构就变，用户没法逐栏对照。
      这里把该说的东西钉成固定几栏，**每一栏都只从 result / 上面那几个
      代码生成函数里取，不做任何运算**。

    ⚠️ 正文仍然保留（前端折叠成「详细说明」）—— 它是过了出口审计的那一份。
       字段卡只是把同样的事实重新排一遍，**不许出现正文里没有的新事实**。
       所以 note / carry / mnote 三个参数是**复用**上面已经生成好的字符串，
       不在这里重写一遍（宪法第 9 条：判据/文案不许抄第二遍）。
    """
    ranked = result.get("ranked") or []
    if not ranked:
        return None
    top = ranked[0]

    hard = [b for b in (top.get("blockers") or []) if b.get("level") == "hard"]
    soft = [b for b in (top.get("blockers") or []) if b.get("level") != "hard"]

    # ---- 一句话结论：只陈述内核给的事实，不加评价词 ----
    # ⚠️ 原来写的是「首选 X」—— 被 test_answer 逮住：「首选」本身就在
    #   宪法第 7 条的禁用词表里（无人评价的机器不许说"首选/值得买"）。
    #   改成陈述排序结果："按你给的条件，排第 1 的是 X"，这是内核给的事实。
    head = "按你给的条件，排第 1 的是 %s，到手 ¥%s" % (top["name"], _money(top.get("price")))
    if top.get("overBudget"):
        head += "（超预算）"
    if hard:
        # 宪法第 5 条：硬伤必须说在前面。这里就是把"前面"钉死。
        head += "。先说要紧的：%s" % hard[0].get("why", "")
    # 🔴 2026-11-16：删掉了原来的 `elif not hasReview: head += "这台的评价库里还没有…"`
    #    用户要求不要暴露"有没有人写过"，也不要解释数据来源。

    # ---- 固定字段行（顺序固定，前端不重排） ----
    sub = top.get("subsidy") or {}
    price_cell = "¥%s" % _money(top.get("price"))
    rows = [{"k": "机型", "v": top["name"]}]
    rows.append({"k": "到手价", "v": price_cell})
    if sub.get("original") or sub.get("subsidy"):
        parts = []
        if sub.get("original"):
            parts.append("页面价 ¥%s" % _money(sub["original"]))
        if sub.get("subsidy"):
            parts.append("含国补 ¥%s" % _money(sub["subsidy"]))
        rows.append({"k": "价格拆解", "v": " · ".join(parts)})
    rows.append({"k": "配置", "v": top.get("spec") or "—"})
    # 🔴 2026-11-16：原来这一行是「评价：库里有人写过优缺点 / 只报参数」——
    #    用户明确要求不要暴露"人工/没人评过"这种内部区分。
    #    换成**价格口径**：同一个数字是到手价还是平台快照价，含义完全不同，
    #    那才是用户需要知道的。
    rows.append({"k": "价格口径",
                 "v": "平台快照价（不含券与国补，不等于到手价）"
                      if top.get("priceIsEstimate") else "到手价"})
    if top.get("perf") is not None:
        rows.append({"k": "性能分", "v": "%s / 100（Cinebench R23 标尺）" % top["perf"]})
    else:
        rows.append({"k": "性能分", "v": "库里没有这台的实测分，不估"})
    if top.get("ram") is not None:
        up_txt = "可加装" if (top.get("upgrade") or 0) > 0 else "焊死，不可加装"
        rows.append({"k": "内存", "v": "%dG（%s）" % (top["ram"], up_txt)})
    if core.effective_weight(top) is not None:
        rows.append({"k": "重量", "v": "%s kg（实测）" % core.effective_weight(top)})
    else:
        rows.append({"k": "重量", "v": "库里没记实测重量"})

    gaps = []
    for b in hard:
        gaps.append({"level": "hard", "text": b.get("why", "")})
    for b in soft:
        gaps.append({"level": "soft", "text": b.get("why", "")})
    if not gaps:
        gaps.append({"level": "none",
                     "text": "这个用途下，库里没有记到它的硬伤；也只是没记到，不等于没有"})

    blocks = []
    for title, text in (("范围提醒", note), ("带出门", carry), ("专业要求", mnote)):
        if text:
            blocks.append({"k": title, "v": text.strip()})

    cands = []
    for x in ranked[1:3]:
        cands.append({
            "name": x["name"],
            "price": x.get("price"),
            "hasReview": bool(x.get("hasReview")),
            "note": "只报参数" if not x.get("hasReview") else "",
        })

    return {
        "headline": head,
        "rows": rows,
        "gaps": gaps,
        "blocks": blocks,
        "candidates": cands,
        "warnings": list(result.get("warnings") or []),
        "dataAsOf": result.get("dataAsOf"),
        # 2026-11-16：原来是「这一轮排序池 N 台，其中 M 台没人写过评价」——
        # 用户要求不要暴露"有没有人写过"这个内部区分，改成只报池子规模。
        "poolHint": ("这一轮的排序池是 %d 台" % (result.get("pool", {}).get("total") or 0))
                    if result.get("pool") else "",
    }


def compose(user_text, result):
    """把内核结果说成人话。模型只负责措辞，数字和事实都是内核给的。"""
    top = result["ranked"]
    first = top[0]
    # 🔴 最后一道兜底：榜首这台本身就不在覆盖范围内 → 弃权，不要措辞。
    #   2026-11-13 实测：池子里混着 4 台苹果机时，「预算 6000 轻薄本」首推
    #   MacBook Air 13 M4；出口审计确实报了「库外机型 MacBook」，
    #   但重写两次仍命中 → 落到 template_reply，而模板里的机名**就是 MacBook**，
    #   于是"检出了、还是发出去了"。
    #   池子那头已经把苹果机挡住了（core.is_out_of_scope_offer），这条留着防的是
    #   "以后从别的口子（新采集源、补丁合并）又进来一台"同一类错。
    if core.is_out_of_scope_offer(first):
        return ("这台不在我的覆盖范围里 —— 我只做 Windows 笔记本、台式整机和内存固态，"
                "苹果整机不在库里，硬答就是编。\n"
                "你可以说说预算和用途，我从 Windows 这边给你挑。"), []
    # 超预算这种警告不许漏：用户最容易被"预算 3000 你给我推 6799"激怒。
    # 模型经常把警告吞掉，或者重写时丢掉，所以最后用硬拼接补上。
    budget_warn = [w for w in result["warnings"] if "超预算" in w or "一台都买不到" in w]
    # 只给榜首的完整数据。备选只给名字，不给价格 ——
    # 实测发现：只要给两台的价格，模型必然自己算差价（1438/460 两条就是），
    # 这违反"模型无数字写权限"。断根方式是让它没有可算的数，而不是靠提示词劝阻。
    # 🔴 价格口径按数据来源分两种说法（2026-11-16 接 ZOL 数据后加）：
    #    jd  → 到手价，含国补，不许再加再减
    #    zol → 平台标价快照，**不含国补/券**，既不能说成到手价，也不能说它含国补
    #    原来这里只写了前者，于是 ZOL 那 119 台被说成「到手价 4898 元」——
    #    数字是真的，口径是错的，用户不会怀疑（这是最难抓的一类）。
    _est = bool(first.get("priceIsEstimate"))
    slim = {
        "侧重": result["mode"],
        "数据日期": result["dataAsOf"],
        "警告": result["warnings"],
        "说明_警告由系统统一写": "上面「警告」里的内容，系统会在末尾自动补一句，"
                                "你不要在正文里复述，也不要评价预算够不够",
        "说明": ("这个价是平台标价快照，不含国补和平台券 —— "
                 "不要说成「到手价」，不要说它包含国补，也不要去加减补贴"
                 if _est else
                 "到手价已经包含国补，不要再把补贴加到价格上，也不要再从价格里减"),
        "已排除_用户看过并拒绝": result.get("excluded", []),
        "当前这台_你要介绍的就是它": {"机型": first["name"],
                  _price_label(first): first["price"],
                  "原价": (first["subsidy"] or {}).get("original"),
                  "其中含国补": None if _est else (first["subsidy"] or {}).get("subsidy"),
                  "配置": first["spec"],
                  "一句话标签": first["tag"],
                  # 专业配置要求（majors.json 原文）。模型说得对不对，全靠这一栏。
                  "你的专业要求": _major_brief(result.get("slots") or {})
                                  or "（没识别出专业）",
                  # 过滤掉"讲的是别的型号"的那部分，见 _clean_caution。
                  # 实测 2026-11-11：小新 16 的 caution 原文在安利 16SE，
                  # 模型照抄之后，首位推荐的段落里主推了另一台。
                  "要提醒的坑": _clean_caution(first["caution"], first),
                  "优点": first.get("pros", []),
                  "缺点": first.get("cons", []),
                  "售后网点_满分5": first.get("brandService"),
                  "保值_满分5": first.get("brandResale"),
                  "品牌备注": first.get("brandNote"),
                  # 这个用途下的硬伤：数据明写的短板。
                  # 有了它必须**先说**，不能只夸优点 —— 实测 2026-11-11：
                  # 用户「学设计的」，推的第一台自己 cons 里写着「色域是明显短板」，
                  # 模型却整段在夸扩展性和军标认证，一个字没提屏幕。
                  # 分两档：hard 是"数据明说这块不行"，必须先说；
                  # soft 是"这块不算突出"（能用的意思），也要说，但不能说成"不能买"。
                  # 实测 2026-11-11：小新 16 的 cons 写「屏幕素质在同价位不算突出」，
                  # 这是弱证据 —— 当成硬伤降权等于替用户判了"不能做设计"。
                  "这个用途下的硬伤_必须先说": [
                      b["why"] + "（原文：" + b["evidence"] + "）"
                      for b in (first.get("blockers") or [])
                      if b.get("level") == "hard"],
                  "这个用途下不算强的地方_要提一句_但不能说成不能用": [
                      b["why"] + "（原文：" + b["evidence"] + "）"
                      for b in (first.get("blockers") or [])
                      if b.get("level") != "hard"],
                  # 🔴🔴 这台到底有没有人写过评价（2026-11-12 接入 80 台采集机后新增）
                  # 采集池那 78 台的 pros/cons 是**空的** —— 爬虫爬不到评价。
                  # 不告诉模型这件事，它就会拿参数当卖点讲：
                  #   实测「预算 8000 打游戏」→「屏幕刷新率高达 240Hz」
                  # 240Hz 是真的，但"高达"是评语，而库里没人评过这台。
                  # 用户看到的是一个像模像样的推荐，实际上系统对这台一无所知。
                  "有没有人写过优缺点": "有" if first.get("hasReview") else "没有",
                  "如果没人写过_你必须这么说":
                      ("可以报配置、报价格、说清它属于什么档次，"
                       "但不许把参数换个说法当优点（「240Hz 高达」「32G 很够用」都算），"
                       "也不许说「值得买」「性价比高」。"
                       "不要解释数据来源，也不要说「没人评过」。")
                      if not first.get("hasReview") else
                      ("按「优点」「缺点」两栏说，"
                       "但同样不许超出这两栏自己加内容。")},
        "其他候选_只可顺带提一句_不要主推": [r["name"] for r in top[1:2]],
    }
    msgs = [{"role": "system", "content": ANSWER_SYS},
            {"role": "user", "content":
             "数据：" + json.dumps(slim, ensure_ascii=False) + "\n\n用户问：" + user_text}]
    txt = chat(msgs, num_predict=260).strip()

    corpus = _data_corpus(result)
    full_corpus = _corpus_all(result)

    def _audit(t):
        """回答的完整体检。**首轮和重写后必须共用同一个函数。**

        🔴 这里踩过一次（2026-11-11 演示前）：
        首轮校验加了「偷换推荐对象」和「出口品类越界」两条，
        但重写后的那段是**另抄一遍**的旧判据，没跟着加。
        结果：模型重写后又写出同样的问题，第二道门是旧的，直接放行 ——
        实测输出「要提醒的坑是：小新 16SE 有双 M.2 硬盘位，同价位更值得看」。
        判据抄两遍，就一定会漂。抽成一个函数，只有一处。
        """
        return dict(
            bad=check_fabrication(t, corpus),
            untr=verify_answer(t, result, user_text),
            over=_overspec(t),
            lie=_budget_lie(t, result),
            cross=_cross_cat(t, result),
            rel=_relative_claim(t, full_corpus),
            # 把「另一台更值得买」说成了这台的坑 —— 等于偷偷换了推荐对象
            pitch=_other_model_pitch(t, result),
            brand=_brand_mismatch(t, first),
            # 出口范围校验：回答里冒出手机/平板/工作站这类库外品类
            outscope=_out_scope_product(t) or check_scope(t),
            # 把字段名当内容念出来（"品牌售后网点分是 5 分制"）
            echo=_field_echo(t),
            # 🔴 这台没人写过评价，却在替它说好话（把参数当卖点）
            # 2026-11-12：接入 80 台采集池后新出现的错误类型。
            # bad/untr 抓不到它 —— 因为它引用的每个数字都是真的。
            praise=_praise_no_review(t, first),
            vague=_vague_praise(t),
            # 🔴 2026-11-17：不许推测整机功耗 / 对"限电够不够"下结论。
            #    首轮推荐同样会犯（"这台限电 500W 跑不满"），
            #    原来只有 _answer_current 挂了这条判据。
            power=_power_guess(t),
        )

    def _hit(a):
        return any(a.values())

    a1 = _audit(txt)
    bad = a1["bad"]
    if _hit(a1):
        # 命中编造词 / 数据外数字 / 超证据断言 / 超预算自相矛盾 / 跨品类越界 → 带违规清单重写一次
        why = []
        if a1["bad"]:
            why.append("写了数据里没有的内容（" + "、".join(a1["bad"]) + "）")
        if a1["untr"]:
            why.append("出现了数据里没有的数字（"
                       + "、".join(str(x) for x in a1["untr"]) + "）")
        if a1["over"]:
            why.append("预测了游戏表现（" + "、".join(a1["over"]) + "），"
                       "库里没有帧数数据，一个字都不许猜")
        if a1["lie"]:
            why.append("这台其实超预算了，不许说「" + "、".join(a1["lie"]) + "」这种话")
        if a1["cross"]:
            why.append("拿台式机做比较（" + "、".join(a1["cross"]) + "），"
                       "这轮数据里没有台式机，不要提别的品类")
        if a1["rel"]:
            why.append("自己算了相对量（" + "、".join(a1["rel"]) + "），"
                       "数据里没有这个百分比或倍数，不许算")
        if a1["pitch"]:
            why.append("把「另一台更值得买」说成了这台的坑 —— "
                       "「要提醒的坑」里提到别的型号时，不要把它当成这台的缺点，"
                       "更不要顺势主推。改用「缺点」里属于这台自己的那一条")
        if a1.get("brand"):
            why.append(
                "你把当前这台说成了**%s**，但它的品牌是**%s** —— "
                "品牌归属说错了会直接误导售后/保值判断。"
                "用户上一句提到的品牌不等于这台的品牌，"
                "不许把它安到这台上。"
                % (a1["brand"]["said"], a1["brand"]["actual"]))
        if a1["outscope"]:
            why.append("提到了库里没有的品类（" + a1["outscope"] + "）—— "
                       "这轮只谈电脑本身，手机、平板、工作站都不要提")
        if a1["praise"]:
            why.append("这台**没人写过优缺点**，你却说了「" + a1["praise"] + "」这种评价话 —— "
                       "只报配置和价格，"
                       "不许说「高达」「首选」「得满分」「值得买」这类判断，"
                       "也不要解释数据来源")
        if a1.get("vague"):
            why.append(
                "「%s」是**凭定位猜的结论**，不是数据 —— "
                "库里没有任何散热/性能实测。这类泛泛评价（中规中矩/符合预期/"
                "核心优势/能维持）读起来像实测，用户会当真。"
                "只能说数据里有的（散热系统描述、TDP/TGP、厚度），"
                "然后明说实测表现判断不了。"
                % a1["vague"])

        if a1.get("power"):
            why.append("你推测了**整机功耗**或对「限电够不够」下了结论 —— "
                       "库里没有整机功耗和实测瓦数，"
                       "只说适配器标称多少瓦（如果有），"
                       "然后明说「整机功耗库里没有，判断不了」并指路")
        # 🔴 2026-11-18：把当前这台说成别的品牌
        if a1.get("brand"):
            why.append("你把当前这台说成了**%s**，但它的品牌是**%s** —— "
                       "品牌归属不许说错，用户提过的品牌不等于这台的品牌"
                       % (a1["brand"]["said"], a1["brand"]["actual"]))
        msgs2 = [{"role": "system", "content": ANSWER_SYS + STRICT_TAIL},
                 {"role": "user", "content":
                  "数据：" + json.dumps(slim, ensure_ascii=False)
                  + "\n\n刚才那句" + "，".join(why) + "。重写，不要出现这些。"
                  + "\n\n用户问：" + user_text}]
        txt = chat(msgs2, num_predict=260).strip()
        # 🔴 重写后必须用**同一个** _audit 再查一遍。
        # 原来这里另抄了一份旧判据，新加的两条没跟上，
        # 导致「小新 16SE 更值得看」重写后照样放行（2026-11-11 实测）。
        a2 = _audit(txt)
        if _hit(a2):
            # 🔴🔴 2026-11-18：**重写仍违规时，不要整段丢掉换模板**。
            #
            #    实测（预算8000打游戏）：模型第一版写的是
            #      「它属于高配游戏本，适配 240Hz 高刷新率屏幕，
            #        适合对画面流畅度有要求的玩家。
            #        适配器标称 280W，但整机实际功耗数据未记录…」
            #    前面那句是**好的**，只有「280W」是编的（这台 adapterW=None）。
            #    但旧逻辑一命中就 `txt = template_reply(first)` ——
            #    整段扔进垃圾桶，用户最后看到 117 字的干巴配置罗列。
            #    这就是用户说的「太 low」「很死板」的直接原因：
            #    不是模型不会说，是**它说的话被整段删了**。
            #
            #    改法：先试**外科手术** —— 只删掉违规的那句/那个数字，
            #    保留其余内容。手术失败（删完太短/删不干净）才退回模板。
            _surgery = _strip_violations(txt, _audit)
            if _surgery and len(_surgery) >= 60:
                txt = _surgery
                bad = a2["bad"] or bad
            else:
                # 手术无效 → 用模板兜底，宁可干巴也不许误导
                txt = template_reply(first)
                bad = a2["bad"] or bad

    # 超预算警告硬保证：不依赖模型愿不愿意提
    for w in budget_warn:
        if w in txt:
            continue
        # 🔴 2026-11-13 修一处重复：模型经常把这条警告**换个说法**先说一遍
        #   （"最便宜的是 10299 元" vs 警告里的 "¥10299"），精确匹配拦不住，
        #   于是同一句事实在结尾又出现一次，数字重复两遍，读起来像系统没记性。
        #   判据退一步：只要正文里已经说了"一台都买不到"，就不再补这整句。
        if "一台都买不到" in w and "一台都买不到" in txt:
            continue
        # 顺带给这条警告加一句人话：它原来读起来像判决书。
        # ⚠️ 这句话里没有任何数字和机型 —— 它只是态度，不承担结论。
        if "一台都买不到" in w:
            txt = (txt.rstrip("。")
                   + "。这个价确实够不着 —— 不是你挑得不对，是市场就这样。")
        txt = txt.rstrip("。") + "。" + w + "。"
    return txt, bad


def numbers_in(text):
    return set(int(x) for x in re.findall(r"\d{3,6}", text))


def allowed_numbers(result):
    """回答里允许出现的全部数字：来自内核，可追溯。"""
    ok = set()
    for r in result["ranked"]:
        for k in ("price", "perf", "upgrade", "portable"):
            v = r.get(k)
            # 🔴 必须收 float（2026-11-12 修）：
            # 接入采集池后价格带小数（¥6687.41 是国补后的实付价，不是拍脑袋的整数）。
            # 原来只写 isinstance(v, int)，浮点价被整个漏掉 ——
            # 模型如实报「到手 6687.41」，verify_answer 却判成"数据外数字"打回重写，
            # 重写又命中，最后落入兜底模板，一条本来正确的回答被自己人毙了。
            if isinstance(v, (int, float)):
                ok.add(int(round(v)))
                # 🔴 2026-11-12 乱测夹具抓到：价格 ¥4240.65 被误判成"数字不可追溯"。
                #   numbers_in() 只抽整数（"4240.65" → 4240），这里却按 round 记成 4241，
                #   小数价格必然对不上 → 一条如实报数的回答被自己人毙掉，白重写一次。
                #   两个都放行：截断值和四舍五入值都是这台机器真实价格的表示。
                ok.add(int(v))
        sub = r.get("subsidy") or {}
        for k in ("original", "subsidy", "paid"):
            if isinstance(sub.get(k), (int, float)):
                ok.add(int(round(sub[k])))
        # 规格里的型号数字（RTX 5060、2.5K 165Hz）属于真实数据，一并放行
        ok |= numbers_in(r.get("spec") or "")
        ok |= numbers_in(r.get("name") or "")
        # caution/tag 是库里人工写好的风险提示，本身就可能含数字
        # （例：暗影精灵 caution="比隐星贵 460，买的是品牌而不是性能"）
        ok |= numbers_in(r.get("caution") or "")
        ok |= numbers_in(r.get("tag") or "")
    for w in result["warnings"]:
        ok |= numbers_in(w)
    ok |= numbers_in(result["dataAsOf"])
    return ok


# 相对量断言：库里没有任何对比测量数据，凡是"多 X%""强 Y 倍""快一倍"全是模型编的。
# 实测 2026-11-11「8000 的台式机」：写出"比移动版多约 15% 的 CUDA 核心"，
# 而 numbers_in 只抓 3~6 位数字，15 是两位数，就这么漏过去了。
RELATIVE_CLAIM = re.compile(
    r"(多|高|快|强|低|少|省)\s*(出|了)?\s*(约|大约|将近|接近|差不多)?\s*"
    r"[\d一二三四五六七八九十]+\s*(%|％|倍)"
    r"|[\d一二三四五六七八九十]+\s*(%|％|倍)\s*(多|左右|以上)?"
    # 「双倍内存」「翻一番」「翻倍」这类口头倍数，不带"倍"字也算
    r"|(双倍|两倍|三倍|四倍|一倍|翻倍|翻一番|翻一翻)"
    r"|\d+\s*G\s*(内存|固态)?\s*翻"
    r"|(比|多)\s*(出|了)?\s*[\d一二三四五六七八九十]+\s*(G|T)(B)?")

# 语料里真实存在的倍数说法不误杀，但必须由语料判定，不能无条件豁免。
# 这里留空是有意的：_relative_claim 已经做了"整句在语料里才放行"的判断，
# 再加一层白名单就等于开后门 —— 实测 2026-11-11「内存翻倍」就是这么漏过去的。


def _corpus_all(result):
    """校验用的完整语料：本轮候选 + 数据源里的政策/趋势/跨品类说明。

    为什么要扩到顶层：实测 2026-11-11 答案里写"CUDA 核心比移动版多约 15%"，
    这句其实是 data.prices.json 的 crossSell 原文，不是模型编的。
    只拿本轮候选当语料会把真话判成编造，判据就成了误杀工具。
    """
    parts = [_data_corpus(result)]
    try:
        d = core.load()
        for k in ("subsidyRules", "subsidyFacts", "crossSell", "upgradeGuide",
                  "outlook", "budgetBands", "categoryChange", "sameModel",
                  "partsChange", "costShare", "trapsByKind", "defects"):
            if k in d:
                parts.append(json.dumps(d[k], ensure_ascii=False))
    except Exception:
        pass
    return " ".join(parts)


def _relative_claim(text, corpus):
    """相对量比较（多 15%、快一倍）。只有追不到数据出处的才算编造。

    实测两次教训：
    ① 第一版"一律拦"，把「国补按 15% 立减」「CUDA 核心比移动版多约 15%」
       这些数据原文也拦了 —— 判据没有分辨力。
    ② 改成"数字能在语料里找到就放行"，又漏光了：「强 3 倍」的 "3" 在语料里
       到处都是（"3 台""3.2K"），一撞就通过。
    正解：看「带数字的完整说法」在不在语料里，而不是只看数字。
    """
    out = []
    for m in RELATIVE_CLAIM.finditer(text):
        s = m.group(0).strip()
        # 去掉空格后整句比对，例如 "多约15%" 命中语料里的 "多约 15%"
        key = re.sub(r"\s+", "", s)
        flat = re.sub(r"\s+", "", corpus)
        if key and key in flat:
            continue
        out.append(s)
    return out


def verify_answer(text, result, user_text=""):
    """硬断言：回答里的数字必须能追到内核或用户原话。返回无法追溯的数字。"""
    allowed = allowed_numbers(result) | numbers_in(user_text)
    return sorted(numbers_in(text) - allowed)


OUTSIDE_BLACKLIST = ["XPS", "ThinkPad", "MacBook", "Mac ", "拯救者", "雷蛇",
                     "外星人", "Alienware", "Surface", "ROG", "幻16", "幻 16"]


def check_outside_products(text, data=None):
    """检查是否引入了库外产品线。否定语境（声明"库里没有"）不算违规。"""
    d = data or core.load()
    known_text = " ".join([o.get("name", "") for o in d["offers"]])
    NEG = ["没提", "不包含", "没有", "不在", "未收录", "别", "不要", "无法", "不涉及"]
    hits = []
    for w in OUTSIDE_BLACKLIST:
        if w not in text or w in known_text:
            continue
        # 只看出现该词的分句，若同句带否定词，说明是在声明范围外，不算违规
        bad = False
        for sent in re.split(r"[。！？；\n]", text):
            if w in sent and not any(n in sent for n in NEG):
                bad = True
                break
        if bad:
            hits.append(w.strip())
    return hits


OUT_OF_SCOPE = ["macbook", "mac ", "苹果电脑", "苹果笔记本", "苹果本", "ipad", "平板",
                "手机", "iphone", "安卓机", "ps5", "switch", "游戏机", "一体机"]
# ⚠️ 这份词表查的是**用户说了什么**（入口），`core.is_out_of_scope_offer` 查的是
#   **数据里那台机器是什么**（取数口子）。两者不是同一条判据抄两遍：
#   一个管"这话该不该接"，一个管"这台能不能进池子"。
#   但加词要成对看：2026-11-13 实测「苹果笔记本和这个比呢」漏在入口没拦住，
#   就是因为这里只有"苹果电脑"没有"苹果笔记本"。


def check_scope(text):
    """范围检查放在抽槽位之前。这类问题不该进澄清流程。"""
    t = text.lower()
    for w in OUT_OF_SCOPE:
        if w in t:
            return w.strip()
    return None


# 回答里**不该出现**的产品品类。库里只有 Windows 笔记本、台式整机、内存固态。
#
# 为什么要在出口查这个（2026-11-11 演示前实跑发现）：
#   「别指望它能完全替代专业设计工作站」—— 用户问的是轻薄本，
#   回答里把"专业设计工作站"当成对照物，这是库里根本没有的品类。
#   「小米笔记本的售后体系不如手机」—— 更直接，回答里冒出"手机"。
#   这些句子都不含数字，verify_answer 管不到；也不是新机型名，
#   check_outside_products 那个按数据比对的判据也管不到 —— 它只筛"库外机型名"。
OUT_SCOPE_PRODUCT = re.compile(
    r"手机|平板|iPad|iPhone|安卓机|"
    r"工作站|服务器|"
    r"MacBook|Mac\s*Book|苹果电脑|iMac|Mac\s*mini|"
    r"PS5|Switch|游戏机|主机党|"
    r"显卡坞|外接显卡")

# 这些是"顺带提一句"的正当用法，不算越界。
#   「比手机还便宜」—— 在说价格便宜，不是在介绍手机
#   「不是手机那种」—— 在划清界限
#   「比平板还轻」  —— 在说重量
# 注意「不如」**不在**豁免里：实测 2026-11-11，
#   「小米笔记本的售后体系不如手机」被豁免掉了 —— 但那是在拿手机做实质对照，
#   用户问的是笔记本售后，回答里出现了库里没有的品类当参照物，就是越界。
#   豁免只该给"用别的东西打比方说价格/重量/体积"，不该给"拿别的东西比性能/售后"。
OUT_SCOPE_EXCUSE = re.compile(
    r"(?:比|不像|不是|没有)\s*(?:手机|平板|工作站|MacBook|iPad|iMac)"
    r"[^，。；]{0,6}(?:还)?(?:便宜|贵|轻|重|薄|厚|小|大|省电)"
    r"|(?:手机|平板|工作站)\s*(?:那么|那种)")


def _out_scope_product(text):
    """回答里出现了库外品类 → 返回命中的词，供上层打回重写。"""
    for m in OUT_SCOPE_PRODUCT.finditer(text or ""):
        ctx = text[max(0, m.start() - 10):m.end() + 10]
        if OUT_SCOPE_EXCUSE.search(ctx):
            continue
        return m.group(0)
    return None


# ══════════════════════════════════════════════════════════════════════
# 社交层（2026-11-13）
#
# 用户原话：「他没有情感上的交互，现在主流功能做的倒是还不错」。
# 翻日志验证过，不是主观感受 —— 真实那一轮是这样的：
#   10:25  U「好的我已经了解了，谢谢」
#          A「条件没改，还是刚才那台 天选6 Pro 锐龙版（到手 ¥10299）。要我做点别的吗？」
#   用户已经在**收尾**了，系统却把同一台又推了一遍，还问"要做别的吗"。
#   更早那句「随便看看」被回成「我不敢瞎猜 —— 你是想：① 换一台 ② 列候选 ③ 问参数」，
#   等于把一句闲话变成了三选一的工单。
#
# 这一层只做一件事：**接住人话**。三条纪律，违反就不许上线：
#   ① 不许评价机器 —— 情感只能对着"用户的处境"，不能对着"机器好坏"
#      （"这台很适合你"是编造，宪法第 7 条）
#   ② 不许谄媚 —— 不夸"您很有眼光""这问题问得好"
#   ③ 不许空安慰 —— 每句共情后面必须跟一个**能落地的动作**，
#      否则就是"说了等于没说"（宪法第 3 条宁可弃权，也不许说空话）
#
# 边界：只接**纯社交**。句子里带预算/品类/型号/换台这类信号的，一律交给主流程，
#       因为"谢谢，那 6000 的呢"里真正要办的是后半句。
# ══════════════════════════════════════════════════════════════════════
SOCIAL_PATTERNS = [
    # (标签, 正则) —— 顺序即优先级：情绪 > 犹豫 > 道谢 > 告别 > 招呼 > 夸奖 > 附和
    ("frustration", re.compile(
        r"太贵|好贵|贵了|买不起|超预算|算了|不看了|不想看|看不懂|没看懂|太复杂|"
        r"烦死|崩溃|救命|吐血|劝退|麻了")),
    # 「随便看看」不是纠结，是**还没想法**。两者回应完全不同：
    #   纠结 → 收敛（逼一个硬标准）；没想法 → 先给两个方向看看
    ("browse", re.compile(r"随便看看|就看看|看看而已|没想法|没概念|不懂电脑|随便买|随便挑")),
    ("indecision", re.compile(
        r"纠结|不知道选|选不出|拿不定|犹豫|你帮我选|你说选哪|都行|看花眼")),
    ("thanks", re.compile(r"谢谢|多谢|感谢|thanks|thank\s*you|thx", re.I)),
    ("bye", re.compile(r"先这样|就这样|再见|拜拜|bye|我走了|先撤|收工|回头再聊", re.I)),
    # 招呼可能连着说好几个：「您好，在吗」「你好呀，有人吗」
    ("greet", re.compile(
        # ⚠️ 字符集里必须有**全角逗号「，」** —— 第一版只写了半角逗号，
        #    「您好，在吗」就被判成不认识了（实测）。
        r"^\s*((你好|您好|hi|hello|在吗|在不在|有人吗|哈喽|嗨|呀)\s*"
        r"[!！。.，,~～、；;\s]*){1,4}$", re.I)),
    ("praise", re.compile(r"你(真|太|挺)?(厉害|牛|聪明|专业|好用|不错)|这(东西|个)?(真)?(挺好|不错|可以)")),
    ("smalltalk", re.compile(r"^(哈+|嗯+|哦+|好的|好|行|ok|okay|收到)\s*[!！。,.~～\s]*$", re.I)),
]

# 句子里有这些 = 有活儿要干，不许被社交层吃掉
TASK_SIGNAL = re.compile(
    r"\d|预算|块钱|元|价位|轻薄|游戏本|台式|一体机|内存|硬盘|显卡|独显|屏幕|重量|"
    r"cpu|i5|i7|i9|ryzen|锐龙|ultra|酷睿|换一台|换台|对比|比一比|多少钱|推荐|"
    # 🔴 2026-11-13 实测（test_attack5 X05）：用户说「太贵了，便宜点的」，
    #   这是在**要更便宜的机器**，不是在发情绪。第一次漏了"便宜"，被社交层接走，
    #   只回了一段"两条路你选"，没换台 —— 判据必须是"有没有要办事"，不是"有没有情绪词"。
    r"设计|剪辑|编程|写代码|办公|打游戏|专业|上课|宿舍|"
    r"便宜|少点|低点|降点|更贵|价格|钱少|"
    # 🔴 2026-11-13 晚（eval_behavior 抓到，47 条真人说法里 2 条）：
    #    「算了换一个吧」→ 判 frustration → 回了一段"两条路你选"，**一台都没换**
    #    「太贵了买不起」→ 同上，用户明明在说"换"，系统在跟他商量预算
    #    两句都命中 frustration 词表（"算了"/"太贵"/"买不起"），
    #    而 TASK_SIGNAL 里只有"换一台|换台"——「换一个」「换掉」「下一个」没写。
    #    判据：**用户有没有给出下一条动作**。给了就是有活儿要干，
    #    情绪词只是语气，不能因为语气重就把活儿丢了。
    r"换一个|换个|换掉|换了吧|下一个|下一台|pass|"
    # 🔴 「买不起 / 超预算 / 钱不够」= 用户已经**替系统做了决定**：
    #    这个价位他不要，必须换一台更便宜的。这和单纯喊"好贵"不是一回事 ——
    #    "好贵"是要安慰/要解释（走 social 是对的），
    #    "买不起"是要一台买得起的（走 social 就是把他晾在那儿）。
    r"买不起|超预算|钱不够|太贵了.*(换|别的)|换个便宜|便宜点|"
    # 🔴 2026-11-13 深夜（追问路由体检抓到）：「是不是买贵了」被判 frustration。
    #
    #    这句命中 frustration 的"贵了"，于是回了一段"两条路你选一条"。
    #    但用户是在**求证一个判断**——"这价是不是贵了"，要的是"这个价在库里排第几"。
    #    给一段情绪安慰，等于答非所问（他并没有难受，他是想知道）。
    #
    #    判据：带**疑问形态**的价钱句 = 在问，不是在抱怨。
    #    这一条同时收「买贵了没」「贵不贵」「是不是贵了」「算不算贵」——
    #    它们的共同点是**没有下结论**，留了个"你觉得呢"的口子。
    #    ⚠️ 不能收"太贵了"（无疑问形态，那是抱怨，走 social 是对的）。
    r"买贵了|贵了吗|贵了没|贵不贵|算不算贵|值不值"
    # 以问号结尾且带价钱评价词的，也是在问
    r"|(?:贵|便宜|划算|值).{0,3}[吗嘛呢]\s*[？?]?\s*$"
    # 🔴 2026-11-13 晚（留出集 C 抓到）：「算了不看了」被 frustration 接走，
    #    回了一段"两条路你选一条"，**一台都没换**。
    #
    #    但它和「太贵了」不是一类：
    #      「太贵了」    = 一句抱怨，用户还在原地，需要的是安慰或解释 → social 对
    #      「算了不看了」= 带**收线动作**（算了/不看了），用户已经放下这台了 → 要换
    #    差别不在情绪强弱，在**有没有放弃这个对象**。
    #
    #    判据：出现"算了 / 不看了 / 不想看 / 别看了"这类**主动终止**的动词。
    #    ⚠️ 只收"算了"，不收"算了，就这台吧"那种——后者带"就这台"，
    #       会把意图层拉到确认式（ask_current），走主流程正好判得对；
    #       留在 social 反而丢失了"他其实接受了"这层意思。
    r"算了|不看了|不想看|别看了|看不下"
    # 结尾这一对引号+括号必须有 —— 上一版编辑丢过，整个模块直接 SyntaxError，
    # 而且错在第 3771 行、看起来跟改动处无关，排查了半天。
)


def classify_social(text):
    """纯社交句 → 返回标签；带任务信号的一律返回 None（交给主流程）。

    长度也设上限：超过 40 字基本都在说需求，"谢谢"只是顺口带的。
    """
    t = (text or "").strip()
    if not t or len(t) > 40:
        return None
    if TASK_SIGNAL.search(t):
        return None
    for label, pat in SOCIAL_PATTERNS:
        if pat.search(t):
            return label
    return None


def social_reply(label, known=None, focus_name=None, last_stage=None):
    """社交回应：短、有人味、每句都留一个下一步。

    ⚠️ 一句机器评价都不许有：这里能说的只有"用户处境"和"系统能做什么"。
    """
    known = known or {}
    has_ctx = bool(known.get("budget") or known.get("purpose") or known.get("cat"))

    if label == "frustration":
        t = ""
        if known.get("budget"):
            t = "预算这条我不劝你加，也不会拿超预算的机器糊你。"
        else:
            t = "先别急，选机这事本来就不该一眼定。"
        return (t + "两条路我都能走：一是把预算钉死，我告诉你这个价里真实能买到什么、"
                     "差的那点差在哪；二是放宽一条你最不在意的（内存/重量/品牌），我按新条件重排。"
                     "你选一条。")

    if label == "browse":
        # ⚠️ 这里**不许出现具体价位**：4500–5500 这种区间不是库里的数，
        #    说出来就是"看着专业的编造"。只描述两条路的重点看什么。
        return ("行，不急着定。我先按最常见的两条路子各说一句：\n"
                "· 只上课写作业、要背来背去 → 走轻薄本，重点看「重量」和能不能加内存；\n"
                "· 要跑设计/剪辑/游戏 → 得走游戏本，重点看「显卡」和内存能不能加。\n"
                "你更像哪边？说个大概我就往下收。")

    if label == "indecision":
        return ("纠结通常不是选项太多，是「还差一条硬标准」。就问你一个："
                "你更怕哪种后悔 —— 背出去嫌重，还是跑起来嫌慢？"
                "定了这条我就能收口成一台，不用你在一堆参数里挑。")

    if label == "thanks":
        tail = ("记住一条就够：这类机器我只能报参数，别把它当成\"推荐\"。"
                if last_stage == "recommend"
                else "预算或用途一变，结果就会跟着变，随时说。")
        return "不客气。" + tail

    if label == "bye":
        return ("行，那就先这样。数据是 %s 的快照，下单前价格自己再核一眼 —— "
                "库里记的和当天页面可能差几十块。" % core.data_as_of())

    if label == "greet":
        if has_ctx:
            return ("在。刚才的条件还留着%s，继续说就行。"
                    % ("（%s）" % _slots_brief(known) if _slots_brief(known) else ""))
        return "在。你把预算和用途说一句就行 —— 我先给一台具体的，不合适再换，不用你一条条挑。"

    if label == "praise":
        # 不谄媚：把功劳还给数据，而不是收下夸奖
        return ("能不能帮上忙，取决于库里有没有这台的数据。"
                "我唯一敢保证的是：说出来的一句一句都能指回数据，指不回去的我会说没有。")

    # smalltalk（嗯/好的/哈哈）
    if has_ctx:
        return "嗯。接着刚才的聊，还是换个条件？"
    return "嗯，你说 —— 预算和用途给我一句就行。"


def _slots_brief(slots):
    """把已知条件压成一句人话，给社交层复用（不新造数字）"""
    out = []
    if slots.get("budget"):
        out.append("预算 ¥%s" % ("%g" % slots["budget"]))
    if slots.get("cat"):
        out.append({"thin": "轻薄本", "gaming": "游戏本",
                    "desktop": "台式整机", "upgrade": "内存固态"}.get(slots["cat"], ""))
    p = slots.get("purpose") or []
    if isinstance(p, str):
        p = [p]
    cn = {"design": "设计", "video": "视频", "gaming": "游戏", "dev": "编程",
          "office": "办公", "threeD": "三维", "audio": "音频", "ai": "本地模型"}
    if p:
        out.append("用途 " + "/".join(cn.get(x, x) for x in p))
    return "、".join([x for x in out if x])


def run(user_text, known=None, asked=None, last_stage=None, seen=None,
        focus=None, verbose=False):
    """对外入口：保证每个分支都把 known 带回去，前端才能续上状态。"""
    out = _run(user_text, known=known, asked=asked, last_stage=last_stage,
               seen=seen, focus=focus, verbose=verbose)
    # 统一兜底：任何分支漏返 known 都会让下一轮从零开始。
    # 实测 2026-11-11：clarify 分支漏返，导致「要 32G 内存」的硬约束
    # 在第二轮直接消失，「换一台」推出来的机器完全不满足用户说过的条件。
    if isinstance(out, dict) and out.get("known") is None:
        out["known"] = dict(out.get("slots") or {})
    # seen 同理：compare / followup 这些分支原来不返 seen，
    # 下一轮"换一台"就又从第一台开始 —— 用户看到的就是死循环。
    #
    # 🔴 2026-11-17 修：光"透传 seen"不够，还要**把当前这台补进去**。
    #
    #    实测（用户第二次实测）：
    #      [12] 华为MateBook D16怎么样  → stage=fit,      seen=[]
    #      [13] 拿他打游戏             → stage=followup, seen=[]
    #      [14] 那换一台吧             → stage=clarify,  seen=[]  ← 不知道看过啥
    #
    #    fit/followup 分支都不往 seen 里写，于是到「换一台」时 seen 是空的，
    #    系统把已经看过的机器又推一遍。
    #
    #    判据：本轮有 focus（说明在讨论某一台），而这台还没在 seen 里 → 补进去。
    #    ⚠️ 只在"用户还在看这台"时补；换台成功后 focus 变新机器，再下一轮自然累积。
    if isinstance(out, dict) and out.get("seen") is None:
        out["seen"] = list(seen or [])
    if isinstance(out, dict):
        _cur = out.get("focus")
        if _cur and _cur not in (out.get("seen") or []):
            out["seen"] = list(out.get("seen") or []) + [_cur]
    # 🔴 2026-11-17：维护「已问过的主题历史」，供下一轮检测重复提问。
    #
    #    实测死循环：连续三轮问售后，三次输出完全一样。
    #    系统必须知道"这是第三次问同一件事"，才能换角度而不是复读。
    #
    #    存在 known 里（`_askedTopics`），随 slots 一起回传给前端。
    #    只保留最近 6 条 —— 太久远的重复不算"没答到点上"。
    if isinstance(out, dict):
        _topics = list((known or {}).get("_askedTopics") or [])
        _now_topic = None
        try:
            import intent_layer as _il_t
            _lr_t = _il_t.route(user_text or "", focus or None)
            if _lr_t.get("model_ok"):
                _t = _lr_t.get("topic")
                if _t and _t != "none":
                    _now_topic = _t
        except Exception:
            pass
        if _now_topic:
            # 中英文主题名统一：路由给的是英文（service/screen…），
            # 而 _topic_facts 用中文（售后/屏幕…），这里存英文即可，
            # answer_followup 那边比对的是 _topic_facts 的返回值，
            # 所以两边要一致 —— 见下面的映射。
            _cn = {"service": "售后", "screen": "屏幕", "keyboard": "键盘",
                   "noise": "散热", "build": "做工", "weight": "重量",
                   "battery": "续航", "price": "价格", "config": "配置",
                   "pros_cons": "优缺点"}.get(_now_topic, _now_topic)
            _topics.append(_cn)
            _topics = _topics[-6:]
        if _topics:
            sl = dict(out.get("slots") or {})
            sl["_askedTopics"] = _topics
            out["slots"] = sl
    _sample_log(user_text, out, focus)
    return out


def _sample_log(user_text, out, focus=None):
    """测试即采样（2026-11-13）：设了 WB_SAMPLE_LOG=1 就把这一轮落到
    `lora_data/auto-<日期>.jsonl`，供后面筛成训练样本。

    用户原话：「测试的话记得同时可以把一些数据当作后续 lora 的样本集」。
    为什么不在测试脚本里各写一遍：那样就要改 12 个文件，而且漏一个就少一截；
    挂在 `run()` 出口只写一处（宪法第 9 条）。**默认关闭**，不影响线上日志，
    也不改任何返回内容 —— 写失败一律静默，绝不让"记样本"影响回答。
    """
    if not os.environ.get("WB_SAMPLE_LOG"):
        return
    try:
        import datetime
        d = os.path.join(os.path.dirname(os.path.abspath(__file__)), "lora_data")
        os.makedirs(d, exist_ok=True)
        rec = {"text": user_text, "stage": out.get("stage"),
               "reply": (out.get("reply") or "")[:1200],
               "slots": out.get("slots") or {}, "focus": out.get("focus") or focus,
               "social": out.get("social"),
               "issues": bool(out.get("fabricated_words") or out.get("outside_products")),
               "ts": datetime.datetime.now().isoformat(timespec="seconds")}
        path = os.path.join(d, "auto-%s.jsonl" % datetime.date.today().isoformat())
        with io.open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    except Exception:
        pass


def _run(user_text, known=None, asked=None, last_stage=None, seen=None,
         focus=None, verbose=False):
    """focus: 当前正在讨论的机型 id。
    这个状态以前不存在，导致 2026-11-11 16:27 两个连环错：
    ① 「打游戏这个合适吗」被当成换品类 → 推了台游戏本
    ② 「我说的就是刚刚你给我推荐的那一台」没有指代对象 → 顺理成章换了台
    前端每轮把 focus 带回来，后端据此判断"这句是在问这台，还是在提新需求"。"""

    # 🔴 模型为主的第一步（2026-11-16 · 毕设架构反转）：
    #    **一轮只调一次模型**，出全部路由决策（intent + topic + fit），
    #    存进 _LAST_ROUTE 供本函数内所有路由点共用 ——
    #    `asks_about_current`（追问入口）、named 分支的匹配/细节分流、
    #    意图分类，读的都是这一份结果。词表只在模型不可用/字段缺失时兜底。
    #    ⚠️ _LAST_ROUTE 是模块级变量：agent 是单线程对话、每轮一次 _run，
    #       重入风险不存在；但任何**绕过 _run 直接调路由函数**的测试
    #       会读到上一轮的残留 —— 那些测试本来就该走 run() 入口。
    try:
        import intent_layer as _il
        _LAST_ROUTE[0] = _il.route(user_text, focus)
    except Exception:
        _LAST_ROUTE[0] = None      # 意图层挂了 → 全词表兜底，系统必须还能跑

    outside_scope = check_scope(user_text)
    if outside_scope:
        return {"stage": "refuse", "slots": dict(known or {}), "picked": None,
                "focus": focus,
                "reply": "我只做 Windows 笔记本、台式整机和内存固态，%s 这类不在覆盖范围内。"
                         "如果你有 Windows 机器的需求，我可以帮你看。" % outside_scope,
                "reason": "范围外：" + outside_scope}

    # 0a. 纯社交（招呼 / 道谢 / 收尾 / 纠结 / 太贵了）→ 接住人话，不推机器。
    #     放在 check_scope 之后（"苹果笔记本谢谢" 仍要先拒），
    #     放在一切槽位逻辑之前（"谢谢" 不该进 clarify 追问）。
    #     focus 必须原样带回去 —— 用户只是道谢，不代表放弃正在聊的那台。
    _social = classify_social(user_text)
    if _social:
        _reply = social_reply(_social, known=known, last_stage=last_stage)
        # 下一步按钮按标签给：收尾类（道谢/告别/夸奖）**不给**，
        # 给了等于拦着人不让走。只给"这句之后真的能接住"的说法 ——
        # 选项必须能被系统听懂，否则又是一次"点了没反应"（2026-11-12 的死循环教训）。
        _SUG = {
            "frustration": (["换一台", "把其余候选列出来"] if focus
                            else ["预算 4000，只上课用", "预算 6000，学设计"]),
            "indecision": (["换一台", "把其余候选列出来"] if focus
                           else ["预算 6000，上课用", "预算 8000，打游戏"]),
            "browse": ["预算 5000，上课用", "预算 8000，打游戏"],
            "greet": (["接着说"] if focus else ["预算 5000，上课用", "预算 8000，打游戏"]),
            "smalltalk": (["换一台", "把其余候选列出来"] if focus
                          else ["预算 5000，上课用"]),
        }
        _sug = _SUG.get(_social, [])
        return {"stage": "social", "slots": dict(known or {}), "social": _social,
                "reply": _reply, "focus": focus,
                "focusName": None, "picked": None,
                "questions": [], "warnings": [], "suggest": _sug,
                "dataAsOf": core.data_as_of(),
                "seen": list(seen or []), "known": dict(known or {}),
                "outside_products": [], "untraceable_numbers": [],
                "fabricated_words": []}

    # ══════════════════════════════════════════════════════════════
    # 🔴 换血第 1 点：「要不要换台」由意图层说了算（2026-11-13 晚）
    # ══════════════════════════════════════════════════════════════
    # 为什么必须改 —— 实测（留出集 C，70 条）：
    #
    #   「这个价有点离谱了吧」  意图层 = refuse_switch（对）
    #                           规则   = False（SWITCH_KW 15 个词一个没中）
    #                           → 系统答"¥3000，是全库最便宜的"
    #   用户说的是"这价格我不接受"，系统在向他证明这机器便宜。
    #   这不是判错方向，是**根本没听见**用户已经否掉了。
    #
    # 判据：want_switch = 规则 OR 意图层。
    #   · 规则先跑 ——「换一台/换掉/下一个」这类转台动词规则零误判、零延迟，
    #     占到真实换台请求的绝大多数，不该让它们等 0.2 秒。
    #   · 规则说不换、但意图层说是 refuse_switch → 采信意图层。
    #     这一支正是"词表穷举不完"的地方。
    #   · 规则说是、意图层说不是 → 仍采信规则。规则的否定判据是从
    #     5 次真实事故里长出来的（「比别的便宜多少」被当换台那次），
    #     比模型的单次判断可靠，不能反过来被模型推翻。
    #
    # ⚠️ 顺序反过来（先问模型）会把每一轮的延迟从 0.0007 秒推到 0.23 秒，
    #    而绝大多数轮次根本是在追问细节、不是换台 —— 那样是拿全局体验换少数几条。
    want_switch = _is_switch_request(user_text)
    if not want_switch:
        # 规则没认出来，才问意图层。异常一律当作"不换"（保持改动前行为）。
        try:
            import intent_layer as _il_sw
            _sw_lab, _sw_why = _il_sw.classify(user_text, focus, allow_model=True)
            if _sw_lab == INTENT_REFUSE_SWITCH:
                want_switch = True
        except Exception:
            pass
    is_compare = any(k in user_text for k in COMPARE_KW)
    on_current = bool(focus) and not want_switch and refers_to_current(user_text, focus)

    # ═══════════════════════════════════════════════════════════
    # 0b2. 🔴 2026-11-21 新增：**数据分析**路径（毕设题目要求）
    #
    #    用户问的是整个库的统计特征，不是要一台机器：
    #      「有多少台有独显」「8000以内平均多重」
    #      「各品牌售后评分对比」「32G内存的价格分布」「性能最强的五台」
    #
    #    原来这些都走 state_range → clarify → 回「是笔记本还是台式？」
    #    （实测 5 个分析类问题，4 个被这么打回 —— 完全答非所问）。
    #
    #    架构：**模型理解 + 代码计算**
    #      ① 模型把问题解析成 {agg, field, filter, group_by}（不碰数字）
    #      ② analyze.analyze() 确定性计算（可复现、可追溯）
    #      ③ 模型把结果组织成人话
    #
    #    为什么不让模型直接算：
    #      · 223 台的聚合计算模型必然出错（它连"第几名"都编过）
    #      · 答辩要能说清每个数字怎么来的 → 代码可复现
    #
    #    判据：模型路由给 analyze，**或**规则认出分析句式（模型不可用时兜底）。
    #    位置必须在 0c（点名机型）之前 —— 否则「有多少台有独显」里的
    #    "独显"可能被当机型名去匹配。
    # ═══════════════════════════════════════════════════════════
    _lr_an = _LAST_ROUTE[0]
    _want_analyze = bool(_lr_an and _lr_an.get("model_ok")
                         and _lr_an.get("intent") == INTENT_ANALYZE)
    if not _want_analyze:
        # 规则兜底：明显的统计句式
        #
        # 🔴🔴 2026-11-23：**加了否定条件**，修一个实测 bug。
        #
        #    事故：「可以，放宽预算推荐几台」（上下文：7000 元轻薄本）
        #    走成了 analyze 分支，回答：
        #      「放宽预算后，华硕无畏 Pro16、华为 MateBook Pro S、
        #        联想小新 Pro14、拯救者 R9000P 和荣耀猎人游戏本
        #        这五台机型价格均为 7999 元。」
        #
        #    **完全荒诞**：用户要的是推荐，系统给了一句"五台同价"的废话。
        #
        #    根因：正则里的 `几台` 命中了「推荐**几台**」。
        #    `几台` 在「有多少台」里是计数，在「推荐几台」里只是量词。
        #
        #    修法：命中统计词之后，再看有没有**明确的推荐/换台动作**。
        #    有 → 不是统计，是推荐（analyze 否决）。
        #
        #    为什么用否决而不是删掉 `几台`：
        #    「有几台带独显」是合法的统计问句，删了会漏。
        _t = user_text or ""
        _hit_stat = bool(re.search(
            r"多少台|几台|平均|中位数|分布|各品牌|各品类|按品牌|"
            r"最强|最弱|最贵|最便宜|排行|排名|占比|统计|对比一下各", _t))
        # 「推荐几台」「换个几台」里的「几台」是量词，不是统计
        _is_recommend = bool(re.search(
            r"推荐|推几台|给几台|来几台|看几台|挑几台|选几台|"
            r"换[一台两三四五六七八九十]|再来|再给|放宽|"
            r"帮我找|给我找|列几台|来几款|推荐几款", _t))
        _want_analyze = _hit_stat and not _is_recommend
    if _want_analyze:
        try:
            import analyze as _an
            import analyze_ctx as _actx
            # 🔴 2026-11-22：**带上上一轮的分析上下文**，解决指代丢失。
            #
            #    实测 bug：
            #      Q1「各品牌数量对比」→ 最大组 联想（98 台）
            #      Q2「那它平均价格多少」→ 解析 filter={}
            #          → 算出全库平均 ¥11,360（223 台）
            #          期望 联想平均 ¥13,206（98 台）  ← 差 2000 元
            #
            #    **用户以为是联想的，系统给了全库的。** 数字是真的，
            #    但答的不是问的问题 —— 这比不回答更危险。
            _q = _an.parse_query(user_text, ctx=_actx.get())
            if _q:
                _res = _an.analyze(_q)
                if _res.get("ok"):
                    # 记下这一轮，供下一轮追问用
                    _actx.remember(_res, _q)
                    _reply = _render_analysis(user_text, _res, _q)
                    return {"stage": "analyze", "slots": dict(known or {}),
                            "reply": _reply, "focus": focus,
                            "focusName": None,
                            "questions": [], "warnings": [],
                            "dataAsOf": core.data_as_of(),
                            "analysis": {k: _res.get(k) for k in
                                         ("n", "agg", "field", "value",
                                          "groups", "rows", "text")},
                            "outside_products": check_outside_products(_reply),
                            "untraceable_numbers": [],
                            "fabricated_words": []}
        except Exception:
            # 分析失败不吞掉：落到下面正常流程（最差也是普通推荐）
            pass

    # 0c. 用户**直接点名**了库里某台机型 → 就地切 focus 回答，不进推荐流程。
    #
    # 为什么要有（2026-11-11 演示前实测）：
    #   U「华为MateBook D16怎么样」→ A「是笔记本还是台式？大概想放在宿舍用…」
    #   用户已经指名道姓，系统还在问最基础的问题 —— 最伤体验的一类。
    #
    # 位置很关键，必须在 on_current 之前、SRC_ASK/PRICE_LABEL 之后：
    #   · 放 on_current 之后 → 「这台 MateBook D16 怎么样」会被指代分支吃掉，
    #     答的是 focus 那台（可能是另一台），用户问 A 系统答 B
    #   · 放 check_scope 之前 → 句子里带"手机"的会被当成越界，
    #     连"MateBook 和小米手机哪个值"这种也该先拒
    #
    # 走哪条下游由句子本身决定，不一律当成「问这台行不行」：
    #   带 FIT_KW（怎么样/行不行）→ _answer_current（用途匹配判断）
    #   带 FOLLOWUP_KW（保修/缺点/屏幕）→ answer_followup（细节）
    #   都没有 → 默认回答"这台是什么"，用 _answer_current 最稳（它必答结论）
    # 0d. 用户点名了一台**库里没有**的机型 → 明说没有，不要拿当前那台糊过去。
    #
    # 实测 2026-11-11 演示走查：
    #   U「ThinkBook 14 怎么样」（库里没有 ThinkBook）
    #   A「这台机器对你做设计来说只能算部分匹配…」  ← 拿天选 7 答的
    # 用户问的是一台库里根本没有的机器，系统却把 focus 那台讲了一通。
    # 这是"答了另一个问题"，比反问糟糕得多 —— 演示时对方一眼就能看穿。
    #
    # 位置必须在 named/on_current 之前：match_named_model 按设计返回 None（弃权），
    # 弃权之后没有任何人接手，就顺着落到 on_current 用旧 focus 答了。
    ghost = unmatched_model_name(user_text)
    if ghost and not want_switch:
        # 显示时保留用户原来的大小写写法（"ThinkBook 14" 比 "THINKBOOK14" 好看）
        shown = re.search(r"[A-Za-z][A-Za-z0-9 ]{2,18}", user_text or "")
        shown = shown.group(0).strip() if shown else ghost
        # 🔴 这里原来写死「22 台」，v0.4 起池子是 100 台 —— 数字必须跟着池子走，
        #   写死就会在用户面前报错数（而且是最容易当场被抓的那种错）。
        n_all = len(_pool_offers_for_lookup())
        reply = ("库里没采到这台 —— 你说的「%s」不在我这份数据里，"
                 "我不认识它的配置和价格，硬答就是编。\n"
                 "我现在能查的是这 %d 台（京东在售、有到手价和配置记录的）。"
                 "你可以换个型号问我，或者告诉我预算和用途，我从库里给你挑。"
                 % (shown, n_all))
        return {"stage": "compare", "slots": dict(known or {}), "reply": reply,
                "focus": focus, "focusName": None,
                "questions": [], "warnings": [],
                "dataAsOf": core.data_as_of(),
                "outside_products": [], "untraceable_numbers": [],
                "fabricated_words": [], "reason": "库里无此型号：" + ghost}

    named = match_named_model(user_text)
    if named and (not focus or named["id"] != focus):
        # named 是库里那台，不是当前 focus —— 用户切换了讨论对象。
        # 「换一台」这类明确要求换机的句子不按点名处理（那是换台流程）。
        if not want_switch:
            purpose_now = (known or {}).get("purpose") or []
            # 🔴 模型为主（2026-11-16）：匹配/细节的分流先看模型的路由结果，
            #    词表只在模型不可用时兜底。模型挂时的行为与反转前完全一致。
            lr = _LAST_ROUTE[0]
            if lr and lr.get("model_ok"):
                ask_fit_kw = bool(lr.get("fit"))
                ask_detail_kw = bool(lr.get("topic")
                                     and lr.get("topic") != "none")
            else:
                ask_fit_kw = any(k in user_text for k in FIT_KW)
                ask_detail_kw = any(k in user_text for k in FOLLOWUP_KW)
            # 🔴 分流的**主维度是「有没有用途」，不是话题**（named 回归抓到）：
            #    「联想小新16如何」模型给了 topic=pros_cons → 旧判据走了 followup
            #    讲了一堆缺点 —— 可用户连用途都没说，讲匹配/缺点都为时过早，
            #    该先引导；「Redmi Book Pro 14 怎么样」+ purpose=design 时模型
            #    fit 给了 False（它把"怎么样"当泛问）→ 也走了 followup，
            #    而用途在手就该直接判匹配。
            #    ⇒ 没用途 → intro（引导）；有用途 → fit（判匹配）；
            #      只有"有用途、明确只问细节、且不是在问匹配"才走 followup。
            if purpose_now:
                out = _answer_current(user_text, named, known or {}, named["id"])
            elif ask_detail_kw and not ask_fit_kw \
                    and (not lr or not lr.get("model_ok")
                         or (lr.get("topic") not in (None, "pros_cons"))):
                # 还没说过用途、又问的是**具体面**（"保修几年"/"屏幕怎么样"）→ 答细节。
                # 🔴 pros_cons 不算具体面（named 回归抓到）：「联想小新16如何」
                #    是整机泛问，模型把"如何"给了 topic=pros_cons ——
                #    于是没问用途就先倒了一堆缺点。泛问的正确动作是
                #    介绍这台 + 引导给用途（intro），不是硬挑一个面讲。
                reply = answer_followup(user_text, _merge_offer(named, (known or {}).get("_askedTopics")))
                out = {"stage": "followup", "slots": dict(known or {}), "reply": reply,
                       "focus": named["id"], "focusName": named["name"],
                       "questions": [], "warnings": [],
                       "dataAsOf": core.data_as_of(),
                       "outside_products": check_outside_products(reply),
                       "untraceable_numbers": [], "fabricated_words": []}
            else:
                # 还不知道用途 → 先介绍这台，再反问用途。
                # 实测 2026-11-11：直接走 _answer_current 会输出
                # 「数据不足，目前没法判断它适不适合你」—— 用户问"怎么样"，
                # 得到一句"我不知道"，比之前的反问品类更差。
                out = _intro_model(user_text, named)
            out["reason"] = "指名问型号：" + named["name"]
            return out

    # 「划算吗」「性价比高吗」「值不值」—— 这几个词只有一种解释：在问刚才那台。
    # 它们不带「这个/这台」这种指代词，refers_to_current() 判 False（实测 2026-11-11），
    # 于是掉进 recommend 重新推荐，模型顺手编出"性价比很高"这种没依据的结论。
    # 判据：带价格评价词 + 不带需求表达（"我要/想买/推荐"）+ 没在说范围。
    bare_price_q = (bool(focus) and not want_switch
                    and any(k in user_text for k in PRICE_Q_KW)
                    and not any(k in user_text for k in DEMAND_WORDS)
                    and not REF_NOT_CURRENT.search(user_text)
                    # 🔴 2026-11-13 晚：「这价格劝退」是**结论**，不是问句。
                    #    "这价格"命中 PRICE_Q_KW → 被当成"问这个价怎么样"，
                    #    系统一本正经地回答"¥3000，是全库最便宜的"——
                    #    用户刚说了"劝退"，它还在夸便宜。
                    #    判据：出现明确拒绝表态（劝退/麻了/不看了/放弃），
                    #    问价就不成立 —— 同一个句子里，表态压过提问。
                    and not re.search(r"劝退|麻了|不看了|放弃|算了不要|算了吧", user_text or ""))
    if bare_price_q:
        on_current = True

    # 0a2. 🔴 2026-11-13 晚：**意图层第一次真正接到路由上。**
    #
    #      在这之前 intent_layer 判得再准也没用 —— `_run()` 只读 INTENT_UNKNOWN
    #      一个标签，其余 5 个（ask_current / refuse_switch / state_range /
    #      state_new_need / list_others）**一次都不读**，真正的路由靠
    #      FIT_KW(28词) / FOLLOWUP_KW(31词) / SWITCH_KW(15词) 三套独立词表。
    #      把标签从 A 改成 B，行为 0 次变化（实测：强制返回 ask_current，5 条样本全无差别）。
    #
    #      实测被漏掉的是这一类 —— 意图层判对、refers_to_current 也是 True，
    #      但 FIT_KW 和 FOLLOWUP_KW 一个词都没命中，于是落到 recommend 把榜首又讲一遍：
    #          「能撑四年不」「带出去累不累」「电池能顶一天吗」
    #          「这机器顶不顶」「卖这么贵值在哪」
    #      这五句都明明白白是在问这台。用户看到的却是"它又把同一台推了一遍"。
    #
    #      判据（四条同时满足才开门，宁可漏不许误 —— 误判的代价是需求被丢）：
    #        ① 意图层说是 ask_current
    #        ② 有 focus（没有"当前这台"，就谈不上"问这台"）
    #        ③ 这一轮没改条件（改了就是新需求，必须重排）
    #           ⚠️ 不能用 `_delta` —— 那个变量要到 6c0 段（约 4298 行）才赋值，
    #              这里在它之前。用一个本地判断：原话里有没有"加/换/要"这类改槽位的信号。
    #        ④ 不是换台/比价/列清单/别的渠道问价（这些各有专门分支，会先返回）
    #      开门之后走 1. 段：FIT_KW 命中则判匹配度，否则走 answer_followup 讲参数。
    _cond_changed = bool(has_new_condition(user_text or "")) \
        or bool(_budget_in_text(user_text or "")) \
        or bool(re.search(r"换成|改为|改成|要个|要个|要台|加个|加装|升级", user_text or ""))
    if (focus and not on_current and not want_switch and not is_compare
            and not _cond_changed):
        _it, _why = INTENT_UNKNOWN, "skipped"
        try:
            import intent_layer as _il2
            _it, _why = _il2.classify(user_text, focus)
        except Exception:
            _it = INTENT_UNKNOWN
        if _it == INTENT_ASK_CURRENT:
            on_current = True

    # 0. 问别的渠道的价格 —— 库里只有京东的价，答不了就必须明说答不了。
    #    必须放在 on_current **之前**：实测「淘宝上是不是更便宜」不带「这个/这台」，
    #    refers_to_current() 判 False，会一路掉到最后走 recommend，模型就开始编。
    #    （复现记录见 SRC_ASK 定义处的注释）
    src_asked = SRC_ASK.search(user_text)
    if src_asked:
        o = core.get_offer(focus) if focus else None
        if o:
            reply = ("我库里只存了京东的到手价，没有别的平台的价 —— "
                     "你这句问的是别家多少，我没法回答，硬答就是编。\n"
                     "%s 京东现在是 ¥%s。要横向比价，你直接把另一边的价告诉我，"
                     "或者两台摆一起，我帮你比配置值不值这个差。" % (o["name"], o.get("price")))
        else:
            reply = ("我库里只存了京东的到手价，没有别的平台的价 —— "
                     "你这句问的是别家多少，我没法回答，硬答就是编。\n"
                     "你先告诉我预算和用途，我把京东这边的候选列出来，"
                     "你去别的平台照着型号查价会快很多。")
        return {"stage": "compare", "slots": dict(known or {}), "reply": reply,
                "focus": focus, "focusName": o["name"] if o else None,
                "questions": [], "warnings": [],
                "dataAsOf": core.data_as_of(),
                "outside_products": [], "untraceable_numbers": [],
                "fabricated_words": [], "reason": "渠道比价：非京东价格无数据"}

    # 0b. 问库里没有的价签 / 没有的指标 —— 数字能对上，但标签是假的。
    #     放在 SRC_ASK 之后：「闲鱼二手的多少钱」应该先被渠道闸拦（那是平台问题），
    #     只问「出厂价多少」才走这里。
    #     见 PRICE_LABEL / RANK_CLAIM 定义处的实测记录。
    label_hit = PRICE_LABEL.search(user_text) or RANK_CLAIM.search(user_text)
    if label_hit and not SRC_ASK.search(user_text):
        o = core.get_offer(focus) if focus else None
        is_price = bool(PRICE_LABEL.search(user_text))
        if o:
            if is_price:
                reply = ("价格我只记了三个数：到手价 ¥%s、原价、以及国补多少。"
                         "出厂价 / 拿货价 / 成本价这类我库里没有 —— "
                         "原价是零售标价，跟出厂成本不是一回事，不能拿来混着说。"
                         % o.get("price"))
            else:
                reply = ("销量、排名、好评率这类我库里一项都没采，说不了。"
                         "%s 京东到手价 ¥%s，配置和优缺点是我能负责的部分。"
                         % (o["name"], o.get("price")))
        else:
            reply = ("你说的这个指标我库里没有。价格只记了到手价、原价和国补三项；"
                     "销量、排名、好评率也一项都没采。\n"
                     "先把预算和用途告诉我，我在有据可查的范围内给你挑。")
        return {"stage": "compare", "slots": dict(known or {}), "reply": reply,
                "focus": focus, "focusName": o["name"] if o else None,
                "questions": [], "warnings": [],
                "dataAsOf": core.data_as_of(),
                "outside_products": [], "untraceable_numbers": [],
                "fabricated_words": [], "reason": "概念错配：库里无此价签/指标"}

    # 1. 追问到当前这台：只讲这台的细节，不改品类、不动条件。
    #    分两条路，顺序不能颠倒：
    #      FIT_KW（合适吗/能不能）→ 用途匹配判断，走 _answer_current
    #      FOLLOWUP_KW（保修/缺点/屏幕）→ 细节追问，走 answer_followup
    #    实测 2026-11-11：只写一条 if 时，"它保修几年"被 _answer_current 接走，
    #    那个函数是判用途匹配的，会顺手编出"这台机器保修一年"。
    if on_current:
        o = core.get_offer(focus)
        # 🔴 2026-11-13 深夜：`ask_detail` 的判据统一到 `asks_about_current()`。
        #
        #    原来这里是 `any(k in user_text for k in FOLLOWUP_KW)`，
        #    只认那 30 个词，于是「接口够用吗」两不沾 ——
        #    "接口"不在 FOLLOWUP_KW，"够用"在 FIT_KW 但它问的是接口不是用途。
        #    结果走了 _answer_current（判用途匹配），答了整机配置，一个字没提接口。
        #    而系统**明明已经认出主题了**（`_topic_of` 返回"接口"）。
        #
        #    统一到一处之后，两个来源取并集，且 `is_followup()` 用的是同一份判据 ——
        #    不会再出现"这里说是追问、那里说不是"（宪法第 9 条）。
        ask_detail = asks_about_current(user_text)
        # 🔴🔴 2026-11-17：`ask_fit` 从「纯词表」改成「模型为主、词表兜底」。
        #
        #    这是架构反转**做了一半**的最后一处 —— `ask_detail` 已经读模型了
        #    （见上面注释），但 `ask_fit` 还停在词表时代。
        #
        #    实测代价（用户 2026-11-17 实测）：
        #      「限电 500W」→ 模型判 `fit=True`（在问匹配），
        #      但 `FIT_KW` 没命中 → `ask_fit=False` → 模型判断被丢弃
        #      → 走了 answer_followup，topic=battery 没数据
        #      → 退化报整机参数（用户看到「问限电答屏幕参数」）。
        #
        #    这就是"调了模型却不采信它"的典型 —— 用户感知是"死板/听不懂"。
        #
        #    为什么之前一直没改：`ask_fit` 的词表判据是 2026-11-11 那批
        #    真实事故（「它保修几年」被 _answer_current 接走）沉淀下来的，
        #    改它有回归风险。但现在 `intent_layer.route()` 的 fit 字段
        #    已经在 test_intent 里验过，可以放心让模型先说话。
        #
        #    ⚠️ 词表**不删**：模型不可用（Ollama 挂了）时它是唯一兜底。
        _lr_fit = _LAST_ROUTE[0]
        if _lr_fit and _lr_fit.get("model_ok") and _lr_fit.get("fit") is not None:
            ask_fit = bool(_lr_fit.get("fit"))
            # 模型说 fit，但词表也命中 → 一致，无需额外处理
            # 模型说 fit=True 而词表没命中 → 采信模型（本修法的核心）
            # 模型说 fit=False 而词表命中 → 仍采信模型（它看的是整句语义）
        else:
            # 模型不可用 → 纯词表兜底（行为与反转前一致）
            ask_fit = any(k in user_text for k in FIT_KW)
        ask_price = any(k in user_text for k in PRICE_Q_KW)
        # 「这个价怎么样」「划算吗」—— 先处理，否则会被下面的 FIT_KW/穿透吃掉。
        # 关键：**用库内数据算出真实位置**，不让模型自己说"最贵/最便宜"。
        # 实测 2026-11-11：模型在 recommend 分支里看到"这是榜首"就编出「算最贵的一台」，
        # 而实际排第 3。价格位置是能算的，就必须由代码算完再交给它说。
        if o and ask_price and not ask_detail:
            return _answer_price_position(user_text, o, focus)
        # 「比别的便宜多少」——不是在问这台，也不是要换台，是要比价。
        # 库里只有榜首一台的完整价格，算差价等于让模型编数字，所以直接说清算不了。
        # 实测 2026-11-11：这句原来被当成换台，用户问比价，系统默默换了台机器。
        if o and is_compare:
            reply = ("这个我不给你算。库里只记了每台自己的到手价，"
                     "没有同配置机型的对照价格，算出来的差价是编的。"
                     "%s 现在到手 ¥%s。想比的话，你告诉我具体想跟哪台比，"
                     "我把两台的配置和价格都列出来，你自己一眼就能看出来。"
                     % (o["name"], o.get("price")))
            return {"stage": "compare", "slots": dict(known or {}), "reply": reply,
                    "focus": focus, "focusName": o["name"],
                    "questions": [], "warnings": [],
                    "dataAsOf": core.data_as_of(),
                    "outside_products": [], "untraceable_numbers": [],
                    "fabricated_words": []}
        # 「缺点 / 短板 / 屏幕 / 重量」是细节追问，不是用途匹配 —— 细节优先
        #
        # 🔴🔴 2026-11-17：**模型判了"在问匹配"时，细节必须让位。**
        #
        #    这是"丢弃模型"的最后一处，也是最隐蔽的一处。
        #
        #    实测（DEBUG 打出来的真值）：
        #      「限电 500W」→ detail=True, fit=True, fitq=False
        #      → `if o and ask_detail and not _is_fit_question()` 成立
        #      → 走 detail 分支 → 答"这一项的具体表现要看实机"
        #
        #    `ask_detail` 和 `ask_fit` **同时为 True** 时，原来无条件选 detail。
        #    但模型明确判了 fit=True（在拿用途/要求问这台行不行），
        #    那就是匹配判断，不是细节问答。
        #
        #    为什么加 `not ask_fit` 不会复活旧事故：
        #      2026-11-11 那批是「它保修几年」被 _answer_current 接走、
        #      编出"保修一年"——那种句子模型给 fit=False，不受影响。
        #
        #    判据：detail 和 fit 同时成立 → **fit 优先**（模型说了算）。
        # 🔴 2026-11-21：**参数主题优先于 fit**。
        #
        #    实测：「接口够不够」「散热行不行」模型给 fit=True
        #    （它理解成"问够不够用"），于是 `not ask_fit` 失败，
        #    走了 _answer_current（判用途匹配），答成整机配置 ——
        #    数据里明明有「USB-A ×2、雷电4 ×1」却一个字没提。
        #    而「屏幕怎么样」模型给 fit=False，正常走 followup，答得很好。
        #
        #    判据：**"够不够"问的可能是参数够不够，不一定是用途匹配。**
        #    只要这句问的是某个**参数主题**（_topic_of 认得出），
        #    就该按"问这台的这一面"处理，不让 fit 抢走路由。
        #
        #    反过来，「这个能打游戏吗」「适合学设计吗」——_topic_of 返回 None，
        #    那是真在问用途匹配，继续走 fit 分支。
        _topic_now = _topic_of(user_text)
        _is_param_topic = _topic_now in (
            "接口", "散热", "屏幕", "键盘", "续航", "重量", "颜色",
            "做工", "触控板", "性能", "内存硬盘", "充电")
        if o and ask_detail and (not ask_fit or _is_param_topic) \
                and not _is_fit_question(user_text):
            reply = answer_followup(user_text, _merge_offer(o, (known or {}).get("_askedTopics")))
            return {"stage": "followup", "slots": dict(known or {}), "reply": reply,
                    "focus": focus, "focusName": o["name"],
                    "questions": [], "warnings": [],
                    "dataAsOf": core.data_as_of(),
                    "outside_products": check_outside_products(reply),
                    "untraceable_numbers": [], "fabricated_words": []}
        if o and ask_fit:
            return _answer_current(user_text, o, known or {}, focus)

        # 🔴 2026-11-13 晚：**「已经判定在问这台，却没词命中」必须有兜底。**
        #
        #    原来这里没有兜底：ask_detail / ask_fit / ask_price / is_compare
        #    四个都不命中，就走出了这个 if，一路落到 recommend 把榜首再讲一遍。
        #    实测被漏掉的是（意图=ask_current、refers_to_current=True，词表全不命中）：
        #        「能撑四年不」「带出去累不累」「电池能顶一天吗」
        #        「这机器顶不顶」「卖这么贵值在哪」
        #    用户的感受就是"我问它话，它又把同一台推了一遍"。
        #
        #    为什么不判 ask_fit 而判 answer_followup：
        #      已经确认是在问这台，但**问的是哪一点不知道**。
        #      answer_followup 会按"这台的数据 + 用户原话"回答（它能读原话），
        #      _answer_current 是判用途匹配的，用在"随便问一句"上会硬给一个匹配结论。
        #      拿不准时选信息量更小的那个 —— 至少要答到，不能编。
        if o:
            # 🔴 兜底不许吞"给条件"的句子（M03 实测，2026-11-16 反转后抓到）：
            #    「预算提高到7000，屏幕素质我有要求」→ 模型判 ask_current +
            #    refers_to_current=True 开了 on_current 门，但 asks_about_current
            #    被改数动词否决成 False → 四个闸（detail/fit/price/compare）全空
            #    → 走到这里被**无条件**当成"在问这台"应答，改预算的话被吞。
            #    判据（满足其一就放行到 recommend，让槽位更新接管）：
            #      ① 给条件动词在场且无疑问形态
            #      ② 模型路由明确判了"不是在问这台"（提需求/范围/换台/列清单）
            _give_cond = bool(_GIVE_COND_VERB.search(user_text or "")) \
                and not _QUESTION_FORM.search(user_text or "")
            _lr0 = _LAST_ROUTE[0] or {}
            _model_other = bool(_lr0.get("model_ok")) and _lr0.get("intent") in (
                INTENT_STATE_NEW_NEED, INTENT_STATE_RANGE,
                INTENT_REFUSE_SWITCH, INTENT_LIST_OTHERS)
            # 🔴🔴 2026-11-17：这个兜底**不许吞"模型判了在问匹配"的句子**。
            #
            #    这是 `ask_fit` 改完之后仍然"丢弃模型"的真正原因：
            #    上一层的 `if o and ask_fit:` 在**这个兜底之后**，
            #    而兜底的条件 `not (_give_cond or _model_other)` 对
            #    「限电 500W」成立（没给条件动词、intent 是 ask_current）
            #    → 直接 followup return，`ask_fit` 那行永远走不到。
            #
            #    实测：模型判 `fit=True`（在问匹配），但被这个兜底截胡，
            #    最后答成「这一项的具体表现要看实机或第三方评测」。
            #
            #    修法：兜底加一条 `and not ask_fit` ——
            #    模型说在问匹配，就让控制流落到下面的 `if o and ask_fit`。
            if not (_give_cond or _model_other or ask_fit):
                reply = answer_followup(user_text, _merge_offer(o, (known or {}).get("_askedTopics")))
                return {"stage": "followup", "slots": dict(known or {}), "reply": reply,
                        "focus": focus, "focusName": o["name"],
                        "questions": [], "warnings": [],
                        "dataAsOf": core.data_as_of(),
                        "outside_products": check_outside_products(reply),
                        "untraceable_numbers": [], "fabricated_words": [],
                        "reason": "意图=问当前这台（词表未命中，走兜底应答）"}
            # 放行：这是在改条件。这里**不能**调用任何推荐函数 ——
            # on_current 块之外的主流程（"2. 追问优先"）本来就处理
            # 「改动 + 提问」混句（16:25:59 的 bug 记录），落到那里让
            # 槽位更新正常走。直接不返回，控制流落到 if on_current: 块之外。
            _on_current_fallback = False

    # 2. 追问优先：已知信息够判断，且问的是某一台的细节 → 不重新解析、不重推
    #    放在最前面，避免"问品控"被当成新需求。
    #    但「预算提高到7000，屏幕素质我有要求」这种"改动 + 提问"混在一句里，
    #    不能整体甩给追问，否则预算改了但槽位没变（16:25:59 的 bug）。
    has_new_cond = has_new_condition(user_text)
    # 🔴 2026-11-13 晚（留出集 D）：「这个屏幕不行，换个好点的」被这条吃掉。
    #
    #    「屏幕」命中 FOLLOWUP_KW → 进追问分支 → 把当前这台的屏幕缺点讲了一遍，
    #    然后停住。用户明明说了「换个好点的」，一个字都没被听见。
    #    判据不能只看"有没有问某个参数"，必须同时看"有没有要换" ——
    #    这两件事在一句话里可以同时出现，而**动作是换台**。
    #
    #    为什么用 _is_switch_request 而不是 SWITCH_KW：
    #      「换个好点的」里 SWITCH_KW 的"换个"能中，但换成
    #      「屏幕太烂了，给我找台好的」就不中 —— 统一走那个函数，别在这儿另判一次。
    if (known and core.ready_for_recommendation(known)
            and any(k in user_text for k in FOLLOWUP_KW) and not has_new_cond
            and not _is_switch_request(user_text)):
        res = core.build_recommendation(known)
        if res["ranked"]:
            m = res["ranked"][0]
            reply = answer_followup(user_text, m)
            return {"stage": "followup", "slots": dict(known), "reply": reply,
                    "focus": m["id"], "focusName": m["name"],
                    "questions": [], "warnings": [],
                    "dataAsOf": res["dataAsOf"],
                    "outside_products": check_outside_products(reply),
                    "untraceable_numbers": []}

    # 3. 正常解析
    slots, err = extract_slots(user_text)
    if err:
        return {"stage": "slot_error", "error": err, "slots": {}}

    # 4. 继承规则。实测教训（前后三轮）：
    #    切太狠 →「还有别的品牌吗」被当成新需求，清空条件回来重问品类（死循环）
    #    不切    →「打游戏这个合适吗」把品类改了，预算还留着 7000（串味）
    #    正确做法：逐槽位判断，只覆盖用户真的改了的那个，其它一律继承。
    if known:
        # 用户这轮主动撤销了预算（"预算无所谓了/越便宜越好"），
        # 继承时就不能把旧预算补回来 —— 补回来等于没听懂。
        # 实测 2026-11-11（第五轮）：第一轮 6000，第二轮说"预算无所谓了"，
        # known 兜底又把 6000 拉回来，_cheapest 和 budget 同时存在，自相矛盾。
        budget_revoked = bool(slots.get("_cheapest")) or bool(slots.get("_budget_dropped"))
        # 本轮是在问「能带进教室吗」这类移动性问题时，模型会按 SLOT_SYS 规则 2
        # 把 cat 推成 thin。但这句不是在提新条件，是在问当前那台 ——
        # 采纳它会把游戏本换成轻薄本（M08 回归，2026-11-11）。
        mobility_ask = bool(MOBILITY_ASK.search(user_text) or CARRY_ONLY.search(user_text))
        # 「要带去教室」是携带约束，不是换品类 —— 但用户明确点名品类时，必须听他的
        if CAT_EXPLICIT.search(user_text):
            mobility_ask = False
        # 🔴 2026-11-12（乱测夹具抓到）：品类只许在**用户真的说了品类或用途**时改变。
        #   实测原文：「那换台 RTX4060 的，稳点别跳闸就行」
        #   → 模型把显卡型号当成台式机，cat 从 upgrade 变 desktop，
        #     整个上下文从笔记本切到台式整机。用户只是要一台带独显的笔记本。
        #   判据：句中既没有品类词（轻薄本/游戏本/台式…）也没有用途词（游戏/设计/代码…）
        #   → 保留已知品类，丢掉模型这轮推出来的。
        _purpose_said = any(w in (user_text or "") for w in CAT_PURPOSE_WORDS)
        for k in ("cat", "budget", "purpose", "years", "carry", "dormWatt"):
            if k == "budget" and budget_revoked:
                continue
            if k == "cat" and known.get("cat"):
                if mobility_ask or (not _purpose_said
                                    and not CAT_EXPLICIT.search(user_text)
                                    and slots.get("cat")
                                    and slots["cat"] != known["cat"]):
                    # 保留 known 的品类，丢掉本轮推出来的
                    slots["cat"] = known["cat"]
                    continue
            cur = slots.get(k)
            if cur is None or cur == [] or cur == "":
                if known.get(k) is not None:
                    slots[k] = known[k]
        # 🔴 2026-11-17：**用途和品类冲突时，品类让位**。
        #
        #    实测（用户第二次实测）：用户先问了 MateBook D16（轻薄本），
        #    然后说「我想打游戏」。此时 purpose=['gaming']，但上面那段
        #    把 known.cat='thin' 继承下来了 —— 因为本轮没抽到 cat。
        #    结果推荐的还是轻薄本（红米 Book Pro 14）。
        #
        #    判据：purpose 里出现 gaming，而 cat 是 thin → 用户要的是游戏本。
        #    「打游戏」这个用途本身就决定了品类，不该被上一轮的 cat 压住。
        #
        #    ⚠️ 反过来不成立：purpose 里有 design/code 时 cat 可以是 thin 或 gaming，
        #       那两种都合理，所以不做反向强制。
        _purpose_now = set(slots.get("purpose") or [])
        # 🔴 2026-11-21 修：**用户明确说了品类时，purpose 不许把它改回去**。
        #
        #    实测 bug：已有 cat=gaming / purpose=['gaming']，
        #    用户说「轻薄本」→ extract_slots 正确抽到 cat=thin →
        #    但这段看到 purpose 里还有 gaming，把 cat 又改回 gaming →
        #    用户说"轻薄本"得到的还是那台游戏本，等于没听见。
        #
        #    本意（2026-11-17）是解决另一个问题：用户说「我想打游戏」时，
        #    本轮没抽到 cat，known.cat='thin' 被继承下来 → 推的还是轻薄本。
        #    那种情况是**没抽到 cat**，靠 purpose 推。
        #
        #    判据：只在**本轮没抽到 cat**（或抽到 None）时才按 purpose 推；
        #    本轮明确抽到 cat 就以用户说的为准 —— 用户明说 > 用途推断。
        _cat_from_user = bool(CAT_EXPLICIT.search(user_text or ""))
        if "gaming" in _purpose_now and slots.get("cat") == "thin" \
                and not _cat_from_user:
            slots["cat"] = "gaming"
        # purpose 是累加的：用户补充"偶尔打游戏"不等于放弃"学设计"。
        # 只有明确否掉才移除（"我不玩游戏了"）。
        merged = list(known.get("purpose") or [])
        for x in (slots.get("purpose") or []):
            if x not in merged:
                merged.append(x)
        for drop, kws in PURPOSE_DROP.items():
            if any(w in user_text for w in kws) and drop in merged:
                merged.remove(drop)
        if merged:
            slots["purpose"] = merged
        # 硬约束整组继承。以前是一个一个补：先补了 _minUpgrade，
        # _minRam 和 _excludeBrand 就漏在外面 —— 「要 32G」第二轮就消失了。
        # 现在按组处理，以后新增硬约束记得加进 HARD_KEYS，不要再写单点 if。
        cat_changed = bool(slots.get("cat") and known.get("cat")
                           and slots["cat"] != known["cat"])
        for k in HARD_KEYS:
            if cat_changed:
                # 用户明确改了品类，旧品类的硬约束才允许丢
                slots.pop(k, None)
                continue
            # _cheapest 是"没有预算"的替代状态。用户这轮给了明确金额，
            # 就说明他不接受"看着办"了，不能把这个状态继承下来。
            if k == "_cheapest" and slots.get("budget") is not None:
                continue
            if slots.get(k) is None and known.get(k) is not None:
                slots[k] = known[k]

    # 5. 隐含推导：说打游戏但没明确品类 → 按游戏本走（PRD §8.4）
    #    但已经定了轻薄本、用户只是问"能不能打游戏"时不能改品类 —— 那是追问。
    if not slots.get("cat") and "gaming" in (slots.get("purpose") or []):
        slots["cat"] = "gaming"
    # 「背去教室」「带去图书馆」这类隐含说明是笔记本，不是台式。
    # 实测：用户说「学设计的，五千，要用四年，平时背去教室」，模型没抽 cat，
    # 系统回头问"是笔记本还是台式"—— 用户会觉得没听懂。
    if not slots.get("cat") and any(
            w in user_text for w in ["背去", "带到", "带去", "抱着", "装包",
                                     "上课带", "拿去教室", "图书馆"]):
        slots["cat"] = "thin"
        slots.setdefault("carry", True)

    # 6. 硬性排除条件（"不要封装内存"这种）
    slots = parse_constraints(user_text, slots)
    if known and known.get("_minUpgrade") is not None and slots.get("_minUpgrade") is None:
        slots["_minUpgrade"] = known["_minUpgrade"]

    # 6a5. 独显硬约束（HARD_KEYS 继承）。触发：原话提到独显/独立显卡，
    #      且不是在问句里（"没独显够用吗""这台有独立显卡吗"是追问，不是要求）。
    #      实测 2026-11-12 16:34：「我想要带独立显卡的」之前被捏造成 gaming 用途、
    #      仍推核显机 —— 现在交给 core 的 dgpuCatSwitch 处理（见 core.build_recommendation）。
    if re.search(r"独显|独立显卡", user_text) and not re.search(
            r"(没|没有|无)\s*(独显|独立显卡)"
            r"|(独显|独立显卡)[^，。？?]{0,6}(吗|么)"
            r"|够不?够|需不需要独显", user_text):
        slots["_wantDgpu"] = True
    # 跨轮继承交给上面 HARD_KEYS 的组继承逻辑，这里不做额外处理

    # 6b. 专业要求表（core.match_major → majors.json）
    #     认出的专业决定两件事：内存底线、能不能加装。
    #     不新造机制，直接喂给已有的 _minRam / _minUpgrade 硬约束。
    g, mname = core.match_major(user_text)
    # 🔴 2026-11-18：**已确定的专业不许被单轮悄悄覆盖**。
    #
    #    实测事故（用户实测日志第 8 条）：
    #      第 1 条用户说「我是软件工程专业的」，专业=软件工程，后面 7 条都对。
    #      第 8 条用户问「有没有**机械**革命的同配置的」——
    #      「机械革命」是**笔记本品牌**，但专业别名表里有个 '机械'
    #      → match_major 返回「机械设计制造及其自动化」
    #      → 专业被覆盖，硬约束从「16G 起、要能加装」变成「32G 起、要独显」
    #      → 推荐逻辑整个变了，用户看到的是莫名其妙的要求。
    #
    #    根因有两层：
    #      ① 别名表里 '机械' 太宽（已修：删掉，只留「机械设计/机械制造」等）
    #      ② 就算匹配对了，**单轮提到的专业也不该覆盖已确定的专业** ——
    #         用户可能只是在引用一个品牌名/产品名。
    #
    #    判据：known 里已有专业，而本轮匹配到的是**另一个**专业时：
    #      · 用户原话里带明确的「我是学/我专业是/我读」这类声明 → 允许改
    #      · 否则保留原专业，只是本轮不新增约束
    _MAJOR_DECLARE = re.compile(
        r"(我是学|我学|我专业是|我读|就读|学的|专业是|主修)")
    if g and known and known.get("_majorId") \
            and g.get("id") != known.get("_majorId"):
        if not _MAJOR_DECLARE.search(user_text or ""):
            # 不是明确声明换专业 → 保留原来的
            g = next((x for x in (core.majors_data().get("groups") or [])
                      if x.get("id") == known["_majorId"]), None)
            mname = known.get("_majorName") or mname
    if g is None and known and known.get("_majorId"):
        g = next((x for x in (core.majors_data().get("groups") or [])
                  if x.get("id") == known["_majorId"]), None)
        mname = known.get("_majorName") or mname
    if g:
        slots["_majorId"] = g.get("id")
        slots["_majorGroup"] = g.get("name")
        slots["_majorName"] = mname
        req = g.get("req") or {}
        ram_min = int(req.get("ramMin") or 0)
        if ram_min:
            slots["_minRam"] = max(int(slots.get("_minRam") or 0), ram_min)
        for gate in g.get("hardGates") or []:
            if gate.get("dim") == "upgrade" and gate.get("min"):
                slots["_minUpgrade"] = max(int(slots.get("_minUpgrade") or 0),
                                           int(gate["min"]))
            # 🔴 2026-11-18：**GPU 硬约束**。这一条之前完全没有。
            #
            #    实测事故（用户实测日志第 10-15 条）：
            #      用户说「车辆工程专业」→ 专业要求 gpu=discrete / vramMin=4
            #      → 系统在回答里**自己都说**「要独立显卡（4G 显存起）」
            #      → 却连续推荐两台核显机（ThinkBook 16+ / Redmi Book Pro 14）
            #      → 用户指出「你说我这个专业需要显卡但是给我推荐了个没有独显的」
            #      → 换一台后**还是核显**
            #
            #    根因：`req.gpu` / `req.vramMin` / `hardGates[dim=gpu]`
            #    这三项**只被用来拼文案**（见 _major_brief），
            #    从来没有落进 slots 当筛选条件。
            #    所以系统"嘴上说要独显，筛的时候不看"。
            #
            #    修法：把 GPU 要求落成 `_minVram`（显存下限，0 表示只要独显）
            #    + `_wantDgpu`（只要有独显就行），
            #    由 core.build_recommendation 真正过滤。
            if gate.get("dim") == "gpu" and gate.get("min"):
                slots["_wantDgpu"] = True
        if (req.get("gpu") or "").lower() == "discrete":
            slots["_wantDgpu"] = True
        vram_min = int(req.get("vramMin") or 0)
        if vram_min:
            slots["_minVram"] = max(int(slots.get("_minVram") or 0), vram_min)

    miss = core.missing_required(slots)
    assume_note = []
    # 🔴 2026-11-17：**有 focus 且在问细节时，不许先问槽位。**
    #
    #    实测：`run('有别的颜色吗', focus='zol-2130961')` 返回 clarify
    #    「是笔记本还是台式？」—— 用户明明已经在问这台的颜色了，
    #    系统却回头问最基础的问题。原因是 focus 只带了 id、没带槽位，
    #    `missing_required(slots)` 缺「品类」→ 触发 clarify。
    #
    #    判据：`refers_to_current` 为真（在说当前这台）且
    #          `asks_about_current` 为真（在问这台的某一面）
    #          → 直接答细节，跳过槽位收集。
    #
    #    ⚠️ 为什么不干脆「有 focus 就跳过」：用户说「预算 8000」这种
    #       加条件的话时，focus 也在、但不是问细节，那种该继续收集/重推。
    if miss and focus and refers_to_current(user_text, focus) \
            and asks_about_current(user_text):
        _o = core.get_offer(focus)
        if _o:
            reply = answer_followup(user_text, _merge_offer(_o, (known or {}).get("_askedTopics")))
            return {"stage": "followup", "slots": dict(known or {}),
                    "reply": reply, "focus": focus, "focusName": _o["name"],
                    "questions": [], "warnings": [],
                    "dataAsOf": core.data_as_of(),
                    "outside_products": check_outside_products(reply),
                    "untraceable_numbers": [], "fabricated_words": []}
    if miss:
        asked = list(asked or [])
        fresh = [m for m in miss if m not in asked]
        if fresh:
            m0 = fresh[0]
            # 必须把这一轮已经抽到的槽位带回去，否则下一轮从零开始。
            # 实测 2026-11-11：原来这里不返回 known，
            # 「7000 的轻薄本要 32G」→ clarify → 下一轮 _minRam=32 和 budget=7000 全丢，
            # 「换一台」时硬约束消失，推出来的机器根本不满足用户说过的条件。
            return {"stage": "clarify", "slots": slots, "missing": miss,
                    "asked": asked + [m0], "focus": focus,
                    "known": dict(slots),
                    "reply": ASK_TEMPLATE.get(m0, "能多说一点吗？")}
        # 每一项都问过了还答不上来 —— 不再问，按默认值往下走
        slots, assumed = apply_defaults(slots)
        assume_note = [DEFAULT_NOTE[a] for a in assumed if a in DEFAULT_NOTE]

    # 6c0. 这一轮到底有没有改动条件 —— 兜底（6e/6f）全靠它判断"用户是不是真说了新东西"。
    #   🔴 2026-11-12：原来只在 6e 里算了一次，6f 没算，于是「限电 500W」这种
    #     确实加了条件的句子被当成"什么都没改"，回了一句一模一样的兜底话（M09 死循环）。
    _delta = True
    if known:
        _delta = any(
            slots.get(k) != known.get(k)
            for k in ("cat", "budget", "purpose", "years", "carry", "dormWatt",
                      "_minRam", "_minUpgrade", "_majorId"))

    # 6c1. 用户只回了个序号（「1」「①」）——**不猜它是哪个意思**，直接把按钮给他。
    #   为什么不猜：同一个「①」在两种反问里指的不是同一件事
    #   （澄清里 ①是换一台，兜底里 ①是对比），猜错就是第三次没听懂。
    #   实测 2026-11-12：用户连打 1 → 系统连问 4 遍同一句，卡死。
    if (known and core.ready_for_recommendation(known)
            and re.fullmatch(r"\s*[①②③1-3]\s*", user_text or "")):
        return {"stage": "clarify", "slots": dict(known), "missing": [],
                "asked": list(asked or []), "focus": focus, "known": dict(known),
                "suggest": ["把它和另外两台放一起比", "说说当前这台的短板", "换一台"],
                "reply": "不用打数字，直接点下面其中一个就行。"}

    # 6c2. 🔴 对比：用户说「对比 / 比一下 / 这台和另外两台」→ 直接摆出来。
    #   为什么必须在 6e/6f 之前：那两处只会反问「比哪两台」，
    #   而反问里给的选项又正好是"对比"，用户点了还是反问 —— 死循环就是这么来的
    #   （实测 2026-11-12：连续 4 轮同一句话）。
    if (known and core.ready_for_recommendation(known)
            and COMPARE_ASK.search(user_text or "")):
        _cres = core.build_recommendation(known)
        _rows = (_cres.get("ranked") or [])[:3]
        if len(_rows) >= 2:
            return {"stage": "compare", "slots": dict(known),
                    "reply": _compare_text(_rows),
                    "focus": focus, "focusName": None,
                    "questions": [], "warnings": [],
                    "dataAsOf": _cres.get("dataAsOf"),
                    "outside_products": [], "untraceable_numbers": [],
                    "known": dict(known)}

    # 6e. 🔴 兜底方向：听不懂的时候要**问**，不能装作听懂了直接动手。
    #
    # 为什么这条比再加十个意图分支都重要（2026-11-12 用户原话：
    # 「按你的思路还是去列举所有可能的说法…没有真正的扛得住我乱测的方法吗」）：
    #   意图分支是穷举的，用户的说法是无限的。只要"没认出来"的默认动作是**行动**
    #   （这里是 build_recommendation → 把首位再讲一遍），
    #   每一句没写过的说法就都会表现成"答非所问"。今天四个 bug 全是这个形状。
    #   反过来，把默认动作改成**反问**，同样没认出来最多是"多问一句"，
    #   而不是"自信地做错事"。这是唯一不靠穷举的兜底。
    #
    # 触发条件收得很紧，避免把正常轮次也变成反问：
    #   · 已经在对话中（known 齐全）
    #   · 意图判成 unknown
    #   · 这一轮没有改动任何槽位（改了就说明听懂了）
    #   · 不是换台/比价/确认这台，也不是"谢谢/算了"这类客套
    if (known and core.ready_for_recommendation(known)
            and not want_switch and not is_compare):
        _intent = classify_intent(user_text, focus)
        _han = len(re.findall(r"[\u4e00-\u9fa5]", user_text or ""))
        # 条件有没有变，用 6c0 算好的那份，别在这儿重算一遍（判据抄两遍必漂）
        #
        # 🔴 2026-11-13 晚：`_soft` 的**动作**改了（留出集 C「好的我知道了」抓到）。
        #    原来它的作用是"命中就跳过反问，继续往下走"——而往下走就是推荐。
        #    于是用户说「好的我知道了」（纯附和，没有新信息），
        #    系统又把惠普战 66 从头讲了一遍，配置、短板、售后一样不落。
        #    用户刚说"我知道了"，得到的回答是"我再给你讲一遍"。
        #
        #    这不是"多问了"和"少问了"的差别，是**没听懂还硬要办事**。
        #    正确动作：客套就承接一句（social 的 smalltalk），不要往下推。
        #    `_soft` 判据本身没错（词在句子里），错的是命中之后干了什么。
        #
        # 🔴 词表补了「明白了 / 了解 / 知道了 / 懂了」（2026-11-13 晚，同上）。
        #    原来只有"好的/行吧/谢谢/嗯/收到"，于是「明白了」「我知道了」不在表里
        #    → 不进客套分支 → 一路落到推荐，把同一台再讲一遍。
        #    这几个词和"好的"是同一类东西：**他听懂了我的话，没有提出新要求**。
        _soft = any(w in (user_text or "") for w in
                    ("谢谢", "多谢", "好的", "行吧", "算了", "嗯", "收到",
                     "明白了", "了解", "知道了", "懂了"))
        # 「还有别的品牌吗」是换品牌，不是没听懂 —— 不能拦成反问（M04 回归）
        _brand = any(w in (user_text or "") for w in ("品牌", "牌子"))
        # 把原来说过的条件**又完整说了一遍**（"学设计的，预算5100，要带去教室"）
        # 不是"没听懂"，是"再说一次"——实测 10:28 那轮被拦成反问，用户当场懵。
        # 判据：这句话自己带着预算和用途，就按新需求/重申处理，不许反问。
        #
        # 🔴 2026-11-13 晚：原来写成 `bool(slots.get("budget")) and bool(slots.get("purpose"))`，
        #    读的是**槽位里有没有**，而不是**这句话里有没有**。
        #    槽位是跨轮累积的：聊过一轮之后 budget/purpose 永远非空，
        #    于是 `_restate` 恒为 True，反问闸被永久短路 —— 实测：
        #        「。。。」 → _restate=True → 跳过反问 → 去推荐了机器
        #    用户发了三个句号，系统热情地讲了一遍惠普战 66。
        #
        #    `_restate` 本来要表达的是"用户**又完整说了一遍**条件"（原句里带预算+用途），
        #    必须从**原话**判，不能从槽位判。改回原话。
        _restate = bool(_budget_in_text(user_text or "")) and any(
            w in (user_text or "") for w in
            ("上课", "办公", "打游戏", "设计", "剪辑", "编程", "写代码", "宿舍", "学习"))
        # 🔴 2026-11-13 晚：「。。。」「……」「??」这类**纯标点/纯符号**必须走反问。
        #
        #    原来门槛是 `_han >= 4`（至少 4 个汉字才拦成反问），于是纯标点 han=0
        #    被这个门槛挡在外面，一路落到 recommend —— 用户发了三个句号，
        #    系统热情洋溢地把榜首又讲了一遍。这是"自信地做错事"，比反问糟得多。
        #    实测：intent_layer 判得没错（unknown），被拦在这个数值条件上。
        #
        #    判据改成：`_han >= 4 or _han == 0`
        #      · han == 0 → 一个字都没有，必然没听懂 → 反问
        #      · han 1~3  → 可能是"嗯""好的""行"这类附和，不拦（_soft 另有处理）
        #
        # 🔴 2026-11-13 深夜（留出集 D「随便吧」）：`_han >= 4` 这道门槛
        #    把 3 个字的交权句挡在外面了。「随便吧」「都行吧」「随你吧」
        #    只有 3 个字，进不来，于是一路落到推荐。
        #    但它们和"嗯"不一样：
        #      「嗯」      = 我听你说完了（附和，不办事也对）
        #      「随便吧」  = 我不管了，你定（**交权**，必须给一个动作）
        #    判据：`_assign`（把决定权交出来）单独认一遍，不受字数门槛限制 ——
        #    这是封闭句式，短句也认得出，不需要靠长度猜。
        _assign = bool(re.fullmatch(
            r"\s*(随便|随你|都行|你看着办|你定|你决定|听你的|你说呢)"
            r"\s*[吧啊呀。！？?!]*\s*", user_text or ""))
        # 🔴 2026-11-13 深夜（M11 回归）：**"征求意见"不许反问**。
        #
        #    M11 的第二轮是「你说呢」，它要的是
        #      「条件没改，还是刚才那台 X（到手 ¥N）。要我做点别的吗？」
        #    —— 一句实质承接，把当前这台再确认一遍，然后交回选择权。
        #    而反问闸回的是「你说「你说呢」，我不敢瞎猜 —— 你想做哪一件？」，
        #    用户问"你说呢"，系统答"你说你想干嘛" —— 等于把问题原样推回去。
        #
        #    这和「你看着办吧」不同：
        #      「你看着办吧」= 我不管了 → 反问一次、给选项，是帮他收口
        #      「你说呢」    = 我想听你的 → **应当给出意见**，不是再问他
        #    判据：含"你说/你觉得/你看呢/依你"就是征求意见，不给反问，
        #    让它落到下面那条"条件没改，还是刚才那台"的实质承接。
        #
        # 🔴 2026-11-13 深夜补第二道闸（D 集「你觉得呢」回归）：
        #    **没有 focus 时不算征求意见** —— 没有"这台"可评，
        #    "你觉得呢"就是一句空转，该反问。
        #    D 集就是这种场景，我第一版把它也放过了，于是去推了一台机器。
        #    判据：征求意见需要**有一个对象可评**。有 focus 才算。
        _asks_opinion = bool(focus and re.search(
            r"你说呢|你说吧|你觉得呢|你看呢|依你|你觉得怎么样|你说好不好",
            user_text or ""))
        if ((_intent == INTENT_UNKNOWN and not _delta
             and (_han >= 4 or _han == 0 or _assign))
                and not _brand and not _restate and not _asks_opinion
                and not CONFIRM_CURRENT.search(user_text or "")):
            # 🔴 客气话不反问，但也**不许往下推机器** —— 用 social 承接一句。
            #
            #    这一段是 2026-11-13 晚补的（留出集 C「好的我知道了」）。
            #    改之前 `_soft` 命中就直接 `not _soft` 为假 → 跳过反问 → 落到
            #    最后的推荐模板，同一台机器原封不动再讲一遍。
            #    用户说"我知道了"，系统答"我再讲一遍给你听" —— 这是明着没听懂。
            #
            #    为什么这里用 social 而不是 clarify：
            #      clarify 是"我没听懂，你想干哪件"，对一个刚说"知道了"的人是冒犯；
            #      smalltalk 回的是"嗯。接着刚才的聊，还是换个条件？" ——
            #      既接住了这句，又没丢上下文，也没重推机器。
            if _soft:
                return {"stage": "social", "slots": dict(known),
                        "social": "smalltalk", "focus": focus,
                        "reply": social_reply("smalltalk", known=known,
                                              last_stage=last_stage),
                        "focusName": None, "picked": None,
                        "questions": [], "warnings": [],
                        "suggest": (["换一台", "把其余候选列出来"] if focus
                                    else ["预算 5000，上课用"]),
                        "dataAsOf": core.data_as_of(),
                        "seen": list(seen or []), "known": dict(known),
                        "outside_products": [], "untraceable_numbers": [],
                        "fabricated_words": []}
            # 🔴 反问必须**复述用户的原话**，再给贴着这句话的选项。
            #   第一版只会念「① 列清单 ② 换一台 ③ 问参数」——
            #   用户说「再加点钱上独显」，得到的是一张无关的菜单，等于第二次没听懂。
            #   （2026-11-12 乱测夹具产出的原句：「那能不能把预算放宽点，再加点钱上独显？」）
            _hw = any(w in (user_text or "") for w in
                      ("独显", "独立显卡", "RTX", "GTX", "显卡", "显存"))
            _opts = (["只看带独显的机型", "提高预算后重排", "先说说当前这台的短板"]
                     if _hw else
                     ["换一台", "把其余候选列出来", "说说当前这台某个参数"])
            return {"stage": "clarify", "slots": dict(known), "missing": [],
                    "asked": list(asked or []), "focus": focus,
                    "known": dict(known), "suggest": _opts,
                    "reply": "你说「%s」，我不敢瞎猜 —— 你想做哪一件？"
                             % (user_text or "").strip()[:20]}

    # 🔴 2026-11-13 晚：品牌换台必须先于"要清单"。
    #
    #    原来两处各写一遍判据：这里 `if LIST_OTHERS_PAT`，下面 6d 里
    #    `if BRAND_SWITCH and not BRAND_PRICE_Q`。因为顺序是"先清单"，品牌两类一直没打架 ——
    #    直到这轮把 LIST 判据放宽（加"还有几个"/"候选…都看"），
    #    「还有别的品牌吗」同时命中两者，被清单分支抢走：
    #    用户要的是**换个牌子**，系统给他把同品牌的剩下几台列了一遍。
    #
    #    正确的优先级：**换品牌 > 列清单**。
    #    理由不是"哪个更重要"，而是"哪个更具体"：说"别的品牌"是在排除一个维度，
    #    说"列出来"只是要更多信息。具体的排除必须先生效。
    _brand_switch = bool(focus and BRAND_SWITCH.search(user_text or "")
                         and not BRAND_PRICE_Q.search(user_text or ""))
    # 🔴 2026-11-13 深夜（留出集 D「就这些？」）：判据升级为 **规则 OR 意图层**。
    #
    #    「就这些？」意图层判 list_others（对），但 LIST_OTHERS_PAT 认不出
    #    —— 那是个问句，不是"列出来"这类动词句式。于是走了 recommend，
    #    把当前这台又讲一遍。用户问"你就这么点东西？"，得到的是同一台。
    #
    #    和 want_switch 是同一套接法（保持一致性，别一处接一处不接）：
    #    规则先判（确定、零延迟），规则说不列再问意图层。
    _want_list = bool(LIST_OTHERS_PAT.search(user_text or ""))
    if not _want_list:
        try:
            import intent_layer as _il_ls
            _ls_lab, _ls_why = _il_ls.classify(user_text, focus, allow_model=True)
            _want_list = (_ls_lab == INTENT_LIST_OTHERS)
        except Exception:
            pass
    if _want_list and not _brand_switch:
        base = known if (known and core.ready_for_recommendation(known)) else slots
        if core.ready_for_recommendation(base):
            _res = core.build_recommendation(base)
            _rest = (_res.get("ranked") or [])[1:]
            if _rest:
                _txt = _list_others_reply(_rest, base)
                return {"stage": "followup", "slots": dict(base), "reply": _txt,
                        "focus": focus, "focusName": None,
                        "questions": [], "warnings": [],
                        "dataAsOf": _res.get("dataAsOf"),
                        "outside_products": [],
                        "untraceable_numbers": []}

    # 7. 「这台适不适合我这个用途」—— 有焦点时先答匹配度，不盲目换品类。
    #    16:27 那次就是在这里翻车的：用户问"打游戏这个合适吗"，
    #    系统直接换成游戏本，等于替他做了决定，但他要的是"帮我判断一下"。
    if on_current and known and known.get("cat") and focus:
        new_pur = slots.get("purpose") or []
        cat_changed = slots.get("cat") and slots["cat"] != known.get("cat")
        if not cat_changed and any(k in user_text for k in FIT_KW):
            o = core.get_offer(focus)
            if o:
                return _answer_current(user_text, o, slots, focus)

    # 注意：这里**不许重算** want_switch —— 上面 0b 已经算过一次，
    # 那一份是「规则 OR 意图层」。在这里再调一次 _is_switch_request
    # 会把意图层那一票丢掉，于是同一句"这个价有点离谱了吧"上面判换台、
    # 下面判不换台，最后照样不换（判据抄两遍必漂，宪法第 9 条）。
    # 原来这行是 `want_switch = _is_switch_request(user_text)`，属于历史遗留。

    # ── 6d2. 「放宽预算」必须真的放宽（2026-11-13，用户报的真 bug）──────
    # 日志 chat-2026-11-13 第 71→72 条：
    #   71 exhausted：「这个条件下库里就这几台，都看过了。
    #                  要不放宽预算，或者换个品类我再看看？」
    #   72 用户：「可以，放宽预算推荐几台」
    #   → 系统把同一台战 66 又推了一遍。
    #
    # 两处都错：
    #   ① 槽位里的 budget 没动（还是 7000）—— 池子根本没变
    #   ② exclude 只挂给「换一台」，这句不算换台 → 已看过那三台全部重新参选，
    #      而它们在 7000 以内仍是第一名，于是首页又是它
    #
    # 🔴 最重要的一点：**这是系统自己提的建议，然后自己没接住。**
    #    用户照着提示做了，得到的却是原地打转 —— 之后就不会再信那些建议了。
    #
    # 🔴 2026-11-13 回归时补的闸（test_multiturn M03 抓到）：
    #    「预算提高到7000」这种句子，**同时**命中"放宽"和"给了明确数字"。
    #    放宽分支原来无条件按 +20% 算，把用户亲口说的 7000 改成 8000 ——
    #    用户给的数字被系统自己改掉，这比不推荐更严重。
    #    所以：**原话里有金额就以原话为准，放宽动作让位。**
    #    "放宽"只负责表达"可以多花钱"这个态度，具体多少钱由用户说了算。
    #
    # 🔴 2026-11-13 晚：这一段改为走 budget_intent 的协作层。
    #    原因：单靠正则词表，开放式说法一律听不见 ——
    #      「手头松了点」「奖学金到账了」「不用给我省」
    #    实测这三类句子规则只有 50%，而协作层（规则确定时用规则、
    #    不确定时问模型）是 83%。改法的关键是**规则先说话**：
    #    数字由规则从原话抽（可追溯），模型只在"规则没认出任何信号"时兜底。
    #    模型永远不负责给出金额（见 budget_intent.classify_budget）。
    _old_budget = slots.get("budget")
    _budget_raised = False
    _explicit_budget = bool(_budget_in_text(user_text or ""))
    try:
        import budget_intent as _bi
        _budget_action, _budget_why = _bi.classify_budget(user_text)
    except Exception:
        # 协作层出任何问题都退回纯规则 —— 不许因为它挂掉而让整轮失败
        _budget_action = "relax" if is_relax_budget(user_text) else "none"
        _budget_why = "fallback:纯规则"
    _relaxed = (_budget_action == "relax")

    if _relaxed and _old_budget and not _explicit_budget:
        _nb = relaxed_budget(_old_budget)
        if _nb and _nb != _old_budget:
            slots = dict(slots)
            slots["budget"] = _nb
            _budget_raised = True
            # 上一轮 exhausted 的「都看过了」，指的是**旧预算下**都看过了。
            # 预算一变那份结论就作废 —— 但作废的方式**不是把 seen 清零**：
            # 试过清零，结果 8000 区间只多一台新机时，战 66（5009，用户早看过）
            # 又回到候选里当了第一名，等于原地打转照旧。
            # 正确做法是「预算变了所以不会再判 exhausted」（见 §6d 的条件依赖
            # want_switch，这句不算换台），seen 一律保留 —— 看过就是看过，
            # 放宽预算不构成"没看过"。

    # 「还有别的品牌吗」= 换品牌，不是换台也不是没听懂。
    # 做法：把当前这台的品牌整组排除，交给内核重新排（不自己挑机器）。
    #
    # 🔴 2026-11-13：exclude 原来只在 want_switch 时才给（`seen if want_switch else None`）。
    #    结果是**任何"没改条件但要新建议"的说法都拿不到排除表** ——
    #    「放宽预算推荐几台」正是这种。用户明确要"几台"，系统把看过的那台又端上来。
    #
    #    改判据：只要这一轮**不是纯追问某台细节**，就把 seen 挂上。
    #    为什么不做成"永远挂"：「这台屏幕怎么样」这种追问要走 focus 分支，
    #    把 seen 也排掉会让它找不到当前这台（focus 本身在 seen 里）。
    #    所以精确一点：want_switch / 放宽预算 / 明确要"几台" → 挂 seen。
    #    注意这里用的是 `_relaxed`（听懂了"放宽"这个意思），不是
    #    `_budget_raised`（真的放宽了）。「预算提高到7000」也算"要新结果"，
    #    该把看过的排掉 —— 只是钱按用户说的 7000 算。
    _wants_more = _relaxed or bool(re.search(
        r"推荐几台|来几台|多给几台|再推|列几台|几个选择|都列|全部列出", user_text or ""))
    _excl = seen if (want_switch or _wants_more) else None
    if focus and BRAND_SWITCH.search(user_text or "") \
            and not BRAND_PRICE_Q.search(user_text or ""):
        _cur = core.get_offer(focus) or {}
        _b = _cur.get("brand")
        if _b:
            _same_brand = [o["id"] for o in core.merged_offers()
                           if o.get("brand") == _b]
            _excl = list(dict.fromkeys(list(_excl or []) + _same_brand))
    result = core.build_recommendation(slots, exclude=_excl)
    # 内核因"要独显"切了品类时，本地槽位必须跟着切 —— 否则返回值里
    # slots 还是 thin，下一轮继承回去，切品类这件事每轮重演一遍。
    if result.get("dgpuCatSwitch"):
        slots = result.get("slots") or slots
    result["slots"] = slots

    # 6f. 🔴 同一台不许连着推两遍 —— 不依赖意图判断的第二道保险。
    #
    # 6e 只能拦住"判成 unknown"的句子；「你说呢」「这两个比一下」这种
    # 被判成别的意图、又没改任何条件的，照样会把首位的卡片再刷一遍。
    # 用户看到的就是"怎么又是它"。
    # 判据很简单：**首位 == 上一轮那台，且这一轮什么条件都没改** →
    # 不要重新推荐，改成问一句"你想让我做什么"。
    # 这条不猜用户想干嘛，只禁止一件不该发生的事（宪法第 3 条：宁可弃权）。
    if (focus and not want_switch
            and result.get("ranked")
            and result["ranked"][0]["id"] == focus
            # 条件变了（「限电 500W」这种）就不是"没听懂"，该按新条件重排 —— 不许拦成兜底
            and not _delta
            and not any(k in (user_text or "") for k in FIT_KW)
            and not any(k in (user_text or "") for k in FOLLOWUP_KW)
            and not LIST_OTHERS_PAT.search(user_text or "")):
        _same = result["ranked"][0]
        # 这里是最后一道兜底：正常的对比请求已经在 6c2 处理掉了，
        # 能走到这里说明连两台都凑不出来 —— 直接说清楚，不要再问"比哪两台"（那是死循环的入口）。
        if is_compare:
            return {"stage": "followup", "slots": dict(slots),
                    "reply": "这台是当前条件下唯一的一台，没有可对比的第二台。"
                             "把预算放宽一点，或者换个品类，我再给你找几台放一起。",
                    "focus": focus, "focusName": _same["name"],
                    "questions": [], "warnings": [], "dataAsOf": result.get("dataAsOf"),
                    "outside_products": [], "untraceable_numbers": [],
                    "seen": list(seen or []) + [focus]}
        return {"stage": "followup", "slots": dict(slots),
                "reply": "条件没改，还是刚才那台 %s（到手 ¥%s）。要我做点别的吗？"
                         % (_same["name"], _money(_same.get("price"))),
                "suggest": ["把它和另外两台放一起比", "说说它最要紧的短板", "换一台"],
                "focus": focus, "focusName": _same["name"],
                "questions": [], "warnings": [], "dataAsOf": result.get("dataAsOf"),
                "outside_products": [], "untraceable_numbers": [],
                "seen": list(seen or []) + [focus]}

    if assume_note:
        result["warnings"] = list(result["warnings"]) + [
            "信息没问全，" + "、".join(assume_note) + "给的推荐"]

    # 「已经看过哪些」必须写回给前端，否则下一轮 exclude 又是空的。
    # 实测 2026-11-11：用户说「这台不行，换一个」，系统把同一台又推了一遍 ——
    # 根因就是 seen 只读不写，前端永远拿到 None，"换一台"等于原地打转。
    seen_now = list(seen or [])
    for r in result["ranked"]:
        if r["id"] not in seen_now:
            seen_now.append(r["id"])

    # 换一台但池子已经翻完了
    if want_switch and not result["ranked"]:
        return {"stage": "exhausted", "slots": slots, "picked": None,
                "reply": "这个条件下库里就这几台，都看过了。要不放宽预算，或者换个品类我再看看？",
                "questions": [], "warnings": [], "dataAsOf": result["dataAsOf"],
                "seen": seen_now, "known": slots, "focus": None}

    # 追问模式：已经在讨论某一台，问的是细节 —— 不重推、不重复卡片。
    # 但条件变了（预算提高/换了要求）就不算追问，必须按新条件重新推。
    if (result["ranked"] and not want_switch and not has_new_condition(user_text)
            and is_followup(user_text, slots)):
        m = result["ranked"][0]
        reply = answer_followup(user_text, m)
        return {"stage": "followup", "slots": slots, "reply": reply,
                "focus": m["id"], "focusName": m["name"],
                "questions": [], "warnings": [],
                "dataAsOf": result["dataAsOf"],
                "seen": seen_now, "known": slots,
                "outside_products": check_outside_products(reply),
                "untraceable_numbers": []}

    if result["refuse"] and not result["ranked"]:
        return {"stage": "refuse", "slots": slots, "reply": result["refuse"],
                "result": result, "focus": focus}

    reply, fabricated = compose(user_text, result) if not want_switch else (template_reply(result["ranked"][0]), [])
    # 🔴 价格口径的**出口校正**（2026-11-16 接 ZOL 后加，见 _price_label 的注释）。
    #
    #    为什么不能只靠提示词：实测把数据里的键名改成「平台标价（不含国补/券）」后，
    #    模型照样输出「这台 ThinkBook **到手价** 4898 元」。它念的是自己习惯的词，
    #    不是键名。而「标价说到手价」属于**数字全对、口径全错**，用户不会怀疑。
    #
    #    所以判据落在代码上：榜首那台的价格是快照（priceIsEstimate）时，
    #    文本里出现的「到手价」一律改成「平台标价」，并在末尾补一句说明。
    #    ⚠️ 只校正**榜首那台**的价格口径 —— 备选只给名字不给价，
    #       而且这个替换只动"到手价"这个词，不改任何数字。
    _first = (result.get("ranked") or [{}])[0]
    if _first.get("priceIsEstimate"):
        # ⚠️ 不能只匹配「到手价」三个字。实测模型会换着说：
        #      「到手价 4898 元」/「到手 ¥4898」/「到手4898」
        #    首版只认第一种，第二次跑就漏了（那次它说的是「到手 ¥4898」）。
        #    用 `到手\s*价?` 一次覆盖全部变体。
        _new = re.sub(r"到手\s*价?", "平台标价", reply)
        if _new != reply:
            reply = _new
            if "不含国补" not in reply:
                reply = reply.rstrip() + "\n（这个价是平台标价快照，不含国补和平台券，不是到手价。）"
            # 改了就重核：替换只动措辞不动数字，但规矩是"改了就重核"。
            untraceable = verify_answer(reply, result, user_text)
    untraceable = verify_answer(reply, result, user_text)
    outside = check_outside_products(reply)

    # 🔴 用途撞品类：这句必须由代码写在最前面，不交给模型（见 _gaming_conflict_note）。
    #   放在 verify_answer 之后是有意的：它是代码生成的可信文本，
    #   数字取自 slots 的预算和 result 里的价格，不需要再过一遍追溯。
    note = _dgpu_switch_note(slots, result) or _gaming_conflict_note(slots, result)
    if note:
        reply = note + reply
    # 带出门：同品类比重量（不换品类、不点名别家），见 _carry_note
    carry = _carry_note(slots, result)
    if carry:
        reply = reply + carry
    # 专业要求：这台差在哪，必须有依据地说出来（majors.json）
    mnote = _major_note(slots, result)
    if mnote:
        reply = reply + mnote

    out = {"stage": "recommend", "slots": slots, "reply": reply,
           # 固定字段版回答（前端主展示）。正文不再当主视图 —— 见 answer_card 的说明。
           "answer": answer_card(result, slots, note=note, carry=carry, mnote=mnote),
           "questions": result["questions"], "warnings": result["warnings"],
           "dataAsOf": result["dataAsOf"], "mode": result["mode"],
           "top": [r["name"] for r in result["ranked"]],
           "untraceable_numbers": untraceable,
           "outside_products": outside,
           "fabricated_words": fabricated,
           "picked": result["ranked"][0]["name"] if result["ranked"] else None,
           "focus": result["ranked"][0]["id"] if result["ranked"] else None,
           "focusName": result["ranked"][0]["name"] if result["ranked"] else None,
           "seen": seen_now,
           "result": result}
    if verbose:
        print(json.dumps({k: v for k, v in out.items() if k != "result"},
                         ensure_ascii=False, indent=2))
    return out
